// TRUCK CONVOY MODE
// ============================================================
// Truck = stort fordon som rör sig framåt. Spelare står på det och försvarar.
// Truck har 7 turret-positions med olika vapen. När en spelare står på en turret,
// får de det vapnet automatiskt (deras egna vapen återgår när de kliver av).

const TRUCK_TURRETS = [
  { id: 't_rocket',  offsetX: -90, offsetY: -32, weaponId: 'rocket',   icon: '🚀', label: 'Raketgevär' },
  { id: 't_minigun', offsetX:  60, offsetY: -32, weaponId: 'minigun',  icon: '🔫', label: 'Minigun' },
  { id: 't_sniper',  offsetX: -90, offsetY:   0, weaponId: 'sniper',   icon: '🎯', label: 'Prickskyttegevär' },
  { id: 't_flame',   offsetX:  60, offsetY:   0, weaponId: 'flame',    icon: '🔥', label: 'Eldkastare' },
  { id: 't_repair',  offsetX: -90, offsetY:  32, weaponId: 'repair',   icon: '🔧', label: 'REPARERA — spamma för att laga trucken' },
  { id: 't_grenade', offsetX:  60, offsetY:  32, weaponId: 'grenade',  icon: '💣', label: 'Granatkastare' },
  { id: 't_railgun', offsetX:   0, offsetY:   0, weaponId: 'railgun',  icon: '🌟', label: 'Railgun (förar-plats)' },
];

// Försök claima en turret (host-validerad)
function tryMountTurret(turretId) {
  if (!state.truck) return;
  const tr = state.truck.turrets.find(x => x.id === turretId);
  if (!tr) return;
  // Toggle dismount om redan på samma
  if (state.player._mountedTurretId === turretId) {
    state.player._mountedTurretId = null;
    if (Coop.active && Coop.isHost) tr.occupiedBy = null;
    if (Coop.active && !Coop.isHost) Coop.sendToHost({ type: 'mount_req', tid: null });
    return;
  }
  // Kolla om turret är tagen av någon annan
  const myId = Coop.active ? (Coop.isHost ? 'host' : Coop.myId) : null;
  if (Coop.active && tr.occupiedBy && tr.occupiedBy !== myId) {
    showToast('Upptagen av annan spelare!');
    Audio.uiClick();
    return;
  }
  if (Coop.active && Coop.isHost) {
    // Frigör tidigare turret
    for (const t of state.truck.turrets) if (t.occupiedBy === 'host') t.occupiedBy = null;
    tr.occupiedBy = 'host';
    state.player._mountedTurretId = turretId;
  } else if (Coop.active && !Coop.isHost) {
    // Klient: skicka request, vänta på host's bekräftelse
    Coop.sendToHost({ type: 'mount_req', tid: turretId });
    state.player._mountedTurretId = turretId; // optimistic
  } else {
    // Single-player
    state.player._mountedTurretId = turretId;
  }
}

// Bygg turret-väljare UI (visas bara i konvoj-mode)
const truckTurretBarEl = document.getElementById('truck-turret-bar');
function buildTruckTurretBar() {
  if (!truckTurretBarEl) return;
  truckTurretBarEl.innerHTML = '';
  for (const tr of TRUCK_TURRETS) {
    const btn = document.createElement('button');
    btn.style.cssText = 'background:rgba(40,40,50,0.95);border:1px solid rgba(170,58,255,0.5);border-radius:8px;width:46px;height:46px;font-size:18px;cursor:pointer;padding:0;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;';
    btn.dataset.turretId = tr.id;
    btn.innerHTML = `<div>${tr.icon}</div><div style="font-size:7px;opacity:0.6;">${tr.label.split(' ')[0]}</div>`;
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (!state.player) return;
      tryMountTurret(tr.id);
      Audio.uiClick();
      renderTruckTurretBar();
    });
    truckTurretBarEl.appendChild(btn);
  }
  // Leave-knapp
  const leaveBtn = document.createElement('button');
  leaveBtn.style.cssText = 'background:rgba(80,30,30,0.95);border:1px solid rgba(255,90,90,0.5);border-radius:8px;width:46px;height:46px;font-size:14px;cursor:pointer;padding:0;color:#fff;font-weight:bold;';
  leaveBtn.textContent = '✕';
  leaveBtn.title = 'Lämna turret';
  leaveBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    if (!state.player) return;
    if (state.player._mountedTurretId) tryMountTurret(state.player._mountedTurretId);
    Audio.uiClick();
    renderTruckTurretBar();
  });
  truckTurretBarEl.appendChild(leaveBtn);
}
function renderTruckTurretBar() {
  if (!truckTurretBarEl) return;
  const myId = Coop.active ? (Coop.isHost ? 'host' : Coop.myId) : null;
  for (const btn of truckTurretBarEl.querySelectorAll('button')) {
    const tid = btn.dataset.turretId;
    if (!tid) continue;
    const tr = state.truck ? state.truck.turrets.find(t => t.id === tid) : null;
    const isMine = state.player && tid === state.player._mountedTurretId;
    const isTaken = tr && tr.occupiedBy && tr.occupiedBy !== myId && tr.occupiedBy !== 'host';
    if (isMine) {
      btn.style.background = 'rgba(170,58,255,0.9)';
      btn.style.borderColor = '#fff';
      btn.style.opacity = '1';
    } else if (isTaken) {
      btn.style.background = 'rgba(80,80,80,0.5)';
      btn.style.borderColor = '#666';
      btn.style.opacity = '0.5';
    } else {
      btn.style.background = 'rgba(40,40,50,0.95)';
      btn.style.borderColor = 'rgba(170,58,255,0.5)';
      btn.style.opacity = '1';
    }
  }
}
buildTruckTurretBar();

function setupTruck(stage) {
  state.truck = {
    x: stage.spawnPos.x + 300,
    y: stage.spawnPos.y,
    w: 220, h: 90,
    hp: 2500, maxHp: 2500,
    speed: 50, // px/s framåt
    alive: true,
    angle: 0, // riktning (mot goal)
    turrets: TRUCK_TURRETS.map(t => ({ ...t, occupiedBy: null, lastShot: 0 })),
    wheelPhase: 0,
  };
  // Spelare börjar PÅ trucken
  if (state.player) {
    state.player.x = state.truck.x;
    state.player.y = state.truck.y - 8;
  }
}

function isTruckMode() {
  const stage = getStage(state.wave);
  return !!(stage && stage.isTruckMode);
}

function updateTruck(dt, now) {
  const t = state.truck;
  if (!t || !t.alive) return;
  const stage = getStage(state.wave);
  // Beräkna riktning mot goal
  const dx = stage.goalPos.x - t.x;
  const dy = stage.goalPos.y - t.y;
  const d = Math.hypot(dx, dy) || 1;
  t.angle = Math.atan2(dy, dx);
  // Bromsa när nästan framme
  const speedMul = d < 200 ? 0.3 : 1;
  t.x += (dx/d) * t.speed * speedMul * dt;
  t.y += (dy/d) * t.speed * speedMul * dt;
  t.wheelPhase += dt * 8;
  // MOUNT-system: lokal spelare som är "fastlåst" på en turret
  const p = state.player;
  if (p && p._mountedTurretId) {
    const tr = t.turrets.find(x => x.id === p._mountedTurretId);
    if (tr) {
      // Lås position till turret
      p.x = t.x + tr.offsetX;
      p.y = t.y + tr.offsetY;
      // Vapen = turret-vapen
      p._turretWeapon = tr.weaponId;
      p._turretId = tr.id;
      tr.occupiedBy = 'host';
    } else {
      // Turret existerar inte — släpp
      p._mountedTurretId = null;
      p._turretWeapon = null;
    }
  } else if (p) {
    // Inte mountad — clear turret-vapen
    p._turretWeapon = null;
    p._turretId = null;
    // Håll spelare PÅ trucken — rotera diff till truck-local space, clamp, rotera tillbaka.
    // Tidigare axis-aligned clamp fungerade fel när t.angle != 0 (kollision-shake).
    const angle = t.angle || 0;
    const cos = Math.cos(-angle), sin = Math.sin(-angle);
    const dx = p.x - t.x, dy = p.y - t.y;
    const lx = dx * cos - dy * sin, ly = dx * sin + dy * cos;
    const maxX = t.w/2 - 12, maxY = t.h/2 - 12;
    const cx = Math.max(-maxX, Math.min(maxX, lx));
    const cy = Math.max(-maxY, Math.min(maxY, ly));
    if (cx !== lx || cy !== ly) {
      const cos2 = Math.cos(angle), sin2 = Math.sin(angle);
      p.x = t.x + cx * cos2 - cy * sin2;
      p.y = t.y + cx * sin2 + cy * cos2;
    }
  }
  // Markera vilka turrets som är claim:ade (host + partners) + lås positions
  if (Coop.active && Coop.isHost) {
    // Reset alla claims för host-spelaren först (kommer sätts om i blocket ovan)
    for (const tr of t.turrets) {
      if (tr.occupiedBy === 'host' && (!p || p._mountedTurretId !== tr.id)) tr.occupiedBy = null;
    }
    // Sätt host-claim om mountad
    if (p && p._mountedTurretId) {
      const tr = t.turrets.find(x => x.id === p._mountedTurretId);
      if (tr) tr.occupiedBy = 'host';
    }
    // Lås partner-positioner till deras turret (bara om partner._mountedTurretId via mount_req)
    for (const [pid, partner] of Coop.players) {
      if (!partner) continue;
      if (partner._mountedTurretId) {
        const tr = t.turrets.find(x => x.id === partner._mountedTurretId);
        if (tr) {
          partner.x = t.x + tr.offsetX;
          partner.y = t.y + tr.offsetY;
          partner.targetX = partner.x; partner.targetY = partner.y;
          tr.occupiedBy = pid;
        }
      }
    }
  } else if (!Coop.active) {
    // Single-player: bara host
    for (const tr of t.turrets) {
      tr.occupiedBy = (p && p._mountedTurretId === tr.id) ? 'host' : null;
    }
  }
  // Truck tar skada från fiender som rör vid den
  for (const e of state.enemies) {
    if (e.dead) continue;
    const ed = Math.hypot(e.x - t.x, e.y - t.y);
    if (ed < (t.w/2) + e.r) {
      if (e.dmg > 0 && (!t._lastHit || now - t._lastHit > 300)) {
        t._lastHit = now;
        t.hp = Math.max(0, t.hp - e.dmg);
        triggerShake(4, 0.15);
        if (t.hp <= 0) {
          t.alive = false;
          explode(t.x, t.y, 200, 0, true);
          triggerShake(20, 0.8);
          endGame(false);
        }
      }
    }
  }
}

function drawTruck() {
  const t = state.truck;
  if (!t) return;
  const x = t.x - state.camera.x;
  const y = t.y - state.camera.y;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(t.angle);
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(-t.w/2 + 4, -t.h/2 + 6, t.w, t.h);
  // Lastbils-platform
  ctx.fillStyle = '#3a3a44';
  ctx.fillRect(-t.w/2, -t.h/2, t.w, t.h);
  // Paneler/raster
  ctx.fillStyle = '#5a5a64';
  ctx.fillRect(-t.w/2, -t.h/2, t.w, 4);
  ctx.fillRect(-t.w/2, t.h/2 - 4, t.w, 4);
  // Ramar runt
  ctx.strokeStyle = '#1a1a22'; ctx.lineWidth = 2;
  ctx.strokeRect(-t.w/2, -t.h/2, t.w, t.h);
  // Hjul (4 st)
  ctx.fillStyle = '#1a1a1a';
  for (const wpos of [-t.w/2 + 30, -t.w/2 + 80, t.w/2 - 80, t.w/2 - 30]) {
    ctx.fillRect(wpos - 8, -t.h/2 - 6, 16, 8);
    ctx.fillRect(wpos - 8,  t.h/2 - 2, 16, 8);
  }
  // Ratt-platsen (förare framåt)
  ctx.fillStyle = '#2a2a34';
  ctx.fillRect(t.w/2 - 40, -t.h/2 + 4, 36, t.h - 8);
  ctx.fillStyle = '#3acaff';
  ctx.fillRect(t.w/2 - 30, -10, 16, 20);
  // Pansar-detalj
  ctx.fillStyle = '#7a7a84';
  ctx.fillRect(-t.w/2 + 6, -t.h/2 + 8, 30, t.h - 16);
  // Turrets
  for (const tr of t.turrets) {
    const tx = tr.offsetX, ty = tr.offsetY;
    ctx.fillStyle = tr.occupiedBy ? '#aa3aff' : '#222';
    ctx.beginPath(); ctx.arc(tx, ty, 14, 0, Math.PI*2); ctx.fill();
    ctx.strokeStyle = tr.occupiedBy ? '#fff' : '#666'; ctx.lineWidth = 2;
    ctx.stroke();
    // Ikon
    ctx.font = '14px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.fillText(tr.icon, tx, ty + 5);
  }
  ctx.restore();
  // HP-bar ovanför trucken
  const hpW = 200, hpH = 8;
  const hpX = x - hpW/2, hpY = y - t.h/2 - 30;
  ctx.fillStyle = 'rgba(0,0,0,0.7)';
  ctx.fillRect(hpX - 2, hpY - 2, hpW + 4, hpH + 4);
  ctx.fillStyle = t.hp / t.maxHp > 0.3 ? '#5aff5a' : '#ff5a5a';
  ctx.fillRect(hpX, hpY, hpW * (t.hp / t.maxHp), hpH);
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 11px sans-serif';
  ctx.textAlign = 'center';
  ctx.shadowColor = '#000'; ctx.shadowBlur = 3;
  ctx.fillText('🚚 TRUCK ' + Math.ceil(t.hp) + '/' + t.maxHp, x, hpY - 6);
  ctx.shadowBlur = 0;
}

function spawnCompanion() {
  if (!save.companions || !save.companions.active) { state.companion = null; return; }
  // PvP-modes (tdm/ctf/siege) tillåter inte companion — orättvist + ingen shop att köpa
  if (Coop.active && Coop.config && (Coop.config.tdm || Coop.config.ctf || Coop.config.siege || Coop.config.gungame)) {
    state.companion = null; return;
  }
  const id = save.companions.active;
  const comp = getCompanionById(id);
  if (!comp) { state.companion = null; return; }
  // Rensa persisted death-state vid spawn (revive eller new run)
  if (save.companions.dead && save.companions.dead[id]) {
    delete save.companions.dead[id];
    persist();
  }
  const lvl = save.companions.level[id] || 0;
  const stats = companionStats(comp, lvl);
  const p = state.player;
  state.companion = {
    id, comp, lvl,
    x: p ? p.x + 30 : 1000, y: p ? p.y + 30 : 1000,
    r: 12,
    hp: stats.hp, maxHp: stats.hp, dmg: stats.dmg, speed: stats.speed,
    range: stats.range, cooldown: stats.cooldown,
    lastAct: 0, target: null, alive: true,
    angle: 0, walkPhase: 0,
    flashUntil: 0, // damage-flash-timestamp (sätts av damageCompanion / event)
  };
}
function updateCompanion(dt, now) {
  const c = state.companion;
  if (!c || !c.alive || !state.player) return;
  const p = state.player;
  // Följ spelaren — håll avstånd 50-90px
  const dx = p.x - c.x, dy = p.y - c.y;
  const d = Math.hypot(dx, dy) || 1;
  const ideal = 60;
  if (d > ideal + 30) {
    c.x += (dx/d) * c.speed * dt;
    c.y += (dy/d) * c.speed * dt;
    c.walkPhase += dt * 8;
  }
  // Hitta närmsta fiende
  let target = null, bestD = c.range;
  for (const e of state.enemies) {
    if (e.dead) continue;
    const ed = Math.hypot(e.x - c.x, e.y - c.y);
    if (ed < bestD) { bestD = ed; target = e; }
  }
  c.target = target;
  if (target) {
    c.angle = Math.atan2(target.y - c.y, target.x - c.x);
  }
  // Specialhandling per companion-typ
  if (c.id === 'metaldog' && target && bestD < 50 && now - c.lastAct > c.cooldown * 1000) {
    c.lastAct = now;
    // bett — staggra + skada
    target.staggerUntil = now + 600;
    damageEnemy(target, c.dmg, false);
    spawnParticles(target.x, target.y, '#ffae3a', 6, 120);
    Audio.kill && Audio.kill();
  } else if (c.id === 'drone' && target && now - c.lastAct > c.cooldown * 1000) {
    c.lastAct = now;
    // Skjut laser-skott
    const ang = c.angle;
    state.bullets.push({
      x: c.x, y: c.y, vx: Math.cos(ang) * 800, vy: Math.sin(ang) * 800,
      dmg: c.dmg, life: 0.8, r: 3, color: '#3acaff', hostile: false,
      style: 'plasma', _companion: true,
    });
  } else if (c.id === 'spacemonkey' && target && now - c.lastAct > c.cooldown * 1000) {
    c.lastAct = now;
    // Plasma-bomb mot target
    state.bullets.push({
      x: c.x, y: c.y, vx: Math.cos(c.angle) * 380, vy: Math.sin(c.angle) * 380,
      dmg: c.dmg, life: 1.6, r: 6, color: '#aa3aff', hostile: false,
      style: 'plasma', _companion: true, explosive: 80,
    });
  }
}
function drawCompanion() {
  const c = state.companion;
  if (!c || !c.alive) return;
  const x = c.x - state.camera.x;
  const y = c.y - state.camera.y;
  ctx.save();
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.4)';
  ctx.beginPath(); ctx.ellipse(x + 2, y + 12, 12, 4, 0, 0, Math.PI*2); ctx.fill();
  // HP-bar ovanför companion — alltid synlig (subtilare när full)
  {
    const bw = 28, bh = 4;
    const bx = x - bw / 2, by = y - 22;
    const frac = Math.max(0, c.hp / c.maxHp);
    const fullAlpha = frac >= 1 ? 0.5 : 1.0;
    ctx.globalAlpha = fullAlpha;
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(bx - 1, by - 1, bw + 2, bh + 2);
    ctx.fillStyle = frac > 0.5 ? '#5aff5a' : (frac > 0.25 ? '#ffd54a' : '#ff5a5a');
    ctx.fillRect(bx, by, bw * frac, bh);
    ctx.globalAlpha = 1;
  }
  // Damage flash (vit overlay 100ms efter skada)
  const flashUntil = c.flashUntil || 0;
  if (performance.now() < flashUntil) ctx.globalCompositeOperation = 'lighter';
  if (c.id === 'metaldog') {
    // Robothund — kropp + ben + huvud
    ctx.translate(x, y);
    ctx.rotate(c.angle);
    // ben (alternerar)
    const legSwing = Math.sin(c.walkPhase);
    ctx.fillStyle = '#3a3a3a';
    ctx.fillRect(-8, -6 - legSwing*1.5, 3, 5);
    ctx.fillRect(-8,  3 + legSwing*1.5, 3, 5);
    ctx.fillRect(6, -6 + legSwing*1.5, 3, 5);
    ctx.fillRect(6,  3 - legSwing*1.5, 3, 5);
    // kropp (silver-grå metall)
    ctx.fillStyle = c.comp.color;
    ctx.fillRect(-9, -5, 18, 10);
    ctx.fillStyle = '#5a5a5a';
    ctx.fillRect(-9, -5, 18, 3);
    // huvud
    ctx.fillStyle = c.comp.color;
    ctx.fillRect(7, -4, 8, 8);
    // röda ögon
    ctx.fillStyle = c.comp.accent;
    ctx.shadowColor = c.comp.accent; ctx.shadowBlur = 4;
    ctx.fillRect(11, -3, 2, 2);
    ctx.fillRect(11,  1, 2, 2);
    ctx.shadowBlur = 0;
    // svans
    ctx.strokeStyle = '#3a3a3a'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(-9, 0); ctx.lineTo(-14, -3); ctx.stroke();
  } else if (c.id === 'drone') {
    const t = performance.now() / 200;
    const hover = Math.sin(t) * 2;
    ctx.translate(x, y + hover);
    ctx.rotate(c.angle * 0.3);
    // skiva
    ctx.fillStyle = c.comp.color;
    ctx.shadowColor = c.comp.color; ctx.shadowBlur = 8;
    ctx.beginPath(); ctx.ellipse(0, 0, 10, 4, 0, 0, Math.PI*2); ctx.fill();
    ctx.shadowBlur = 0;
    // mitt-led
    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.arc(0, 0, 2.5, 0, Math.PI*2); ctx.fill();
    // 4 propellrar
    const pt = performance.now() / 30;
    ctx.strokeStyle = 'rgba(255,255,255,0.3)'; ctx.lineWidth = 1.5;
    for (let i = 0; i < 4; i++) {
      const a = i * Math.PI / 2 + pt;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * 6, Math.sin(a) * 6);
      ctx.lineTo(Math.cos(a) * 11, Math.sin(a) * 11);
      ctx.stroke();
    }
  } else if (c.id === 'spacemonkey') {
    ctx.translate(x, y);
    // hopp-animation
    const bounce = Math.abs(Math.sin(c.walkPhase)) * -3;
    ctx.translate(0, bounce);
    // kropp (brun apa)
    ctx.fillStyle = c.comp.color;
    ctx.beginPath(); ctx.arc(0, 2, 8, 0, Math.PI*2); ctx.fill();
    // huvud
    ctx.beginPath(); ctx.arc(0, -6, 6, 0, Math.PI*2); ctx.fill();
    // ansikte (lila glow)
    ctx.fillStyle = '#f4d4a4';
    ctx.beginPath(); ctx.arc(0, -5, 4, 0, Math.PI*2); ctx.fill();
    // ögon
    ctx.fillStyle = c.comp.accent;
    ctx.shadowColor = c.comp.accent; ctx.shadowBlur = 4;
    ctx.beginPath(); ctx.arc(-1.5, -6, 1, 0, Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(1.5, -6, 1, 0, Math.PI*2); ctx.fill();
    ctx.shadowBlur = 0;
    // armar (sträcker mot target)
    ctx.fillStyle = c.comp.color;
    ctx.fillRect(-9, 0, 4, 5);
    ctx.fillRect( 5, 0, 4, 5);
    // hjälm/space-glas
    ctx.strokeStyle = c.comp.accent; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(0, -6, 7, 0, Math.PI*2); ctx.stroke();
  }
  ctx.restore();
  // namn-tag
  ctx.fillStyle = c.comp.accent;
  ctx.font = 'bold 9px sans-serif';
  ctx.textAlign = 'center';
  ctx.shadowColor = '#000'; ctx.shadowBlur = 3;
  ctx.fillText(c.comp.icon, x, y - 16);
  ctx.shadowBlur = 0;
}

function updateDrone(dt, now) {
  if (!state.drone || !state.drone.alive || !state.player) return;
  const d = state.drone;
  const p = state.player;
  // Cirkulera runt spelaren
  d.angle += dt * 1.5;
  const orbitR = 50;
  const tx = p.x + Math.cos(d.angle) * orbitR;
  const ty = p.y + Math.sin(d.angle) * orbitR;
  d.x += (tx - d.x) * 8 * dt;
  d.y += (ty - d.y) * 8 * dt;
  // Skjut närmsta fiende
  if (now - d.lastShot > 600) {
    let target = null, bestD = 380;
    for (const e of state.enemies) {
      if (e.dead) continue;
      const dst = Math.hypot(e.x - d.x, e.y - d.y);
      if (dst < bestD) { bestD = dst; target = e; }
    }
    if (target) {
      d.lastShot = now;
      const ang = Math.atan2(target.y - d.y, target.x - d.x);
      state.bullets.push({
        x: d.x, y: d.y, vx: Math.cos(ang)*700, vy: Math.sin(ang)*700,
        dmg: 18, life: 1.2, r: 3, color: '#3acaff', hostile: false,
        style: 'drone',
      });
    }
  }
}
// Rita emote-bubbla ovanför en spelare/partner
function drawEmoteBubble(em, x, y, r) {
  const now = performance.now();
  if (!em || !em.until || now > em.until) return;
  const totalDur = em.dur || 3500;
  const t = em.until - now;
  const elapsed = totalDur - t;
  // Pop-in: scale 0.4 → 1 (overshoot 1.15 vid 120ms)
  let scale;
  if (elapsed < 120) scale = 0.4 + (elapsed / 120) * 0.75;
  else if (elapsed < 200) scale = 1.15 - ((elapsed - 120) / 80) * 0.15;
  else scale = 1;
  // Fade-out: sista 400ms
  const alpha = t > 400 ? 1 : Math.max(0, t / 400);
  // Bobbing: subtil floating
  const bob = Math.sin(elapsed / 250) * 2;
  ctx.save();
  ctx.globalAlpha = alpha;
  const cx = x;
  const cy = y - r - 30 + bob;
  // Bara emojin — ingen bubbla, ingen border. Soft drop-shadow för läsbarhet
  // mot game-bg så emojin pop:par utan att behöva white-box runt.
  ctx.shadowColor = 'rgba(0,0,0,0.7)';
  ctx.shadowBlur = 4;
  ctx.shadowOffsetY = 2;
  ctx.font = 'bold ' + Math.round(32 * scale) + 'px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#fff'; // fallback om systemet inte renderar emoji som färg
  ctx.fillText(em.emoji, cx, cy);
  ctx.restore();
}

// TDM: rita pulsande team-ring under varje spelare för friend/foe-identifiering
function drawTdmTeamRings() {
  if (!Coop.tdmTeams) return;
  const pulse = 0.85 + Math.sin(performance.now() / 200) * 0.15;
  const drawRing = (wx, wy, team, isMe) => {
    const x = wx - state.camera.x, y = wy - state.camera.y;
    if (x < -40 || x > viewW + 40 || y < -40 || y > viewH + 40) return;
    const color = team === 'red' ? '#ff3a3a' : '#3a8aff';
    const fillCol = team === 'red' ? 'rgba(255,58,58,0.22)' : 'rgba(58,138,255,0.22)';
    const r = 24;
    ctx.save();
    // Fylld inner-disk för stark team-identifiering — synlig direkt vid blick
    ctx.fillStyle = fillCol;
    ctx.beginPath();
    ctx.arc(x, y + 14, r, 0, Math.PI * 2);
    ctx.fill();
    // Tjock ring + glow
    ctx.strokeStyle = color;
    ctx.lineWidth = isMe ? 4 : 3;
    ctx.shadowColor = color;
    ctx.shadowBlur = 14 * pulse;
    ctx.globalAlpha = 1;
    // Color-blind safety: röd = solid ring, blå = streckad (deuteranope-vänligt)
    if (team === 'blue') ctx.setLineDash([8, 5]);
    ctx.beginPath();
    ctx.arc(x, y + 14, r, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();
  };
  // Min egen ring
  if (state.player && Coop.tdmTeams[Coop.myId]) {
    drawRing(state.player.x, state.player.y, Coop.tdmTeams[Coop.myId], true);
  }
  // Partners
  for (const [pid, p] of Coop.players) {
    if (p.x === undefined) continue;
    if (p.hp !== undefined && p.hp <= 0) continue;
    const team = Coop.tdmTeams[pid];
    if (!team) continue;
    drawRing(p.x, p.y, team, false);
  }
}

function drawCtfTeamRings() {
  if (!Coop.ctfTeams) return;
  const pulse = 0.85 + Math.sin(performance.now() / 200) * 0.15;
  const drawRing = (wx, wy, team, isMe) => {
    const x = wx - state.camera.x, y = wy - state.camera.y;
    if (x < -40 || x > viewW + 40 || y < -40 || y > viewH + 40) return;
    const color = team === 'red' ? '#ff5a5a' : '#5aaaff';
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = isMe ? 3 : 2;
    ctx.shadowColor = color;
    ctx.shadowBlur = 12 * pulse;
    ctx.globalAlpha = 0.9;
    if (team === 'blue') ctx.setLineDash([6, 4]);
    ctx.beginPath();
    ctx.arc(x, y + 14, 22, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();
  };
  if (state.player && Coop.ctfTeams[Coop.myId]) {
    drawRing(state.player.x, state.player.y, Coop.ctfTeams[Coop.myId], true);
  }
  for (const [pid, p] of Coop.players) {
    if (p.x === undefined) continue;
    if (p.hp !== undefined && p.hp <= 0) continue;
    const team = Coop.ctfTeams[pid];
    if (!team) continue;
    drawRing(p.x, p.y, team, false);
  }
}

// CTF: team-tinted floor halves — visa direkt vem äger vilken sida av arenan.
// Subtilt så det inte överröstar player/enemies.
function drawCtfArenaFloor() {
  const arena = state.ctfArena;
  if (!arena) return;
  const cx = state.camera.x, cy = state.camera.y;
  ctx.save();
  // Röd sida (vänster halva)
  ctx.fillStyle = 'rgba(255,60,60,0.05)';
  ctx.fillRect(0 - cx, 0 - cy, arena.worldW * 0.45, arena.worldH);
  // Blå sida (höger halva)
  ctx.fillStyle = 'rgba(60,140,255,0.05)';
  ctx.fillRect(arena.worldW * 0.55 - cx, 0 - cy, arena.worldW * 0.45, arena.worldH);
  // Mittlinje (neutral zone)
  ctx.strokeStyle = 'rgba(255,255,255,0.10)';
  ctx.lineWidth = 2;
  ctx.setLineDash([12, 12]);
  ctx.beginPath();
  ctx.moveTo(arena.worldW * 0.5 - cx, 0 - cy);
  ctx.lineTo(arena.worldW * 0.5 - cx, arena.worldH - cy);
  ctx.stroke();
  ctx.setLineDash([]);
  // Subtila team-cirklar runt baser (ambient glow)
  const pulse = 0.5 + Math.sin(performance.now() / 700) * 0.2;
  for (const team of ['red', 'blue']) {
    const f = state.ctfFlags && state.ctfFlags[team];
    if (!f) continue;
    const bx = f.baseX - cx, by = f.baseY - cy;
    const color = team === 'red' ? 'rgba(255,90,90,' : 'rgba(90,170,255,';
    // Tighter pulse-glow (90px var 220px) så bara området DIREKT runt flag-stand
    // är highlightat — annars överlappade glow:n med decorations som RED 4 LIFE.
    const grad = ctx.createRadialGradient(bx, by, 15, bx, by, 90);
    grad.addColorStop(0, color + (0.20 * pulse) + ')');
    grad.addColorStop(1, color + '0)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(bx, by, 90, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

// Generisk wall-render — detaljerad pixel-art-style rendering för varje kind.
// Använd helper-funktioner per typ så koden är läsbar. Alla helpers tar
// (x, y, w, h) som ABSOLUTA skärm-koord (kameran är redan applicerad).
function drawPvpWalls(walls) {
  if (!walls) return;
  // Avrunda kameran så väggar (integer-koord) renderas vid exakta pixel-positioner.
  // Annars: camera float → wall screen-pos float → anti-aliased blur → wobble vid kamera-pan.
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  // Shadow under varje wall (drop-shadow) först så de lager-lurar visuellt
  ctx.save();
  for (const w of walls) {
    const x = w.x - cx, y = w.y - cy;
    if (x + w.w < -20 || x > viewW + 20 || y + w.h < -20 || y > viewH + 20) continue;
    // Drop-shadow för depth (ej för low dividers eller pipes som ligger på marken)
    if (w.kind !== 'pipe' && w.kind !== 'wall_divider') {
      ctx.fillStyle = 'rgba(0,0,0,0.35)';
      ctx.fillRect(x + 2, y + Math.max(3, w.h * 0.06), w.w, w.h);
    }
    // Stabil hash per-wall baserat på WORLD-koord (konstant). Tidigare beräknades
    // hash från SCREEN-coords (x,y) inom helpers → bullet-holes, concrete-dots och
    // wood-grain "vandrade" varje frame när kameran rörde sig.
    const seed = ((w.x * 7) ^ (w.y * 13) ^ (w.w * 5) ^ (w.h * 11)) | 0;
    // Rita själva obstaclet
    if (w.kind === 'wall_red_base' || w.kind === 'wall_blue_base') drawBaseWall(x, y, w.w, w.h, w.kind === 'wall_red_base', seed);
    else if (w.kind === 'wall_pillar') drawPillar(x, y, w.w, w.h, seed);
    else if (w.kind === 'wall_divider') drawDivider(x, y, w.w, w.h);
    else if (w.kind === 'sandbag') drawSandbag(x, y, w.w, w.h);
    else if (w.kind === 'barrel') drawBarrel(x, y, w.w, w.h);
    else if (w.kind === 'debris') drawDebris(x, y, w.w, w.h, seed);
    else if (w.kind === 'barricade') drawBarricade(x, y, w.w, w.h);
    else if (w.kind === 'pipe') drawPipe(x, y, w.w, w.h);
    else if (w.kind === 'crate') drawCrate(x, y, w.w, w.h, seed);
    else if (w.kind === 'truck') drawTruck(x, y, w.w, w.h, seed);
    else if (w.kind === 'van') drawVan(x, y, w.w, w.h, seed);
    else if (w.kind === 'car_wreck') drawCarWreck(x, y, w.w, w.h, seed);
    else if (w.kind === 'guardhouse') drawGuardhouse(x, y, w.w, w.h);
    else if (w.kind === 'ramp') drawRamp(x, y, w.w, w.h);
    else if (w.kind === 'oil_drum') drawOilDrum(x, y, w.w, w.h, seed);
    else if (w.kind === 'fire_drum') drawFireDrum(x, y, w.w, w.h, seed);
    else if (w.kind === 'lamppost') drawLamppost(x, y, w.w, w.h, w.x, w.y);
    else if (w.kind === 'broken_pillar') drawBrokenPillar(x, y, w.w, w.h, seed);
    else if (w.kind === 'tagged_pillar') drawTaggedPillar(x, y, w.w, w.h, seed);
    else if (w.kind === 'concrete') drawConcreteWall(x, y, w.w, w.h);
    else { ctx.fillStyle = '#5a5a5a'; ctx.fillRect(x, y, w.w, w.h); }
  }
  ctx.restore();
}

// Base-wall: stålplattor med nitar + lag-färg + slitage + bullet-holes
function drawBaseWall(x, y, w, h, isRed, seed) {
  const baseDark = isRed ? '#3a1010' : '#10204a';
  const baseMid = isRed ? '#5a2828' : '#1a3060';
  const stroke = isRed ? '#ff6060' : '#60a0ff';
  // Gradient fyllning för 3D-look
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, baseMid);
  grad.addColorStop(0.5, baseDark);
  grad.addColorStop(1, baseMid);
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Plattor-segmentering (varje 60-80 px)
  const segW = Math.max(40, w > h ? w / Math.max(2, Math.round(w / 80)) : w);
  const segH = Math.max(40, h > w ? h / Math.max(2, Math.round(h / 80)) : h);
  ctx.strokeStyle = 'rgba(0,0,0,0.55)';
  ctx.lineWidth = 1;
  if (w > h) {
    for (let i = segW; i < w; i += segW) {
      ctx.beginPath();
      ctx.moveTo(x + i, y + 2);
      ctx.lineTo(x + i, y + h - 2);
      ctx.stroke();
    }
  } else {
    for (let i = segH; i < h; i += segH) {
      ctx.beginPath();
      ctx.moveTo(x + 2, y + i);
      ctx.lineTo(x + w - 2, y + i);
      ctx.stroke();
    }
  }
  // Nitar (små cirklar i hörnen + längs kanterna)
  const rivetR = 1.8;
  const rivetColor = '#222';
  const rivetHi = isRed ? '#7a3030' : '#3050a0';
  const placeRivet = (rx, ry) => {
    ctx.fillStyle = rivetColor;
    ctx.beginPath(); ctx.arc(rx, ry, rivetR, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = rivetHi;
    ctx.beginPath(); ctx.arc(rx - 0.5, ry - 0.5, rivetR * 0.4, 0, Math.PI * 2); ctx.fill();
  };
  // Hörn-nitar
  placeRivet(x + 5, y + 5);
  placeRivet(x + w - 5, y + 5);
  placeRivet(x + 5, y + h - 5);
  placeRivet(x + w - 5, y + h - 5);
  // Längs långsidor
  if (w > 60) {
    for (let i = 30; i < w - 10; i += 30) {
      placeRivet(x + i, y + 5);
      placeRivet(x + i, y + h - 5);
    }
  }
  if (h > 60) {
    for (let i = 30; i < h - 10; i += 30) {
      placeRivet(x + 5, y + i);
      placeRivet(x + w - 5, y + i);
    }
  }
  // Bullet-holes — använd seed (world-coord-baserad) så de inte vandrar
  const hash = seed || 0;
  const holes = Math.min(3, Math.floor((w + h) / 120));
  for (let i = 0; i < holes; i++) {
    const hx = x + 10 + ((hash * (i + 1) * 23) & 0xff) % Math.max(1, w - 20);
    const hy = y + 10 + ((hash * (i + 3) * 31) & 0xff) % Math.max(1, h - 20);
    ctx.fillStyle = '#000';
    ctx.beginPath(); ctx.arc(hx, hy, 2, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = 'rgba(180,180,180,0.4)';
    ctx.lineWidth = 0.8;
    ctx.beginPath(); ctx.arc(hx, hy, 3.5, 0, Math.PI * 2); ctx.stroke();
  }
  // Lag-färgad ram (subtil)
  ctx.strokeStyle = stroke;
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// Pillar: betongpelare med synligt rebar + sprickor + bullet-holes
function drawPillar(x, y, w, h, seed) {
  // Concrete-gradient
  const grad = ctx.createLinearGradient(x, y, x + w, y);
  grad.addColorStop(0, '#4a4a4a');
  grad.addColorStop(0.5, '#606060');
  grad.addColorStop(1, '#3a3a3a');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Yttre kant
  ctx.strokeStyle = '#2a2a2a';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  // Inner highlight (left edge)
  ctx.fillStyle = 'rgba(255,255,255,0.08)';
  ctx.fillRect(x + 2, y + 2, 2, h - 4);
  // Concrete texture (noise-dots) — använd seed så texturen är stabil
  const hash = seed || 0;
  ctx.fillStyle = 'rgba(0,0,0,0.18)';
  for (let i = 0; i < 8; i++) {
    const px = x + 2 + ((hash * (i + 1) * 7) & 0xff) % (w - 4);
    const py = y + 2 + ((hash * (i + 7) * 13) & 0xff) % (h - 4);
    ctx.fillRect(px, py, 1.5, 1.5);
  }
  // Sprickor (zig-zag-linjer)
  ctx.strokeStyle = 'rgba(0,0,0,0.6)';
  ctx.lineWidth = 1;
  if (h > 100) {
    ctx.beginPath();
    const midX = x + w / 2;
    ctx.moveTo(midX, y + h * 0.2);
    ctx.lineTo(midX - 2, y + h * 0.35);
    ctx.lineTo(midX + 1, y + h * 0.5);
    ctx.lineTo(midX - 3, y + h * 0.65);
    ctx.lineTo(midX + 2, y + h * 0.8);
    ctx.stroke();
  }
  // Exponerad rebar i toppen om hög pillar
  if (h > 100) {
    ctx.strokeStyle = '#5a3a1a';
    ctx.lineWidth = 1.5;
    for (let rx = x + 6; rx < x + w - 6; rx += 6) {
      ctx.beginPath();
      ctx.moveTo(rx, y);
      ctx.lineTo(rx, y - 4);
      ctx.stroke();
    }
    // Rost-orange tipp
    ctx.fillStyle = '#9a5a20';
    for (let rx = x + 6; rx < x + w - 6; rx += 6) {
      ctx.fillRect(rx - 1, y - 4, 2, 2);
    }
  }
  // Bullet-holes
  const holesN = Math.floor(h / 60);
  for (let i = 0; i < holesN; i++) {
    const hx = x + 5 + ((hash * (i + 1) * 19) & 0xff) % (w - 10);
    const hy = y + 20 + (i * h / Math.max(1, holesN)) | 0;
    ctx.fillStyle = '#000';
    ctx.beginPath(); ctx.arc(hx, hy, 1.5, 0, Math.PI * 2); ctx.fill();
  }
}

// Divider: jersey-barrier-style med reflektiv-stripes
function drawDivider(x, y, w, h) {
  // Concrete-gradient (top → bottom)
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#5a5a5a');
  grad.addColorStop(0.5, '#404040');
  grad.addColorStop(1, '#2a2a2a');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Kant
  ctx.strokeStyle = '#1a1a1a';
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  // Reflective gul-svart stripes (varannan)
  const stripeW = 12;
  for (let i = 0; i < w; i += stripeW * 2) {
    ctx.fillStyle = 'rgba(255,213,74,0.85)';
    ctx.fillRect(x + i, y + h * 0.3, Math.min(stripeW, w - i), h * 0.4);
  }
  // Yttre kant (mörk)
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(x, y + h - 2, w, 2);
}

// Sandsäck: stack av runda säckar med stitches + rope
function drawSandbag(x, y, w, h) {
  // Antal säckar baserat på bredd (varje säck ~36px)
  const bagW = 36;
  const bags = Math.max(1, Math.floor(w / bagW));
  const actualBagW = w / bags;
  for (let i = 0; i < bags; i++) {
    const bx = x + i * actualBagW;
    const bw = actualBagW;
    // Säck-bas (rounded shape via gradient)
    const grad = ctx.createLinearGradient(bx, y, bx, y + h);
    grad.addColorStop(0, '#b89060');
    grad.addColorStop(0.5, '#9a7440');
    grad.addColorStop(1, '#6a4e2a');
    ctx.fillStyle = grad;
    ctx.beginPath();
    if (typeof ctx.roundRect === 'function') {
      ctx.roundRect(bx + 1, y + 1, bw - 2, h - 2, Math.min(6, h * 0.3));
    } else {
      ctx.rect(bx + 1, y + 1, bw - 2, h - 2);
    }
    ctx.fill();
    // Kant (mörk konturlinje)
    ctx.strokeStyle = '#3a2810';
    ctx.lineWidth = 1.2;
    ctx.stroke();
    // Stitching (sömmar) — horisontella streck längs ovansidan
    ctx.strokeStyle = 'rgba(40,25,5,0.7)';
    ctx.lineWidth = 0.8;
    ctx.setLineDash([2, 2]);
    ctx.beginPath();
    ctx.moveTo(bx + 4, y + 3);
    ctx.lineTo(bx + bw - 4, y + 3);
    ctx.stroke();
    ctx.setLineDash([]);
    // Mid-tie (rep i mitten)
    ctx.fillStyle = '#5a3a15';
    ctx.fillRect(bx + bw / 2 - 2, y + 2, 4, h - 4);
    // Knut i mitten
    ctx.fillStyle = '#7a5025';
    ctx.beginPath();
    ctx.arc(bx + bw / 2, y + h / 2, Math.min(3, h * 0.2), 0, Math.PI * 2);
    ctx.fill();
    // Top-highlight
    ctx.fillStyle = 'rgba(255,220,180,0.25)';
    ctx.fillRect(bx + 4, y + 2, bw - 8, 2);
  }
}

// Explosivt fat: cylinder med metal-bands + biohazard + dripps
function drawBarrel(x, y, w, h) {
  const cx = x + w / 2;
  const cy = y + h / 2;
  // Yttre cirkel (top-view-style ovanifrån). Använd lite rektangel för "djup"
  ctx.fillStyle = '#2a0808';
  ctx.fillRect(x, y, w, h);
  // Huvud-cirkel (3D-bowl)
  const grad = ctx.createRadialGradient(cx - 2, cy - 2, 1, cx, cy, w * 0.55);
  grad.addColorStop(0, '#ff6060');
  grad.addColorStop(0.5, '#aa2020');
  grad.addColorStop(1, '#5a1010');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(cx, cy, w * 0.5, 0, Math.PI * 2);
  ctx.fill();
  // Metal-band runt (yttre)
  ctx.strokeStyle = '#3a3a3a';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(cx, cy, w * 0.5, 0, Math.PI * 2);
  ctx.stroke();
  // Inner-cirkel (top-opening)
  ctx.strokeStyle = '#222';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(cx, cy, w * 0.32, 0, Math.PI * 2);
  ctx.stroke();
  // Biohazard-symbol (☢) i mitten
  ctx.fillStyle = '#ffd54a';
  ctx.font = 'bold ' + Math.floor(w * 0.5) + 'px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.shadowColor = '#000';
  ctx.shadowBlur = 2;
  ctx.fillText('☢', cx, cy);
  ctx.shadowBlur = 0;
  // Drip-streck nedanför (looks dangerous)
  ctx.strokeStyle = '#2a0a0a';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(cx - 4, cy + w * 0.45);
  ctx.lineTo(cx - 5, y + h + 2);
  ctx.moveTo(cx + 3, cy + w * 0.4);
  ctx.lineTo(cx + 4, y + h + 1);
  ctx.stroke();
  // Top-highlight (reflective)
  ctx.fillStyle = 'rgba(255,255,255,0.3)';
  ctx.beginPath();
  ctx.arc(cx - w * 0.18, cy - w * 0.18, w * 0.1, 0, Math.PI * 2);
  ctx.fill();
}

// Debris: jaggad metallbit med rost + rivets
function drawDebris(x, y, w, h, seed) {
  // Bakgrund (mörk skugga-area)
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(x, y, w, h);
  // Mestadels mörkgrå metal med rost
  ctx.fillStyle = '#4a4a52';
  ctx.beginPath();
  // Jaggad oregelbunden form (seed används för stabilitet, även om current
  // polygon-form är hårdkodad relativ till x/y så seeds bara håller framtida
  // randomisering konsekvent)
  const hash = seed || 0;
  ctx.moveTo(x + 2, y + 4);
  ctx.lineTo(x + w * 0.3, y + 1);
  ctx.lineTo(x + w * 0.6, y + 3);
  ctx.lineTo(x + w - 2, y + 2);
  ctx.lineTo(x + w - 1, y + h * 0.4);
  ctx.lineTo(x + w - 4, y + h - 3);
  ctx.lineTo(x + w * 0.5, y + h - 1);
  ctx.lineTo(x + 3, y + h - 2);
  ctx.lineTo(x + 1, y + h * 0.5);
  ctx.closePath();
  ctx.fill();
  // Rost-fläckar (orange-bruna)
  ctx.fillStyle = '#7a4a20';
  ctx.beginPath();
  ctx.arc(x + w * 0.3, y + h * 0.4, 4, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#9a5a30';
  ctx.beginPath();
  ctx.arc(x + w * 0.7, y + h * 0.6, 3, 0, Math.PI * 2);
  ctx.fill();
  // Rivets/bolts (silver-små cirklar)
  const placeBolt = (bx, by) => {
    ctx.fillStyle = '#222';
    ctx.beginPath(); ctx.arc(bx, by, 1.5, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#7a7a80';
    ctx.beginPath(); ctx.arc(bx - 0.3, by - 0.3, 0.6, 0, Math.PI * 2); ctx.fill();
  };
  placeBolt(x + w * 0.2, y + h * 0.2);
  placeBolt(x + w * 0.8, y + h * 0.25);
  placeBolt(x + w * 0.4, y + h * 0.7);
  // Sprick-linjer
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(x + w * 0.15, y + h * 0.1);
  ctx.lineTo(x + w * 0.6, y + h * 0.5);
  ctx.lineTo(x + w * 0.85, y + h * 0.45);
  ctx.stroke();
}

// Barricade: korslagda träplankor med spikar + slitage
function drawBarricade(x, y, w, h) {
  // Bakgrund (svagt mörkare)
  ctx.fillStyle = '#3a2a18';
  ctx.fillRect(x, y, w, h);
  // Tre plankor överlappande
  const plankH = Math.max(6, h * 0.55);
  const drawPlank = (px, py, pw, ph, rot, color1, color2) => {
    ctx.save();
    ctx.translate(px + pw / 2, py + ph / 2);
    if (rot) ctx.rotate(rot);
    const grad = ctx.createLinearGradient(-pw / 2, -ph / 2, -pw / 2, ph / 2);
    grad.addColorStop(0, color1);
    grad.addColorStop(0.5, color2);
    grad.addColorStop(1, color1);
    ctx.fillStyle = grad;
    ctx.fillRect(-pw / 2, -ph / 2, pw, ph);
    ctx.strokeStyle = '#3a2810';
    ctx.lineWidth = 1;
    ctx.strokeRect(-pw / 2 + 0.5, -ph / 2 + 0.5, pw - 1, ph - 1);
    // Trä-grain (horisontella linjer)
    ctx.strokeStyle = 'rgba(50,30,10,0.4)';
    ctx.lineWidth = 0.5;
    for (let i = -ph / 2 + 2; i < ph / 2; i += 3) {
      ctx.beginPath();
      ctx.moveTo(-pw / 2 + 2, i);
      ctx.lineTo(pw / 2 - 2, i);
      ctx.stroke();
    }
    // Spikar
    ctx.fillStyle = '#222';
    ctx.beginPath(); ctx.arc(-pw / 2 + 4, 0, 1.8, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(pw / 2 - 4, 0, 1.8, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#7a7a80';
    ctx.beginPath(); ctx.arc(-pw / 2 + 4 - 0.3, -0.3, 0.6, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(pw / 2 - 4 - 0.3, -0.3, 0.6, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  };
  // Bottenplanka (rakt)
  drawPlank(x, y + h - plankH, w, plankH, 0, '#8a6a3a', '#6a4a20');
  // Korslagd planka (lite roterad)
  drawPlank(x + 4, y, w - 8, plankH * 0.9, -0.05, '#9a7a40', '#7a5a28');
  // Yttre kontur
  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// Rör: cylindriskt metallrör med flänsar + bolts + ångström
function drawPipe(x, y, w, h) {
  // Cylinder gradient (top → bottom för horisontellt rör)
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#7a98a8');
  grad.addColorStop(0.45, '#4a6a7a');
  grad.addColorStop(0.5, '#3a5a6a');
  grad.addColorStop(0.55, '#4a6a7a');
  grad.addColorStop(1, '#1a3040');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Top-highlight (reflective shine)
  ctx.fillStyle = 'rgba(220,240,255,0.5)';
  ctx.fillRect(x, y + 1, w, 2);
  // Botten-skugga
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(x, y + h - 2, w, 2);
  // Flänsar i ändarna (bredare cirkel-bands)
  ctx.fillStyle = '#3a4a55';
  ctx.fillRect(x, y - 2, 8, h + 4);
  ctx.fillRect(x + w - 8, y - 2, 8, h + 4);
  ctx.strokeStyle = '#1a2a35';
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 0.5, y - 2, 7, h + 4);
  ctx.strokeRect(x + w - 7.5, y - 2, 7, h + 4);
  // Bolts på flänsarna
  const placeBolt = (bx, by) => {
    ctx.fillStyle = '#1a1a1a';
    ctx.beginPath(); ctx.arc(bx, by, 1.5, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#aaa';
    ctx.beginPath(); ctx.arc(bx - 0.3, by - 0.3, 0.6, 0, Math.PI * 2); ctx.fill();
  };
  placeBolt(x + 4, y);
  placeBolt(x + 4, y + h - 1);
  placeBolt(x + w - 4, y);
  placeBolt(x + w - 4, y + h - 1);
  // Rost-strimmor längs röret
  ctx.fillStyle = 'rgba(120,60,20,0.4)';
  ctx.fillRect(x + w * 0.3, y + h * 0.3, 2, h * 0.4);
  ctx.fillRect(x + w * 0.65, y + h * 0.5, 2, h * 0.3);
}

// Crate: trälåda med plankor, hörn-band, stamps
function drawCrate(x, y, w, h, seed) {
  // Gradient-bakgrund för wood-tone
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#9a6a3a');
  grad.addColorStop(0.5, '#7a4a20');
  grad.addColorStop(1, '#5a3010');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Plankor (horisontella separator-linjer)
  ctx.strokeStyle = '#3a1a0a';
  ctx.lineWidth = 1.2;
  const plankCount = Math.max(2, Math.floor(h / 25));
  for (let i = 1; i < plankCount; i++) {
    const py = y + (h / plankCount) * i;
    ctx.beginPath();
    ctx.moveTo(x + 2, py);
    ctx.lineTo(x + w - 2, py);
    ctx.stroke();
  }
  // Trä-grain (subtila vertikala streck) — använd seed så grain inte vandrar
  ctx.strokeStyle = 'rgba(40,20,5,0.3)';
  ctx.lineWidth = 0.6;
  const hash = seed || 0;
  for (let i = 0; i < 4; i++) {
    const gx = x + 4 + ((hash * (i + 1) * 13) & 0x7f) % (w - 8);
    ctx.beginPath();
    ctx.moveTo(gx, y + 2);
    ctx.lineTo(gx, y + h - 2);
    ctx.stroke();
  }
  // Hörn-metall-bands (mörka L-shapes)
  ctx.fillStyle = '#3a2818';
  const cornerSize = Math.min(8, Math.floor(Math.min(w, h) * 0.25));
  // Top-left
  ctx.fillRect(x, y, cornerSize, 2);
  ctx.fillRect(x, y, 2, cornerSize);
  // Top-right
  ctx.fillRect(x + w - cornerSize, y, cornerSize, 2);
  ctx.fillRect(x + w - 2, y, 2, cornerSize);
  // Bottom-left
  ctx.fillRect(x, y + h - 2, cornerSize, 2);
  ctx.fillRect(x, y + h - cornerSize, 2, cornerSize);
  // Bottom-right
  ctx.fillRect(x + w - cornerSize, y + h - 2, cornerSize, 2);
  ctx.fillRect(x + w - 2, y + h - cornerSize, 2, cornerSize);
  // Nitar i hörnen
  const placeNail = (nx, ny) => {
    ctx.fillStyle = '#1a1010';
    ctx.beginPath(); ctx.arc(nx, ny, 1.3, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#888';
    ctx.beginPath(); ctx.arc(nx - 0.2, ny - 0.2, 0.5, 0, Math.PI * 2); ctx.fill();
  };
  placeNail(x + 3, y + 3);
  placeNail(x + w - 3, y + 3);
  placeNail(x + 3, y + h - 3);
  placeNail(x + w - 3, y + h - 3);
  // Stamp/label (om tillräckligt stor)
  if (w >= 60 && h >= 60) {
    ctx.save();
    ctx.translate(x + w / 2, y + h * 0.6);
    ctx.rotate(-0.08);
    ctx.fillStyle = 'rgba(20,10,5,0.55)';
    ctx.strokeStyle = 'rgba(20,10,5,0.55)';
    ctx.lineWidth = 1.5;
    ctx.font = 'bold ' + Math.floor(w * 0.18) + 'px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('AMMO', 0, 0);
    // Frame runt stamp
    ctx.strokeRect(-w * 0.28, -h * 0.12, w * 0.56, h * 0.24);
    ctx.restore();
  }
  // Yttre kant
  ctx.strokeStyle = '#1a0a05';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
}

// === JUGGERNAUT-WALL-RENDERS ====================================================

function drawConcreteWall(x, y, w, h) {
  // Perimeter-betong med mörk fog + textur
  const grad = ctx.createLinearGradient(x, y, x, y + h);
  grad.addColorStop(0, '#3a3a40');
  grad.addColorStop(0.5, '#2a2a2e');
  grad.addColorStop(1, '#1a1a1e');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Streckad fog ovanpå
  ctx.fillStyle = 'rgba(10,10,12,0.6)';
  ctx.fillRect(x, y, w, 2);
  ctx.fillRect(x, y + h - 2, w, 2);
  // Bullet-marks (random)
  ctx.fillStyle = '#0a0a0a';
  if (w > 100) {
    for (let i = 0; i < Math.min(8, w / 200); i++) {
      const mx = x + 20 + ((i * 137) % (w - 40));
      const my = y + (i % 2 === 0 ? 4 : h - 6);
      ctx.beginPath(); ctx.arc(mx, my, 1.5, 0, Math.PI * 2); ctx.fill();
    }
  }
}

function drawTruck(x, y, w, h, seed) {
  // Cargo-lastbil/skåpbil sett ovanifrån — cab + cargo + hjul + detaljer
  const isHorizontal = w > h;
  const bodyLen = isHorizontal ? w : h;
  const bodyW = isHorizontal ? h : w;
  // Lastbil-färg (deterministic per pos)
  const colors = ['#5a4a30', '#3a4a5a', '#5a3a3a', '#4a4a4a'];
  const bodyColor = colors[(seed >>> 4) & 3];
  const bodyDark = '#1a1a1a';
  ctx.save();
  ctx.translate(x, y);
  // Skugga under
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(2, 4, w, h);
  // Body shadow-dark stripe
  ctx.fillStyle = bodyDark;
  ctx.fillRect(0, 0, w, h);
  // Body main color
  ctx.fillStyle = bodyColor;
  ctx.fillRect(2, 2, w - 4, h - 4);
  // Cab (front kvadrat, mörkare)
  if (isHorizontal) {
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(w - 22, 2, 20, h - 4);
    ctx.fillStyle = '#0a1a3a';
    // Vindruta
    ctx.fillRect(w - 18, 4, 14, 6);
    // Reflektion på vindruta
    ctx.fillStyle = '#3a6a8a';
    ctx.fillRect(w - 17, 5, 6, 1);
    // Strålkastare
    ctx.fillStyle = '#fff8a0';
    ctx.shadowColor = '#fff8a0'; ctx.shadowBlur = 4;
    ctx.fillRect(w - 4, 4, 2, 3);
    ctx.fillRect(w - 4, h - 7, 2, 3);
    ctx.shadowBlur = 0;
  } else {
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(2, h - 22, w - 4, 20);
    ctx.fillStyle = '#0a1a3a';
    ctx.fillRect(4, h - 18, w - 8, 6);
    ctx.fillStyle = '#fff8a0';
    ctx.fillRect(4, h - 4, 3, 2);
    ctx.fillRect(w - 7, h - 4, 3, 2);
  }
  // Cargo-area panel-lines (3-4 vertikala)
  ctx.strokeStyle = bodyDark;
  ctx.lineWidth = 1;
  const panelCount = 4;
  if (isHorizontal) {
    for (let i = 1; i < panelCount; i++) {
      const px = (w - 22) * (i / panelCount);
      ctx.beginPath(); ctx.moveTo(px, 4); ctx.lineTo(px, h - 4); ctx.stroke();
    }
  } else {
    for (let i = 1; i < panelCount; i++) {
      const py = (h - 22) * (i / panelCount);
      ctx.beginPath(); ctx.moveTo(4, py); ctx.lineTo(w - 4, py); ctx.stroke();
    }
  }
  // Top-highlight
  ctx.fillStyle = mixColors(bodyColor, '#ffffff', 0.3);
  if (isHorizontal) ctx.fillRect(2, 2, w - 4, 1.5);
  else ctx.fillRect(2, 2, 1.5, h - 4);
  // 4 hjul (mörka cirklar i hörnen)
  ctx.fillStyle = '#0a0a0a';
  const wR = Math.min(bodyW * 0.18, 5);
  if (isHorizontal) {
    ctx.fillRect(8, -wR * 0.5, 10, wR * 0.7);
    ctx.fillRect(w - 30, -wR * 0.5, 10, wR * 0.7);
    ctx.fillRect(8, h - wR * 0.2, 10, wR * 0.7);
    ctx.fillRect(w - 30, h - wR * 0.2, 10, wR * 0.7);
  } else {
    ctx.fillRect(-wR * 0.5, 8, wR * 0.7, 10);
    ctx.fillRect(w - wR * 0.2, 8, wR * 0.7, 10);
    ctx.fillRect(-wR * 0.5, h - 30, wR * 0.7, 10);
    ctx.fillRect(w - wR * 0.2, h - 30, wR * 0.7, 10);
  }
  // Rost / slitage (3-4 fläckar)
  ctx.fillStyle = '#3a2a18';
  for (let i = 0; i < 4; i++) {
    const rx = 6 + ((seed * (i + 1) * 17) % (w - 30));
    const ry = 6 + ((seed * (i + 2) * 13) % (h - 12));
    ctx.fillRect(rx, ry, 3, 2);
  }
  // Yttre dark outline
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(0.5, 0.5, w - 1, h - 1);
  ctx.restore();
}

function drawVan(x, y, w, h, seed) {
  // Skåpbil — kortare än lastbil, mer kvadratisk
  drawTruck(x, y, w, h, seed); // återanvänd truck-design (mindre proportioner)
  // Lägg på en distinkt "VAN"-detalj: stege på taket (3 streck)
  ctx.save();
  ctx.strokeStyle = '#3a3a3a';
  ctx.lineWidth = 1.2;
  if (w > h) {
    ctx.beginPath();
    ctx.moveTo(x + 10, y + h / 2 - 2); ctx.lineTo(x + w - 30, y + h / 2 - 2);
    ctx.moveTo(x + 10, y + h / 2 + 2); ctx.lineTo(x + w - 30, y + h / 2 + 2);
    for (let i = 0; i < 4; i++) {
      const lx = x + 14 + i * ((w - 50) / 4);
      ctx.moveTo(lx, y + h / 2 - 2); ctx.lineTo(lx, y + h / 2 + 2);
    }
    ctx.stroke();
  }
  ctx.restore();
}

function drawCarWreck(x, y, w, h, seed) {
  // Utbrunnen bil: svart-sotigt skelett med trasiga fönster + öppna dörrar
  const isHorizontal = w > h;
  ctx.save();
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.fillRect(x + 2, y + 5, w, h);
  // Body — mycket mörk, sotad
  ctx.fillStyle = '#1a1410';
  ctx.fillRect(x, y, w, h);
  // Brand-fläckar / sot-streaks (mörkare)
  ctx.fillStyle = '#0a0808';
  for (let i = 0; i < 6; i++) {
    const fx = x + 4 + ((seed * (i + 1) * 19) % (w - 8));
    const fy = y + 4 + ((seed * (i + 3) * 23) % (h - 8));
    ctx.fillRect(fx, fy, 4, 3);
  }
  // Orange-roströd glow var här lågorna brunnit
  ctx.fillStyle = 'rgba(180, 60, 20, 0.25)';
  ctx.fillRect(x + 4, y + 4, w - 8, h - 8);
  // Trasiga fönster (mörka rektanglar)
  ctx.fillStyle = '#0a0a0a';
  if (isHorizontal) {
    ctx.fillRect(x + w * 0.2, y + 3, w * 0.6, 3);
    ctx.fillRect(x + w * 0.2, y + h - 6, w * 0.6, 3);
  } else {
    ctx.fillRect(x + 3, y + h * 0.2, 3, h * 0.6);
    ctx.fillRect(x + w - 6, y + h * 0.2, 3, h * 0.6);
  }
  // Tak (mörkare mid-stripe — välter / krossad)
  ctx.fillStyle = '#0a0a08';
  if (isHorizontal) {
    ctx.fillRect(x + w * 0.25, y + h * 0.35, w * 0.5, h * 0.3);
  } else {
    ctx.fillRect(x + w * 0.35, y + h * 0.25, w * 0.3, h * 0.5);
  }
  // Hjul — 4 förbrända ringar
  ctx.fillStyle = '#000';
  ctx.strokeStyle = '#3a1a08';
  ctx.lineWidth = 0.8;
  const wheels = isHorizontal
    ? [[x + 12, y - 1], [x + w - 12, y - 1], [x + 12, y + h + 1], [x + w - 12, y + h + 1]]
    : [[x - 1, y + 12], [x + w + 1, y + 12], [x - 1, y + h - 12], [x + w + 1, y + h - 12]];
  for (const [wx, wy] of wheels) {
    ctx.beginPath();
    ctx.ellipse(wx, wy, 5, 3, 0, 0, Math.PI*2);
    ctx.fill(); ctx.stroke();
  }
  // Rost-orange highlights (random)
  ctx.fillStyle = 'rgba(180, 90, 40, 0.4)';
  ctx.fillRect(x + 2, y + 2, w - 4, 0.5);
  ctx.fillRect(x + 2, y + h - 2.5, w - 4, 0.5);
  // Yttre dark outline
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  ctx.restore();
}

function drawGuardhouse(x, y, w, h) {
  // Vakthytt: liten betong-bod med fönster + dörr
  ctx.save();
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(x + 3, y + 5, w, h);
  // Bas: gradient grå betong
  const grad = ctx.createLinearGradient(x, y, x + w, y);
  grad.addColorStop(0, '#5a5a5a');
  grad.addColorStop(0.5, '#7a7a7a');
  grad.addColorStop(1, '#4a4a4a');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Tak (mörkt)
  ctx.fillStyle = '#2a2a2a';
  ctx.fillRect(x, y, w, 4);
  // Tak-highlight
  ctx.fillStyle = '#5a5a5a';
  ctx.fillRect(x, y, w, 1);
  // Stora fönster (2 framsidor — vänd mot center)
  ctx.fillStyle = '#1a3a5a';
  ctx.fillRect(x + 10, y + 12, w - 20, h - 30);
  // Vindruta reflektion
  ctx.fillStyle = '#3a6a8a';
  ctx.fillRect(x + 12, y + 14, (w - 24) * 0.4, 2);
  // Window-frame
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 10, y + 12, w - 20, h - 30);
  // Horisontellt fönster-streck (mitten)
  ctx.beginPath();
  ctx.moveTo(x + 10, y + 12 + (h - 30) / 2); ctx.lineTo(x + w - 10, y + 12 + (h - 30) / 2);
  ctx.stroke();
  // Vertikalt center-streck
  ctx.beginPath();
  ctx.moveTo(x + w / 2, y + 12); ctx.lineTo(x + w / 2, y + h - 18);
  ctx.stroke();
  // Dörr (under fönstret)
  ctx.fillStyle = '#3a2a1a';
  ctx.fillRect(x + (w - 14) / 2, y + h - 16, 14, 12);
  ctx.fillStyle = '#1a0a08';
  ctx.fillRect(x + (w - 14) / 2, y + h - 16, 14, 1);
  // Dörr-handtag
  ctx.fillStyle = '#ffd54a';
  ctx.fillRect(x + (w - 14) / 2 + 10, y + h - 10, 1.5, 2);
  // SECURITY-text på sidan
  ctx.fillStyle = '#ff5a3a';
  ctx.font = 'bold 7px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('SECURITY', x + w / 2, y + 9);
  // Yttre outline
  ctx.strokeStyle = '#1a1a1a';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  ctx.restore();
}

function drawRamp(x, y, w, h) {
  // Bilramp — diagonal gradient som ser ut som en sluttning
  ctx.save();
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.4)';
  ctx.fillRect(x + 2, y + 4, w, h);
  // Bas gradient (mörk → ljus → mörk = "valv-känsla")
  const grad = ctx.createLinearGradient(x, y, x + w, y);
  grad.addColorStop(0, '#2a2a2a');
  grad.addColorStop(0.5, '#5a5a5a');
  grad.addColorStop(1, '#2a2a2a');
  ctx.fillStyle = grad;
  ctx.fillRect(x, y, w, h);
  // Diagonala chevron-arrows (uppåt-pekande, gula) som indikerar slope
  ctx.strokeStyle = '#ffd54a';
  ctx.lineWidth = 2.5;
  const chevronCount = Math.max(2, Math.floor(w / 60));
  for (let i = 0; i < chevronCount; i++) {
    const cx = x + 15 + i * (w / chevronCount);
    ctx.beginPath();
    ctx.moveTo(cx, y + h * 0.75);
    ctx.lineTo(cx + 12, y + h * 0.35);
    ctx.lineTo(cx + 24, y + h * 0.75);
    ctx.stroke();
  }
  // Kant-striping (svart-gul varning)
  for (let i = 0; i < w; i += 12) {
    ctx.fillStyle = i % 24 < 12 ? '#ffd54a' : '#1a1a1a';
    ctx.fillRect(x + i, y, 12, 3);
    ctx.fillRect(x + i, y + h - 3, 12, 3);
  }
  // Yttre outline
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  ctx.restore();
}

function drawOilDrum(x, y, w, h, seed) {
  // Vanligt oljefat (icke-brinnande) — rostigt + lock + band
  ctx.save();
  const cx = x + w / 2, cy = y + h / 2;
  const r = Math.min(w, h) / 2;
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.beginPath(); ctx.ellipse(cx + 1.5, cy + 4, r + 1, 4, 0, 0, Math.PI*2); ctx.fill();
  // Fat-bas
  ctx.fillStyle = '#3a2818';
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2); ctx.fill();
  // Highlight-ring (vänster sida)
  ctx.fillStyle = '#6a4828';
  ctx.beginPath(); ctx.arc(cx - r * 0.3, cy - r * 0.3, r * 0.4, 0, Math.PI*2); ctx.fill();
  // Topp-lock (mörkare cirkel)
  ctx.fillStyle = '#1a1208';
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.85, 0, Math.PI*2); ctx.fill();
  // Lock-rim
  ctx.strokeStyle = '#5a3818';
  ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.arc(cx, cy, r * 0.85, 0, Math.PI*2); ctx.stroke();
  // Center-skruv (lock-handle)
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(cx - 1.5, cy - 1.5, 3, 3);
  ctx.fillStyle = '#3a3a3a';
  ctx.fillRect(cx - 1.5, cy - 1, 3, 0.5);
  // Rost-fläckar
  ctx.fillStyle = '#8a4818';
  ctx.fillRect(cx - r * 0.6, cy + r * 0.2, 3, 2);
  ctx.fillRect(cx + r * 0.3, cy - r * 0.5, 2, 2);
  // OIL-text om fatet är stort nog
  if (r > 14) {
    ctx.fillStyle = '#ffd54a';
    ctx.font = 'bold 6px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('OIL', cx, cy + 8);
  }
  // Yttre outline
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2); ctx.stroke();
  ctx.restore();
}

function drawFireDrum(x, y, w, h, seed) {
  // Brinnande oljefat — solid collision + animerade flammor + ljuspöl
  const cx = x + w / 2, cy = y + h / 2;
  const r = Math.min(w, h) / 2;
  const t = performance.now();
  const flicker = 0.85 + Math.sin(t / 70 + (seed & 0xff)) * 0.15;
  ctx.save();
  // Ljuspöl på golvet (rendera FÖRST så fat hamnar ovanpå)
  const lightR = 80;
  const lightGrad = ctx.createRadialGradient(cx, cy + 6, 4, cx, cy + 6, lightR);
  lightGrad.addColorStop(0, `rgba(255, 140, 50, ${0.45 * flicker})`);
  lightGrad.addColorStop(0.6, `rgba(255, 100, 30, ${0.15 * flicker})`);
  lightGrad.addColorStop(1, 'rgba(255, 80, 20, 0)');
  ctx.fillStyle = lightGrad;
  ctx.fillRect(cx - lightR, cy + 6 - lightR, lightR * 2, lightR * 2);
  // Skugga
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.beginPath(); ctx.ellipse(cx + 1, cy + 5, r + 2, 4, 0, 0, Math.PI*2); ctx.fill();
  // Fat-kropp (rostig mörk metall)
  ctx.fillStyle = '#2a1a0a';
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2); ctx.fill();
  // Vänster highlight
  ctx.fillStyle = '#4a2a1a';
  ctx.beginPath(); ctx.arc(cx - r * 0.3, cy - r * 0.3, r * 0.5, 0, Math.PI*2); ctx.fill();
  // 2 band runt fat
  ctx.strokeStyle = '#1a0808';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(cx - r, cy - r * 0.4); ctx.lineTo(cx + r, cy - r * 0.4);
  ctx.moveTo(cx - r, cy + r * 0.5); ctx.lineTo(cx + r, cy + r * 0.5);
  ctx.stroke();
  // Rost-fläckar
  ctx.fillStyle = '#7a3818';
  ctx.fillRect(cx - r * 0.5, cy + r * 0.1, 3, 2);
  ctx.fillRect(cx + r * 0.2, cy - r * 0.6, 2, 1.5);
  ctx.fillRect(cx - r * 0.3, cy + r * 0.6, 2, 1);
  // Topp-rim (mörkare)
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI*2); ctx.stroke();
  // FLAMMA (multi-lager animation)
  const flameH = r * 1.8 + Math.sin(t / 70) * 4;
  // Yttre orange
  ctx.fillStyle = `rgba(255, 100, 30, ${0.7 * flicker})`;
  ctx.beginPath();
  ctx.moveTo(cx - r * 0.7, cy - r * 0.3);
  ctx.quadraticCurveTo(cx - r * 0.5 + Math.sin(t / 100) * 2, cy - flameH * 0.55, cx - 2, cy - flameH * 0.85);
  ctx.quadraticCurveTo(cx + Math.sin(t / 80) * 3, cy - flameH, cx + 2, cy - flameH * 0.85);
  ctx.quadraticCurveTo(cx + r * 0.5 + Math.sin(t / 90) * 2, cy - flameH * 0.55, cx + r * 0.7, cy - r * 0.3);
  ctx.closePath(); ctx.fill();
  // Mid gul
  ctx.fillStyle = `rgba(255, 200, 60, ${0.85 * flicker})`;
  ctx.beginPath();
  ctx.moveTo(cx - r * 0.45, cy - r * 0.3);
  ctx.quadraticCurveTo(cx - r * 0.3 + Math.sin(t / 90) * 1.5, cy - flameH * 0.45, cx - 1, cy - flameH * 0.7);
  ctx.quadraticCurveTo(cx + Math.sin(t / 70) * 2, cy - flameH * 0.8, cx + 1, cy - flameH * 0.7);
  ctx.quadraticCurveTo(cx + r * 0.3 + Math.sin(t / 95) * 1.5, cy - flameH * 0.45, cx + r * 0.45, cy - r * 0.3);
  ctx.closePath(); ctx.fill();
  // Vit hot-core
  ctx.fillStyle = `rgba(255, 250, 220, ${0.9 * flicker})`;
  ctx.beginPath();
  ctx.ellipse(cx + Math.sin(t / 60) * 1, cy - flameH * 0.35, 2, 5, 0, 0, Math.PI*2); ctx.fill();
  // Glow ovanpå
  ctx.shadowColor = '#ff7030'; ctx.shadowBlur = 16 * flicker;
  ctx.fillStyle = `rgba(255, 180, 50, ${0.5 * flicker})`;
  ctx.beginPath(); ctx.arc(cx, cy - flameH * 0.3, 3, 0, Math.PI*2); ctx.fill();
  ctx.shadowBlur = 0;
  // Sparks (flyger upp)
  const sparkSeed = Math.floor(t / 100) + (seed & 0xff);
  for (let i = 0; i < 4; i++) {
    const sphase = (t / 800 + i * 0.25) % 1;
    const sx = cx + Math.sin((sparkSeed + i) * 13) * 6;
    const sy = cy - r - sphase * 40;
    ctx.fillStyle = `rgba(255, ${150 + i * 30}, 50, ${1 - sphase})`;
    ctx.beginPath(); ctx.arc(sx, sy, 1 + (1 - sphase) * 0.7, 0, Math.PI*2); ctx.fill();
  }
  ctx.restore();
}

function drawLamppost(x, y, w, h, worldX, worldY) {
  // Tak-monterad lyktstolpe (sticker NER från taket). Pole + lamp-head + light-pool
  // Använd world-coords för deterministic flicker per pos
  const t = performance.now();
  const flickerSeed = ((worldX * 17 + worldY * 23) | 0);
  const flickerPhase = (t / 1000) * 4 + flickerSeed * 0.1;
  const flickerNoise = Math.sin(flickerPhase * 7.3) * Math.cos(flickerPhase * 11.7);
  const isOn = flickerNoise > -0.3;
  const intensity = isOn ? (0.8 + Math.sin(flickerPhase * 3.2) * 0.2) : (Math.random() < 0.08 ? 0.35 : 0);
  ctx.save();
  // Ljus-pöl på marken — render FÖRST
  if (intensity > 0.1) {
    const poolR = 95;
    const poolGrad = ctx.createRadialGradient(x + w / 2, y + h + 14, 4, x + w / 2, y + h + 14, poolR);
    poolGrad.addColorStop(0, `rgba(220, 230, 255, ${0.35 * intensity})`);
    poolGrad.addColorStop(0.45, `rgba(180, 210, 255, ${0.18 * intensity})`);
    poolGrad.addColorStop(1, 'rgba(180, 210, 255, 0)');
    ctx.fillStyle = poolGrad;
    ctx.fillRect(x + w / 2 - poolR, y + h + 14 - poolR, poolR * 2, poolR * 2);
  }
  // Skugga under pole
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.fillRect(x + 2, y + 4, w, h);
  // Pole-bas (mörk metall)
  ctx.fillStyle = '#1a1a20';
  ctx.fillRect(x, y, w, h);
  // Pole highlight (vänster)
  ctx.fillStyle = '#3a3a48';
  ctx.fillRect(x, y, 1.5, h);
  // Pole top-cap (mörk topp)
  ctx.fillStyle = '#0a0a0e';
  ctx.fillRect(x - 1, y - 1, w + 2, 2);
  // Lamp-fixture (sticker ut ovanpå pole — lampskärm)
  ctx.fillStyle = '#0a0a0a';
  ctx.fillRect(x - 6, y - 7, w + 12, 5);
  // Lampskärm-inner-glow när på
  if (intensity > 0.05) {
    ctx.fillStyle = `rgba(220, 240, 255, ${intensity})`;
    ctx.shadowColor = '#a8d0ff'; ctx.shadowBlur = 14 * intensity;
    ctx.fillRect(x - 5, y - 6, w + 10, 3);
    ctx.shadowBlur = 0;
    // Vit hot-streak
    ctx.fillStyle = `rgba(255, 255, 255, ${intensity * 0.7})`;
    ctx.fillRect(x - 5, y - 5.5, w + 10, 1);
  } else {
    // Av — mörkt
    ctx.fillStyle = '#0a0a0a';
    ctx.fillRect(x - 5, y - 6, w + 10, 3);
  }
  // Lampskärm-fastsättnings-skruvar
  ctx.fillStyle = '#3a3a40';
  ctx.beginPath(); ctx.arc(x - 4, y - 4, 0.7, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(x + w + 4, y - 4, 0.7, 0, Math.PI*2); ctx.fill();
  // Mount-bracket (övre del — tak-fastsättning)
  ctx.fillStyle = '#2a2a30';
  ctx.fillRect(x - 2, y - 12, w + 4, 5);
  ctx.fillStyle = '#5a5a60';
  ctx.fillRect(x - 2, y - 12, w + 4, 1);
  ctx.restore();
}

function drawBrokenPillar(x, y, w, h, seed) {
  // Trasig pelare — exponerad rebar + sprickor + raserad topp
  drawPillar(x, y, w, h, seed);
  ctx.save();
  // Stor diagonal spricka
  ctx.strokeStyle = '#0a0a0a';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(x, y + h * 0.3);
  ctx.lineTo(x + w * 0.5, y + h * 0.5);
  ctx.lineTo(x + w, y + h * 0.4);
  ctx.stroke();
  // Exponerad rebar (rostig metallpinne sticker ut)
  ctx.strokeStyle = '#8a4818';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(x + w * 0.3, y - 4);
  ctx.lineTo(x + w * 0.3, y + h * 0.4);
  ctx.moveTo(x + w * 0.7, y - 6);
  ctx.lineTo(x + w * 0.7, y + h * 0.3);
  ctx.stroke();
  // Rebar-böjningar (top)
  ctx.beginPath();
  ctx.moveTo(x + w * 0.3, y - 4); ctx.lineTo(x + w * 0.3 - 3, y - 8);
  ctx.moveTo(x + w * 0.7, y - 6); ctx.lineTo(x + w * 0.7 + 4, y - 9);
  ctx.stroke();
  // Concrete-chunks-rubble vid botten
  ctx.fillStyle = '#3a3a40';
  ctx.fillRect(x - 2, y + h - 2, 4, 3);
  ctx.fillRect(x + w - 2, y + h - 3, 5, 4);
  ctx.fillStyle = '#5a5a60';
  ctx.fillRect(x - 1, y + h - 2, 1, 1);
  ctx.restore();
}

function drawTaggedPillar(x, y, w, h, seed) {
  // Tagged pelare — vanlig pelare med stor röd graffiti-tag
  drawPillar(x, y, w, h, seed);
  ctx.save();
  // Stor röd graffiti-tag (kryss / JUG-symbol)
  ctx.translate(x + w / 2, y + h / 2);
  ctx.font = 'italic 900 ' + Math.min(w, h) * 0.55 + 'px Impact, "Arial Black", sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.shadowColor = '#aa0000'; ctx.shadowBlur = 4;
  ctx.fillStyle = '#ff3030';
  ctx.fillText('JUG', 0, 0);
  ctx.shadowBlur = 0;
  // Spray-drips
  ctx.fillStyle = '#ff3030';
  ctx.fillRect(-w * 0.2, h * 0.05, 1, 6);
  ctx.fillRect(w * 0.15, h * 0.05, 1, 4);
  ctx.beginPath(); ctx.arc(-w * 0.2 + 0.5, h * 0.05 + 7, 1.2, 0, Math.PI*2); ctx.fill();
  ctx.restore();
}

// Linjär färgblandning. Stöder #rgb, #rrggbb. t=0→a, t=1→b.
function mixColors(a, b, t) {
  const parseHex = (h) => {
    if (!h || h[0] !== '#') return [255, 255, 255];
    const s = h.length === 4 ? h[1]+h[1]+h[2]+h[2]+h[3]+h[3] : h.slice(1);
    return [parseInt(s.substr(0,2),16), parseInt(s.substr(2,2),16), parseInt(s.substr(4,2),16)];
  };
  const [ar, ag, ab] = parseHex(a);
  const [br, bg, bb] = parseHex(b);
  const mix = (x, y) => Math.round(x + (y - x) * t);
  return 'rgb(' + mix(ar, br) + ',' + mix(ag, bg) + ',' + mix(ab, bb) + ')';
}

// CTF: rita decorations — skyltar, klotter, lyktor, små flaggor.
// Ingen collision, bara visuell flavor. Renderas under walls.
function drawCtfDecorations() {
  const decos = state.ctfDecorations;
  if (!decos || !decos.length) return;
  // Avrunda kameran så decorations inte vobblar vid kamera-pan (sub-pixel rendering).
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now();
  for (const d of decos) {
    const x = d.x - cx, y = d.y - cy;
    // Cull (med marginal för rot/text-bounds)
    if (x < -200 || x > viewW + 200 || y < -100 || y > viewH + 100) continue;
    ctx.save();
    if (d.kind === 'sign') {
      const w = d.w || 120, h = d.h || 28;
      ctx.translate(x + w / 2, y + h / 2);
      if (d.rot) ctx.rotate(d.rot);
      // Skylt-bakgrund
      ctx.fillStyle = d.bg || '#222';
      ctx.fillRect(-w / 2, -h / 2, w, h);
      ctx.strokeStyle = d.fg || '#ffd54a';
      ctx.lineWidth = 2;
      ctx.strokeRect(-w / 2 + 0.5, -h / 2 + 0.5, w - 1, h - 1);
      // Skylt-text (stöder \n)
      ctx.fillStyle = d.fg || '#ffd54a';
      const fontSize = d.size || Math.min(h - 8, 14);
      ctx.font = 'bold ' + fontSize + 'px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      const lines = String(d.text || '').split('\n');
      const lineH = fontSize + 2;
      const startY = -(lines.length - 1) * lineH / 2;
      for (let li = 0; li < lines.length; li++) {
        ctx.fillText(lines[li], 0, startY + li * lineH);
      }
      // Nedhängande "kedja"-look längs ovansidan så det ser fastsatt ut
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(-w / 2 - 2, -h / 2 - 4, 3, 4);
      ctx.fillRect(w / 2 - 1, -h / 2 - 4, 3, 4);
    } else if (d.kind === 'graffiti') {
      ctx.translate(x, y);
      if (d.rot) ctx.rotate(d.rot);
      const fontSize = d.size || 16;
      const text = d.text || '';
      const baseColor = d.color || '#fff';
      // Realistic spray-paint: 5 lager + drips
      // Använd condensed font för "tag"-känsla
      ctx.font = 'italic 900 ' + fontSize + 'px "Impact","Arial Black",sans-serif';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';
      // Mät för drips
      const metrics = ctx.measureText(text);
      const textW = metrics.width;
      // Layer 1: overspray haze runt hela texten (mörk halo)
      ctx.save();
      ctx.shadowColor = baseColor;
      ctx.shadowBlur = fontSize * 0.6;
      ctx.globalAlpha = 0.35;
      ctx.fillStyle = baseColor;
      ctx.fillText(text, 0, 0);
      ctx.restore();
      // Layer 2: tjock svart outline (kontur som ett tag)
      ctx.strokeStyle = '#000';
      ctx.lineWidth = Math.max(3, fontSize * 0.18);
      ctx.lineJoin = 'round';
      ctx.miterLimit = 2;
      ctx.globalAlpha = 0.85;
      ctx.strokeText(text, 0, 0);
      // Layer 3: huvudfärg fyllning
      ctx.fillStyle = baseColor;
      ctx.globalAlpha = 0.95;
      ctx.fillText(text, 0, 0);
      // Layer 4: ljusare highlight inom (upper-left, klassisk tag-style)
      ctx.fillStyle = mixColors(baseColor, '#ffffff', 0.45);
      ctx.globalAlpha = 0.55;
      ctx.fillText(text, -1, -1.5);
      // Layer 5: drips — droppar som rinner ner från bokstäver (deterministic hash)
      ctx.globalAlpha = 0.9;
      ctx.fillStyle = baseColor;
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 1;
      const dripHash = ((d.x * 13) | 0) + ((d.y * 7) | 0);
      const charSpacing = textW / Math.max(1, text.length);
      const numDrips = 2 + ((dripHash >> 3) & 0x3); // 2-5 drips
      for (let i = 0; i < numDrips; i++) {
        const charIdx = ((dripHash >> (i * 3)) & 0xff) % text.length;
        const dripX = charIdx * charSpacing + ((dripHash * (i + 1)) & 0xf) - 8;
        const dripLen = fontSize * 0.3 + ((dripHash >> i) & 0xf) * 0.8;
        const dropR = Math.max(1.5, fontSize * 0.08);
        // Vertikal streak
        ctx.fillRect(dripX, fontSize * 0.3, 1.5, dripLen);
        // Droppe i botten
        ctx.beginPath();
        ctx.arc(dripX + 0.75, fontSize * 0.3 + dripLen + dropR * 0.5, dropR, 0, Math.PI * 2);
        ctx.fill();
        // Subtil outline på droppen
        ctx.beginPath();
        ctx.arc(dripX + 0.75, fontSize * 0.3 + dripLen + dropR * 0.5, dropR, 0, Math.PI * 2);
        ctx.stroke();
      }
      // Layer 6: spray-dust speckles (små prickar runt texten)
      ctx.fillStyle = baseColor;
      ctx.globalAlpha = 0.6;
      const numSpeckles = 12 + ((dripHash >> 5) & 0x7);
      for (let i = 0; i < numSpeckles; i++) {
        const sx = ((dripHash * (i + 11)) & 0xff) / 255 * (textW + 30) - 15;
        const sy = (((dripHash >> 2) * (i + 7)) & 0xff) / 255 * (fontSize * 1.8) - fontSize * 0.7;
        const sr = 0.6 + (i & 1) * 0.4;
        ctx.beginPath();
        ctx.arc(sx, sy, sr, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    } else if (d.kind === 'flag_decoration') {
      // En riktig flagga: hög stolpe + topp-knopp + rektangulär våg-flagga med
      // animation. Mörk team-färg + ljusare highlight + svart kant + stjärna.
      const color = d.team === 'red' ? '#dd2020' : '#2050ff';
      const colorDark = d.team === 'red' ? '#8a0a0a' : '#0a2080';
      const colorLight = d.team === 'red' ? '#ff7070' : '#7090ff';
      // Hög stolpe (silver med träbas)
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - 1, y - 40, 2, 50);
      // Topp-knopp (gylne sphere)
      ctx.fillStyle = '#ffd54a';
      ctx.beginPath();
      ctx.arc(x, y - 41, 2.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 0.8;
      ctx.stroke();
      // Flagga: rektangulär med wave-effekt (segmenterad så den ser ut att fladdra)
      const flagW = 24;
      const flagH = 16;
      const flagTop = y - 38;
      const segments = 4;
      const segW = flagW / segments;
      // Bakgrund (mörk skugga under flagga)
      ctx.fillStyle = colorDark;
      ctx.beginPath();
      let py0 = flagTop;
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        if (i === 0) ctx.moveTo(px, py0 + wave);
        else ctx.lineTo(px, py0 + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        ctx.lineTo(px, py0 + flagH + wave);
      }
      ctx.closePath();
      ctx.fill();
      // Huvudfärg (samma form, lite mindre)
      ctx.fillStyle = color;
      ctx.beginPath();
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        if (i === 0) ctx.moveTo(px, py0 + 1 + wave);
        else ctx.lineTo(px, py0 + 1 + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        ctx.lineTo(px, py0 + flagH - 1 + wave);
      }
      ctx.closePath();
      ctx.fill();
      // Ljusare topp-highlight
      ctx.fillStyle = colorLight;
      ctx.beginPath();
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        if (i === 0) ctx.moveTo(px, py0 + 1 + wave);
        else ctx.lineTo(px, py0 + 1 + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        ctx.lineTo(px, py0 + 4 + wave);
      }
      ctx.closePath();
      ctx.fill();
      // Star i mitten (vit, klassisk team-symbol)
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 10px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = '#000';
      ctx.shadowBlur = 1;
      const starWave = Math.sin(t / 200 + segments * 0.3) * 2;
      ctx.fillText('★', x + 1 + flagW * 0.5, flagTop + flagH * 0.5 + starWave);
      ctx.shadowBlur = 0;
      // Kant runt flaggan
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        if (i === 0) ctx.moveTo(px, py0 + wave);
        else ctx.lineTo(px, py0 + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 200 + i * 0.6) * 2;
        const px = x + 1 + i * segW;
        ctx.lineTo(px, py0 + flagH + wave);
      }
      ctx.closePath();
      ctx.stroke();
    } else if (d.kind === 'lantern') {
      const color = d.color || '#ffb84a';
      // Glow
      const pulse = 0.6 + Math.sin(t / 380 + (x + y) * 0.001) * 0.4;
      const grad = ctx.createRadialGradient(x, y, 4, x, y, 60);
      grad.addColorStop(0, color);
      grad.addColorStop(0.4, color + '44');
      grad.addColorStop(1, 'transparent');
      ctx.globalAlpha = 0.45 * pulse;
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(x, y, 60, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
      // Lyktans bas
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - 4, y - 6, 8, 12);
      ctx.fillStyle = color;
      ctx.fillRect(x - 3, y - 5, 6, 10);
    }
    ctx.restore();
  }
}

// CTF: rita turrets — bas + roterande pipa + hp-bar + förstörd-version
function drawCtfTurrets() {
  if (!state.ctfTurrets) return;
  // Avrunda kameran så turret-baser inte vobblar vid kamera-pan
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now();
  for (const id of Object.keys(state.ctfTurrets)) {
    const tur = state.ctfTurrets[id];
    const x = tur.x - cx, y = tur.y - cy;
    if (x < -80 || x > viewW + 80 || y < -80 || y > viewH + 80) continue;
    ctx.save();
    const teamColor = tur.team === 'red' ? '#ff5a5a' : '#5aaaff';
    if (tur.destroyed) {
      // Förstörd: mörk vrak + flickering eld + rök-partiklar (spawnas av tick i runFrame)
      ctx.fillStyle = '#222';
      ctx.beginPath();
      ctx.arc(x, y, 24, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#444';
      ctx.lineWidth = 2;
      ctx.stroke();
      // Flickering eld
      const flicker = 0.5 + Math.random() * 0.5;
      ctx.fillStyle = `rgba(255,120,30,${flicker * 0.6})`;
      ctx.beginPath();
      ctx.arc(x + (Math.random() - 0.5) * 8, y + (Math.random() - 0.5) * 8, 8 + Math.random() * 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = `rgba(255,200,60,${flicker * 0.4})`;
      ctx.beginPath();
      ctx.arc(x + (Math.random() - 0.5) * 4, y + (Math.random() - 0.5) * 4, 4 + Math.random() * 3, 0, Math.PI * 2);
      ctx.fill();
      // Spawna rök-partiklar då och då
      if (state.particles && state.particles.length < 200 && Math.random() < 0.15) {
        state.particles.push({
          x: tur.x + (Math.random() - 0.5) * 16,
          y: tur.y + (Math.random() - 0.5) * 16,
          vx: (Math.random() - 0.5) * 20,
          vy: -30 - Math.random() * 30,
          life: 1.2 + Math.random() * 0.8,
          color: 'rgba(80,80,80,0.5)',
          r: 8 + Math.random() * 4,
          isExplosion: true,
        });
      }
      // Rebuild-progress-ring: grön båge när team-spelare står och repar
      const p = tur.rebuildProgress || 0;
      if (p > 0) {
        ctx.lineWidth = 4;
        // Bakgrunds-spår
        ctx.strokeStyle = 'rgba(255,255,255,0.15)';
        ctx.beginPath();
        ctx.arc(x, y, 32, 0, Math.PI * 2);
        ctx.stroke();
        // Progress
        ctx.strokeStyle = '#5aff5a';
        ctx.shadowColor = '#5aff5a';
        ctx.shadowBlur = 10;
        ctx.beginPath();
        ctx.arc(x, y, 32, -Math.PI / 2, -Math.PI / 2 + p * Math.PI * 2);
        ctx.stroke();
        ctx.shadowBlur = 0;
        // Tid kvar (sekunder)
        const sLeft = Math.ceil((1 - p) * 20);
        ctx.fillStyle = '#5aff5a';
        ctx.font = 'bold 13px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(sLeft + 's', x, y - 40);
      }
    } else {
      // Aktiv: bas-cirkel
      ctx.fillStyle = '#333';
      ctx.beginPath();
      ctx.arc(x, y, tur.r, 0, Math.PI * 2);
      ctx.fill();
      // Lag-färgad ring
      ctx.strokeStyle = teamColor;
      ctx.lineWidth = 3;
      ctx.stroke();
      // Inner-detalj (turret-bas-skiva)
      ctx.fillStyle = '#555';
      ctx.beginPath();
      ctx.arc(x, y, tur.r * 0.65, 0, Math.PI * 2);
      ctx.fill();
      // Pipa — roterar mot occupants aim (vi har inte den, så vi pekar mot mid-arena)
      const aim = tur.aim || 0; // server kan skicka detta senare; tills då pekar mot mitten
      const dirX = Math.cos(aim), dirY = Math.sin(aim);
      ctx.strokeStyle = '#222';
      ctx.lineWidth = 8;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + dirX * (tur.r + 10), y + dirY * (tur.r + 10));
      ctx.stroke();
      ctx.lineCap = 'butt';
      // Occupant-indikator
      if (tur.occupantId) {
        const pulse = 0.6 + Math.sin(t / 200) * 0.4;
        ctx.fillStyle = `rgba(255,213,74,${pulse})`;
        ctx.beginPath();
        ctx.arc(x, y, 5, 0, Math.PI * 2);
        ctx.fill();
      }
      // HP-bar ovanför om skadad
      if (tur.hp < tur.maxHp) {
        const bw = 50;
        const hpFrac = Math.max(0, tur.hp / tur.maxHp);
        ctx.fillStyle = 'rgba(0,0,0,0.6)';
        ctx.fillRect(x - bw / 2 - 1, y - tur.r - 16, bw + 2, 7);
        ctx.fillStyle = hpFrac > 0.5 ? '#5aff5a' : (hpFrac > 0.25 ? '#ffd54a' : '#ff5a5a');
        ctx.fillRect(x - bw / 2, y - tur.r - 15, bw * hpFrac, 5);
      }
    }
    ctx.restore();
  }
}

// CTF: rita walls — använd detaljerade drawPvpWalls med pixel-art per kind.
// Tidigare var detta en separat simpel version som ALDRIG anropade
// drawPvpWalls → nya detaljerade grafiken syntes aldrig.
function drawCtfWalls() {
  drawPvpWalls(state.ctfWalls);
}

// CTF: rita flag-stands + dropped flags + carrier-flagga ovanför bärare
function drawCtfFlags() {
  const flags = state.ctfFlags;
  if (!flags) return;
  // Avrunda kameran så flag-stands inte vobblar vid kamera-pan
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now();
  const pulse = 0.7 + Math.sin(t / 250) * 0.3;
  ctx.save();

  const drawFlagStand = (team, f) => {
    const x = f.baseX - cx, y = f.baseY - cy;
    if (x < -60 || x > viewW + 60 || y < -60 || y > viewH + 60) return;
    const color = team === 'red' ? '#ff5a5a' : '#5aaaff';
    // Capture-zon ring (alltid synlig)
    ctx.strokeStyle = team === 'red' ? 'rgba(255,90,90,0.35)' : 'rgba(90,170,255,0.35)';
    ctx.lineWidth = 2;
    ctx.setLineDash([8, 6]);
    ctx.beginPath();
    ctx.arc(x, y, state.ctfCaptureRadius || 50, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
    // Pulserande glow när flagga är hemma
    if (f.atBase) {
      const glowR = 32 + pulse * 8;
      const grad = ctx.createRadialGradient(x, y, 8, x, y, glowR);
      grad.addColorStop(0, team === 'red' ? 'rgba(255,90,90,0.55)' : 'rgba(90,170,255,0.55)');
      grad.addColorStop(1, team === 'red' ? 'rgba(255,90,90,0)' : 'rgba(90,170,255,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(x, y, glowR, 0, Math.PI * 2);
      ctx.fill();
    }
    // Stor stolpe (hög + tjock, snyggare än tunn rektangel)
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(x - 2, y - 38, 4, 60);
    ctx.strokeStyle = '#444';
    ctx.lineWidth = 0.6;
    ctx.strokeRect(x - 2, y - 38, 4, 60);
    // Topp-knopp (gylne sphere)
    ctx.fillStyle = '#ffd54a';
    ctx.beginPath();
    ctx.arc(x, y - 40, 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1;
    ctx.stroke();
    // Cirkulär bas-platta (hexagonal-look)
    const colorDark = team === 'red' ? '#5a1010' : '#102050';
    ctx.fillStyle = colorDark;
    ctx.beginPath();
    ctx.arc(x, y + 24, 14, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y + 24, 11, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1.5;
    ctx.stroke();
    // Team-emblem på basen (☆)
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 12px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('★', x, y + 24);
    // Stor flagga med wave-segment, kant och stjärna (samma stil som flag_decoration)
    if (f.atBase) {
      const colorLight = team === 'red' ? '#ff7070' : '#7090ff';
      const flagW = 36;
      const flagH = 26;
      const flagTop = y - 36;
      const segments = 5;
      const segW = flagW / segments;
      // Skugga
      ctx.fillStyle = colorDark;
      ctx.beginPath();
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        if (i === 0) ctx.moveTo(px, flagTop + wave);
        else ctx.lineTo(px, flagTop + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        ctx.lineTo(px, flagTop + flagH + wave);
      }
      ctx.closePath();
      ctx.fill();
      // Huvudfärg
      ctx.fillStyle = color;
      ctx.beginPath();
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        if (i === 0) ctx.moveTo(px, flagTop + 1.5 + wave);
        else ctx.lineTo(px, flagTop + 1.5 + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        ctx.lineTo(px, flagTop + flagH - 1.5 + wave);
      }
      ctx.closePath();
      ctx.fill();
      // Top-highlight
      ctx.fillStyle = colorLight;
      ctx.beginPath();
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        if (i === 0) ctx.moveTo(px, flagTop + 1.5 + wave);
        else ctx.lineTo(px, flagTop + 1.5 + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        ctx.lineTo(px, flagTop + 6 + wave);
      }
      ctx.closePath();
      ctx.fill();
      // Stjärna i mitten
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 16px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = '#000';
      ctx.shadowBlur = 2;
      const starWave = Math.sin(t / 180 + segments * 0.27) * 3;
      ctx.fillText('★', x + 2 + flagW * 0.5, flagTop + flagH * 0.5 + starWave);
      ctx.shadowBlur = 0;
      // Kant
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      for (let i = 0; i <= segments; i++) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        if (i === 0) ctx.moveTo(px, flagTop + wave);
        else ctx.lineTo(px, flagTop + wave);
      }
      for (let i = segments; i >= 0; i--) {
        const wave = Math.sin(t / 180 + i * 0.55) * 3;
        const px = x + 2 + i * segW;
        ctx.lineTo(px, flagTop + flagH + wave);
      }
      ctx.closePath();
      ctx.stroke();
    }
  };

  const drawDroppedFlag = (team, f) => {
    const x = f.x - cx, y = f.y - cy;
    if (x < -40 || x > viewW + 40 || y < -40 || y > viewH + 40) return;
    const color = team === 'red' ? '#ff5a5a' : '#5aaaff';
    // Auto-return countdown ring (30s)
    const droppedAge = f.droppedAt ? (t - f.droppedAt) / 1000 : 0;
    const timeLeft = Math.max(0, 30 - droppedAge);
    const frac = timeLeft / 30;
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.8;
    ctx.beginPath();
    ctx.arc(x, y, 18, -Math.PI / 2, -Math.PI / 2 + frac * Math.PI * 2);
    ctx.stroke();
    ctx.globalAlpha = 1;
    // Pulserande glow
    const glowR = 14 + pulse * 4;
    const grad = ctx.createRadialGradient(x, y, 4, x, y, glowR);
    grad.addColorStop(0, team === 'red' ? 'rgba(255,90,90,0.8)' : 'rgba(90,170,255,0.8)');
    grad.addColorStop(1, team === 'red' ? 'rgba(255,90,90,0)' : 'rgba(90,170,255,0)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(x, y, glowR, 0, Math.PI * 2);
    ctx.fill();
    // Flag-emoji + tyg
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x - 2, y - 8);
    ctx.lineTo(x + 12, y - 4);
    ctx.lineTo(x - 2, y);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.fillStyle = '#3a2a1a';
    ctx.fillRect(x - 3, y - 9, 2, 18);
  };

  const drawCarrierFlag = (team, carrierId) => {
    let carrier = null;
    if (carrierId === Coop.myId && state.player) carrier = state.player;
    else if (Coop.players && Coop.players.has(carrierId)) carrier = Coop.players.get(carrierId);
    if (!carrier || carrier.x === undefined) return;
    const x = carrier.x - cx, y = carrier.y - cy;
    if (x < -40 || x > viewW + 40 || y < -40 || y > viewH + 40) return;
    const color = team === 'red' ? '#ff5a5a' : '#5aaaff';
    const wave = Math.sin(t / 150) * 3;
    // Flagga ovanför huvudet
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x, y - 24);
    ctx.lineTo(x + 16 + wave, y - 20);
    ctx.lineTo(x, y - 16);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1;
    ctx.stroke();
    // Stolpe
    ctx.fillStyle = '#3a2a1a';
    ctx.fillRect(x - 1, y - 26, 2, 14);
    // Trail (partiklar i lagets färg)
    if ((carrier._trailTimer === undefined || t - carrier._trailTimer > 80)) {
      carrier._trailTimer = t;
      if (state.particles && state.particles.length < 200) {
        state.particles.push({
          x: carrier.x, y: carrier.y + 8, vx: 0, vy: 0, life: 0.55,
          color: team === 'red' ? 'rgba(255,90,90,0.7)' : 'rgba(90,170,255,0.7)',
          r: 5, isBloodPool: true,
        });
      }
    }
  };

  // Stands (alltid rita) + dropped/carrier (per state)
  for (const team of ['red', 'blue']) {
    const f = flags[team];
    if (!f) continue;
    drawFlagStand(team, f);
    if (f.carrierId) drawCarrierFlag(team, f.carrierId);
    else if (!f.atBase) drawDroppedFlag(team, f);
  }
  ctx.restore();
}

// PvP-pickups (HP-regen + shield-regen) — rita pulserande ikoner på arenan.
// Tillgängliga = full färg + pulse, otillgängliga = tonad ghost.
function drawPvpPickups() {
  const cx = state.camera.x, cy = state.camera.y;
  const t = performance.now();
  const pulse = 0.7 + Math.sin(t / 250) * 0.3;
  ctx.save();
  for (const id of Object.keys(state.pvpPickups)) {
    const pu = state.pvpPickups[id];
    const x = pu.x - cx, y = pu.y - cy;
    if (x < -30 || x > viewW + 30 || y < -30 || y > viewH + 30) continue;
    const isHp = pu.type === 'hp';
    const color = isHp ? '#5aff5a' : '#3acaff';
    if (!pu.available) {
      // Tonad ghost-version + respawn-progress-ring
      ctx.globalAlpha = 0.25;
      ctx.strokeStyle = color;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(x, y, 14, 0, Math.PI * 2);
      ctx.stroke();
      ctx.globalAlpha = 1;
      // OBS: INGEN ctx.restore() här! Outer ctx.save() är på rad 2154 (en gång),
      // och final ctx.restore() är på rad 2208. Tidigare buggrest pop'ade outer-save
      // mitt i loopen → final restore pop'ade en save från en TIDIGARE funktion
      // (drawCtfFlags etc.) → canvas-state-leak ("ljus blir helt ljust") + ev. krasch
      // i Chrome → render() bail'ade → minimap + timer + dark-overlays försvann.
      continue;
    }
    // Glow
    const glowR = 18 + pulse * 6;
    const grad = ctx.createRadialGradient(x, y, 4, x, y, glowR);
    grad.addColorStop(0, isHp ? 'rgba(90,255,90,0.55)' : 'rgba(58,202,255,0.55)');
    grad.addColorStop(1, isHp ? 'rgba(90,255,90,0)' : 'rgba(58,202,255,0)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(x, y, glowR, 0, Math.PI * 2);
    ctx.fill();
    // Ikon
    if (isHp) {
      // Grön + (kors-form)
      ctx.fillStyle = '#5aff5a';
      ctx.fillRect(x - 9, y - 3, 18, 6);
      ctx.fillRect(x - 3, y - 9, 6, 18);
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(x - 9, y - 3, 18, 6);
      ctx.strokeRect(x - 3, y - 9, 6, 18);
    } else {
      // Cyan diamant (shield)
      ctx.fillStyle = '#3acaff';
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(x, y - 10);
      ctx.lineTo(x + 8, y);
      ctx.lineTo(x, y + 10);
      ctx.lineTo(x - 8, y);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
    }
  }
  ctx.restore();
}

// PvP shield-bubble: rita runt spelare som är immuna. Visas för mig + alla
// partners som har aktiv shield. Renderas i alla PvP-lägen.
function drawPvpShieldBubbles() {
  const now = performance.now();
  const draw = (wx, wy) => {
    const x = wx - state.camera.x, y = wy - state.camera.y;
    if (x < -60 || x > viewW + 60 || y < -60 || y > viewH + 60) return;
    const pulse = 0.7 + Math.sin(now / 120) * 0.3;
    ctx.save();
    // Outer ring
    ctx.strokeStyle = `rgba(140,255,200,${0.55 * pulse})`;
    ctx.lineWidth = 3;
    ctx.shadowColor = '#5aff9a';
    ctx.shadowBlur = 18 * pulse;
    ctx.beginPath();
    ctx.arc(x, y, 26, 0, Math.PI * 2);
    ctx.stroke();
    // Inner glow
    const grad = ctx.createRadialGradient(x, y, 8, x, y, 26);
    grad.addColorStop(0, `rgba(140,255,200,${0.18 * pulse})`);
    grad.addColorStop(1, 'rgba(140,255,200,0)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(x, y, 26, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  };
  if (state.player && state.player.pvpShieldUntil && now < state.player.pvpShieldUntil) {
    draw(state.player.x, state.player.y);
  }
  if (typeof Coop !== 'undefined' && Coop.players) {
    for (const [, p] of Coop.players) {
      if (p.pvpShieldUntil && now < p.pvpShieldUntil && p.x !== undefined) {
        draw(p.x, p.y);
      }
    }
  }
}

// CTF: rita hold-to-return progress-ring runt spelaren när de håller över egen dropped-flag
function drawCtfReturnHold() {
  const hold = state.ctfReturnHold;
  if (!hold || !state.player) return;
  const elapsed = performance.now() - hold.startAt;
  const frac = Math.min(1, elapsed / (hold.durationMs || 1000));
  const px = state.player.x - state.camera.x;
  const py = state.player.y - state.camera.y;
  const color = hold.team === 'red' ? '#ff5a5a' : '#5aaaff';
  ctx.save();
  // Outer ring (track)
  ctx.strokeStyle = 'rgba(255,255,255,0.18)';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(px, py, 26, 0, Math.PI * 2);
  ctx.stroke();
  // Progress arc
  ctx.strokeStyle = color;
  ctx.lineWidth = 4;
  ctx.shadowColor = color;
  ctx.shadowBlur = 10;
  ctx.beginPath();
  ctx.arc(px, py, 26, -Math.PI / 2, -Math.PI / 2 + frac * Math.PI * 2);
  ctx.stroke();
  // Label
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 11px sans-serif';
  ctx.textAlign = 'center';
  ctx.shadowBlur = 4;
  ctx.shadowColor = '#000';
  ctx.fillText('RETUR ' + Math.round(frac * 100) + '%', px, py - 38);
  ctx.restore();
}

// CTF: HUD-banner när FIENDEN bär min flagga (defenders behöver veta) + arrow mot carrier
function drawCtfStolenFlagAlert() {
  if (!state.ctfFlags || !Coop.ctfTeams) return;
  const myTeam = Coop.ctfTeams[Coop.myId];
  if (!myTeam) return;
  const myFlag = state.ctfFlags[myTeam];
  if (!myFlag || !myFlag.carrierId) return;
  const carrierId = myFlag.carrierId;
  let carrier = null;
  if (carrierId === Coop.myId && state.player) carrier = state.player;
  else if (Coop.players && Coop.players.has(carrierId)) carrier = Coop.players.get(carrierId);
  if (!carrier || carrier.x === undefined) return;
  const carrierName = (Coop.players.get(carrierId) && Coop.players.get(carrierId).name) || 'Fiende';
  const color = myTeam === 'red' ? '#ff5a5a' : '#5aaaff';

  ctx.save();
  // Banner top-center (just under score-bar)
  const bannerY = 84;
  const pulse = 0.85 + Math.sin(performance.now() / 180) * 0.15;
  ctx.globalAlpha = pulse;
  ctx.fillStyle = 'rgba(0,0,0,0.78)';
  const text = '⚠ ' + carrierName.toUpperCase() + ' STAL ER FLAGGA!';
  ctx.font = 'bold 13px sans-serif';
  const w = ctx.measureText(text).width + 24;
  ctx.fillRect(viewW / 2 - w / 2, bannerY, w, 26);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(viewW / 2 - w / 2, bannerY, w, 26);
  ctx.fillStyle = color;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, viewW / 2, bannerY + 13);
  ctx.globalAlpha = 1;

  // Directional arrow mot carrier (om utanför skärm) — pekar från player mot carrier
  const px = state.player ? state.player.x - state.camera.x : viewW / 2;
  const py = state.player ? state.player.y - state.camera.y : viewH / 2;
  const cx = carrier.x - state.camera.x;
  const cy = carrier.y - state.camera.y;
  const offScreen = cx < 30 || cx > viewW - 30 || cy < 30 || cy > viewH - 30;
  if (offScreen && state.player) {
    const ang = Math.atan2(cy - py, cx - px);
    const r = Math.min(viewW, viewH) * 0.32;
    const ax = viewW / 2 + Math.cos(ang) * r;
    const ay = viewH / 2 + Math.sin(ang) * r;
    ctx.save();
    ctx.translate(ax, ay);
    ctx.rotate(ang);
    ctx.fillStyle = color;
    ctx.shadowColor = color;
    ctx.shadowBlur = 12;
    ctx.beginPath();
    ctx.moveTo(18, 0);
    ctx.lineTo(-8, -10);
    ctx.lineTo(-8, 10);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
  ctx.restore();
}

// SIEGE — decorations använder samma renderer som CTF (samma data-format)
function drawSiegeDecorations() {
  if (!state.siegeDecorations || !state.siegeDecorations.length) return;
  // Tillfälligt swap state.ctfDecorations så vi kan återanvända drawCtfDecorations.
  // Try/finally så swap restoreas även om drawCtfDecorations throwar.
  const saved = state.ctfDecorations;
  state.ctfDecorations = state.siegeDecorations;
  try { drawCtfDecorations(); }
  finally { state.ctfDecorations = saved; }
}

// JUGGERNAUT-dedikerad decoration-render. Hanterar alla parking-garage-
// specifika dekoration-typer (flicker_light, puddle, fire_drum, drain,
// caution_tape, parking_lines, shopping_cart, abandoned_bag, warning_triangle).
// Sign + graffiti faller tillbaka till drawCtfDecorations.
function drawJuggernautDecorations(decos) {
  if (!decos || !decos.length) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now();
  // Sortera så vi ritar markdekor (puddle/parking_lines/drain) FÖRE höjd-element
  // (fire_drum/shopping_cart) — annars hamnar pölar ovanpå objekt.
  const groundKinds = ['puddle', 'parking_lines', 'drain', 'caution_tape'];
  const ordered = [];
  for (const d of decos) if (groundKinds.indexOf(d.kind) >= 0) ordered.push(d);
  for (const d of decos) if (groundKinds.indexOf(d.kind) < 0) ordered.push(d);
  // CTF-decoration-fallback-kinds (sign + graffiti) — låt drawCtfDecorations
  // hantera dem. Vi behöver swappa in vår array kortvarigt.
  const ctfFallbackKinds = ['sign', 'graffiti', 'flag_decoration', 'lantern'];
  for (const d of ordered) {
    if (ctfFallbackKinds.indexOf(d.kind) >= 0) continue; // hanteras nedan
    const x = d.x - cx, y = d.y - cy;
    if (x < -200 || x > viewW + 200 || y < -200 || y > viewH + 200) continue;
    ctx.save();

    if (d.kind === 'puddle') {
      // Vatten-pöl: mörk reflective fläck med oregelbunden kant + highlight
      const r = d.r || 60;
      const grad = ctx.createRadialGradient(x, y, 2, x, y, r);
      grad.addColorStop(0, 'rgba(40, 50, 80, 0.7)');
      grad.addColorStop(0.7, 'rgba(20, 25, 40, 0.55)');
      grad.addColorStop(1, 'rgba(20, 25, 40, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      // Oregelbunden bubble-form (8 punkter med deterministic variation)
      const seed = ((d.x * 13) | 0) + ((d.y * 7) | 0);
      for (let i = 0; i < 16; i++) {
        const a = (i / 16) * Math.PI * 2;
        const variation = 0.85 + (((seed >> i) & 0x1f) / 31) * 0.3;
        const px = x + Math.cos(a) * r * variation;
        const py = y + Math.sin(a) * r * 0.6 * variation; // mer oval
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath(); ctx.fill();
      // Highlights (reflektion av lampor ovan)
      ctx.fillStyle = 'rgba(140, 180, 255, 0.4)';
      ctx.beginPath(); ctx.ellipse(x - r * 0.3, y - r * 0.2, r * 0.18, r * 0.05, 0, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = 'rgba(200, 220, 255, 0.3)';
      ctx.beginPath(); ctx.ellipse(x + r * 0.2, y + r * 0.1, r * 0.12, r * 0.04, 0, 0, Math.PI*2); ctx.fill();
      // Subtle ripple-animation
      const ripplePulse = (t / 800 + (d.x * 0.001) + (d.y * 0.001)) % 1;
      if (ripplePulse < 0.5) {
        ctx.strokeStyle = `rgba(160, 200, 255, ${(0.5 - ripplePulse) * 0.6})`;
        ctx.lineWidth = 0.6;
        ctx.beginPath();
        ctx.ellipse(x, y, r * 0.4 * (0.3 + ripplePulse), r * 0.25 * (0.3 + ripplePulse), 0, 0, Math.PI*2);
        ctx.stroke();
      }

    } else if (d.kind === 'drain') {
      // Golvbrunn: mörk fyrkantig öppning med metall-galler (parallella streck)
      const w = 22, h = 22;
      ctx.fillStyle = '#0a0a0a';
      ctx.fillRect(x - w/2, y - h/2, w, h);
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - w/2 + 1, y - h/2 + 1, w - 2, h - 2);
      // Galler-stänger
      ctx.fillStyle = '#3a3a3a';
      for (let i = 0; i < 5; i++) {
        ctx.fillRect(x - w/2 + 2 + i * 4, y - h/2 + 2, 2, h - 4);
      }
      // Highlight på galler-toppen
      ctx.fillStyle = '#5a5a5a';
      for (let i = 0; i < 5; i++) {
        ctx.fillRect(x - w/2 + 2 + i * 4, y - h/2 + 2, 2, 0.5);
      }
      // Mörk skugga runt
      ctx.strokeStyle = 'rgba(0,0,0,0.5)';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(x - w/2 - 1, y - h/2 - 1, w + 2, h + 2);

    } else if (d.kind === 'parking_lines') {
      // Vita parkeringsstreck: rader av streck längs en horisontell linje
      const count = d.count || 5;
      const dir = d.dir || 'h';
      const lineLen = 60, spacing = 70;
      ctx.fillStyle = 'rgba(220, 220, 200, 0.75)';
      ctx.strokeStyle = 'rgba(140, 140, 120, 0.4)';
      ctx.lineWidth = 0.5;
      if (dir === 'h') {
        for (let i = 0; i < count; i++) {
          const lx = x + i * spacing;
          if (lx < -lineLen || lx > viewW) continue;
          // Streck — något slitet med subtil fade
          ctx.fillRect(lx, y - 2, lineLen, 4);
          ctx.strokeRect(lx, y - 2, lineLen, 4);
          // Slitage-fläckar (utspridda mörkare prickar för worn look)
          ctx.fillStyle = 'rgba(60, 60, 50, 0.25)';
          const wear = ((d.x * 13 + i * 17) | 0);
          for (let j = 0; j < 3; j++) {
            const wx = lx + ((wear * (j + 1)) & 0x3f);
            ctx.fillRect(wx, y - 1, 4, 2);
          }
          ctx.fillStyle = 'rgba(220, 220, 200, 0.75)';
        }
      }

    } else if (d.kind === 'caution_tape') {
      // OUT OF ORDER-tape: gul-svart diagonalt streck-mönster
      const w = d.w || 80, h = 8;
      ctx.save();
      ctx.translate(x, y);
      if (d.rot) ctx.rotate(d.rot);
      // Gul bas
      ctx.fillStyle = '#ffd54a';
      ctx.fillRect(-w / 2, -h / 2, w, h);
      // Svarta diagonaler
      ctx.fillStyle = '#1a1a1a';
      for (let i = 0; i < w / 6; i++) {
        ctx.beginPath();
        ctx.moveTo(-w / 2 + i * 6, -h / 2);
        ctx.lineTo(-w / 2 + i * 6 - h, h / 2);
        ctx.lineTo(-w / 2 + i * 6 + 3 - h, h / 2);
        ctx.lineTo(-w / 2 + i * 6 + 3, -h / 2);
        ctx.closePath(); ctx.fill();
      }
      // Mörk kant
      ctx.strokeStyle = '#1a1a1a';
      ctx.lineWidth = 0.6;
      ctx.strokeRect(-w / 2, -h / 2, w, h);
      // "CAUTION"-text liten
      ctx.fillStyle = '#1a1a1a';
      ctx.font = 'bold 6px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('CAUTION', 0, 0);
      ctx.restore();

    } else if (d.kind === 'fire_drum') {
      // Brinnande oljefat: stor cylinder + flammor + ljuspöl
      const color = d.color || '#ff7a30';
      // Ljuspöl på golvet runt fat (varmt orange glow)
      const lightR = 80;
      const lightGrad = ctx.createRadialGradient(x, y + 6, 4, x, y + 6, lightR);
      const flicker = 0.85 + Math.sin(t / 80) * 0.15;
      lightGrad.addColorStop(0, `rgba(255, 140, 50, ${0.35 * flicker})`);
      lightGrad.addColorStop(0.6, `rgba(255, 100, 30, ${0.12 * flicker})`);
      lightGrad.addColorStop(1, 'rgba(255, 80, 20, 0)');
      ctx.fillStyle = lightGrad;
      ctx.fillRect(x - lightR, y - lightR + 6, lightR * 2, lightR * 2);
      // Fat-skugga
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.beginPath(); ctx.ellipse(x + 2, y + 12, 14, 4, 0, 0, Math.PI*2); ctx.fill();
      // Fat-kropp (rostig mörk metall)
      ctx.fillStyle = '#2a1a0a';
      ctx.fillRect(x - 11, y - 8, 22, 20);
      // Fat-highlight (vänster sida)
      ctx.fillStyle = '#4a2a1a';
      ctx.fillRect(x - 11, y - 8, 3, 20);
      // Fat-rim top
      ctx.fillStyle = '#3a2418';
      ctx.fillRect(x - 11, y - 8, 22, 2);
      // 2 horisontella band runt fatet
      ctx.strokeStyle = '#1a1208';
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.moveTo(x - 11, y - 2); ctx.lineTo(x + 11, y - 2);
      ctx.moveTo(x - 11, y + 6); ctx.lineTo(x + 11, y + 6);
      ctx.stroke();
      // Rost-fläckar
      ctx.fillStyle = '#6a3818';
      ctx.fillRect(x - 8, y + 1, 3, 2);
      ctx.fillRect(x + 3, y - 4, 2, 1.5);
      ctx.fillRect(x - 5, y + 8, 2, 1);
      // FLAMMAN (fladdrar, multiple layers)
      const flameH = 22 + Math.sin(t / 70) * 4;
      // Yttre orange flame
      ctx.fillStyle = `rgba(255, 100, 30, ${0.7 * flicker})`;
      ctx.beginPath();
      ctx.moveTo(x - 8, y - 8);
      ctx.quadraticCurveTo(x - 6 + Math.sin(t / 100) * 2, y - flameH * 0.6, x - 2, y - flameH * 0.9);
      ctx.quadraticCurveTo(x + Math.sin(t / 80) * 3, y - flameH, x + 2, y - flameH * 0.9);
      ctx.quadraticCurveTo(x + 6 + Math.sin(t / 90) * 2, y - flameH * 0.6, x + 8, y - 8);
      ctx.closePath(); ctx.fill();
      // Mid yellow flame
      ctx.fillStyle = `rgba(255, 200, 60, ${0.85 * flicker})`;
      ctx.beginPath();
      ctx.moveTo(x - 5, y - 8);
      ctx.quadraticCurveTo(x - 3 + Math.sin(t / 90) * 1.5, y - flameH * 0.5, x - 1, y - flameH * 0.75);
      ctx.quadraticCurveTo(x + Math.sin(t / 70) * 2, y - flameH * 0.85, x + 1, y - flameH * 0.75);
      ctx.quadraticCurveTo(x + 3 + Math.sin(t / 95) * 1.5, y - flameH * 0.5, x + 5, y - 8);
      ctx.closePath(); ctx.fill();
      // Inner white-hot core
      ctx.fillStyle = `rgba(255, 250, 220, ${0.9 * flicker})`;
      ctx.beginPath();
      ctx.ellipse(x + Math.sin(t / 60) * 1, y - flameH * 0.4, 2, 5, 0, 0, Math.PI*2); ctx.fill();
      // Glow ovanpå
      ctx.shadowColor = '#ff7030'; ctx.shadowBlur = 18 * flicker;
      ctx.fillStyle = `rgba(255, 180, 50, ${0.4 * flicker})`;
      ctx.beginPath(); ctx.arc(x, y - 12, 3, 0, Math.PI*2); ctx.fill();
      ctx.shadowBlur = 0;
      // Random sparks som flyger uppåt
      const sparkSeed = Math.floor(t / 100);
      for (let i = 0; i < 3; i++) {
        const sphase = (t / 800 + i * 0.33) % 1;
        const sx = x + Math.sin((sparkSeed + i) * 13) * 6;
        const sy = y - 8 - sphase * 35;
        ctx.fillStyle = `rgba(255, ${150 + i * 30}, 50, ${1 - sphase})`;
        ctx.beginPath(); ctx.arc(sx, sy, 1 + (1 - sphase) * 0.6, 0, Math.PI*2); ctx.fill();
      }

    } else if (d.kind === 'flicker_light') {
      // Trasigt lysrör i tak: ljusrektangel + flackerande sken-pöl nedanför
      const color = d.color || '#a8d0ff';
      const flickerHz = d.flickerHz || 4;
      // Flackerings-mönster (deterministic + pseudo-random)
      const flickerSeed = ((d.x * 17 + d.y * 23) | 0);
      const flickerPhase = (t / 1000) * flickerHz + flickerSeed * 0.1;
      const flickerNoise = Math.sin(flickerPhase * 7.3) * Math.cos(flickerPhase * 11.7);
      const isOn = flickerNoise > -0.3; // ofta på, ibland av
      const intensity = isOn ? (0.75 + Math.sin(flickerPhase * 3.2) * 0.25) : (Math.random() < 0.1 ? 0.3 : 0);
      // Ljus-pöl på golvet
      const poolR = 90;
      if (intensity > 0.1) {
        const poolGrad = ctx.createRadialGradient(x, y + 12, 4, x, y + 12, poolR);
        poolGrad.addColorStop(0, `rgba(200, 220, 255, ${0.32 * intensity})`);
        poolGrad.addColorStop(0.5, `rgba(170, 200, 255, ${0.15 * intensity})`);
        poolGrad.addColorStop(1, 'rgba(170, 200, 255, 0)');
        ctx.fillStyle = poolGrad;
        ctx.fillRect(x - poolR, y + 12 - poolR, poolR * 2, poolR * 2);
      }
      // Lampskärm (rektangulär, tak-mounted, med skugga)
      ctx.fillStyle = 'rgba(0,0,0,0.45)';
      ctx.fillRect(x - 17, y - 6, 34, 8);
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - 16, y - 5, 32, 7);
      // Lysrör inside (when on: white-blue glow)
      if (intensity > 0.05) {
        ctx.fillStyle = `rgba(220, 240, 255, ${intensity})`;
        ctx.shadowColor = color; ctx.shadowBlur = 12 * intensity;
        ctx.fillRect(x - 14, y - 3, 28, 3);
        ctx.shadowBlur = 0;
        // Vit kärn-streak
        ctx.fillStyle = `rgba(255, 255, 255, ${intensity * 0.7})`;
        ctx.fillRect(x - 14, y - 2.5, 28, 0.8);
      } else {
        // Av — mörkt insida
        ctx.fillStyle = '#0a0a0a';
        ctx.fillRect(x - 14, y - 3, 28, 3);
      }
      // Skärm-skruv-detaljer
      ctx.fillStyle = '#0a0a0a';
      ctx.beginPath(); ctx.arc(x - 15, y - 4, 0.6, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 15, y - 4, 0.6, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x - 15, y + 1, 0.6, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 15, y + 1, 0.6, 0, Math.PI*2); ctx.fill();

    } else if (d.kind === 'shopping_cart') {
      // Övergiven shopping-cart: silver-gitter-korg + 4 hjul + handle
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath(); ctx.ellipse(x + 2, y + 9, 14, 3, 0, 0, Math.PI*2); ctx.fill();
      // Korg (silver-mesh-style)
      ctx.fillStyle = '#7a7a82';
      ctx.fillRect(x - 12, y - 6, 24, 14);
      // Mesh-pattern (vertical + horizontal grid)
      ctx.strokeStyle = '#3a3a40';
      ctx.lineWidth = 0.4;
      for (let i = -10; i <= 10; i += 3) {
        ctx.beginPath();
        ctx.moveTo(x + i, y - 6); ctx.lineTo(x + i, y + 8);
        ctx.stroke();
      }
      for (let i = -4; i <= 6; i += 3) {
        ctx.beginPath();
        ctx.moveTo(x - 12, y + i); ctx.lineTo(x + 12, y + i);
        ctx.stroke();
      }
      // Korg-rim (mörkare metall-ram)
      ctx.strokeStyle = '#3a3a40';
      ctx.lineWidth = 1;
      ctx.strokeRect(x - 12, y - 6, 24, 14);
      // Handle (silver-stång)
      ctx.fillStyle = '#9a9aa2';
      ctx.fillRect(x - 13, y - 9, 26, 1.5);
      ctx.fillStyle = '#cccfd5';
      ctx.fillRect(x - 13, y - 9, 26, 0.5);
      // Handle-grepp (svart plast)
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - 11, y - 9.5, 22, 2);
      // 4 hjul
      ctx.fillStyle = '#1a1a1a';
      ctx.beginPath(); ctx.arc(x - 9, y + 9, 2, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 9, y + 9, 2, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x - 9, y + 5, 1.5, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 9, y + 5, 1.5, 0, Math.PI*2); ctx.fill();
      // Hjul-highlights
      ctx.fillStyle = '#5a5a60';
      ctx.beginPath(); ctx.arc(x - 9.5, y + 8.5, 0.5, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 8.5, y + 8.5, 0.5, 0, Math.PI*2); ctx.fill();
      // Subtle rost (orange-brun fläck på kanten)
      ctx.fillStyle = 'rgba(140, 70, 30, 0.5)';
      ctx.fillRect(x + 10, y, 2, 4);

    } else if (d.kind === 'abandoned_bag') {
      // Övergiven väska/kasse: mörk taske med strap + zip
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath(); ctx.ellipse(x + 1, y + 7, 11, 2, 0, 0, Math.PI*2); ctx.fill();
      // Body (mörk brun/grön)
      ctx.fillStyle = '#3a2818';
      ctx.beginPath();
      ctx.moveTo(x - 9, y - 4);
      ctx.lineTo(x - 9, y + 6);
      ctx.lineTo(x + 9, y + 6);
      ctx.lineTo(x + 9, y - 4);
      ctx.quadraticCurveTo(x, y - 8, x - 9, y - 4);
      ctx.fill();
      // Highlight
      ctx.fillStyle = '#5a4028';
      ctx.fillRect(x - 9, y - 4, 18, 1);
      // Strap-handle ovanpå
      ctx.strokeStyle = '#2a1808';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(x, y - 5, 4, Math.PI, 0, false);
      ctx.stroke();
      // Zip-detaljer
      ctx.strokeStyle = '#1a1208';
      ctx.lineWidth = 0.5;
      ctx.beginPath();
      ctx.moveTo(x - 8, y - 1); ctx.lineTo(x + 8, y - 1);
      ctx.stroke();
      // Zip-puller (liten metall-bit)
      ctx.fillStyle = '#9a9a9a';
      ctx.fillRect(x - 1, y - 1.5, 2, 1);

    } else if (d.kind === 'floor_marking') {
      // Stor målad text på golvet (parking P, EXIT-arrow etc.) — slitet
      const text = d.text || 'P';
      const size = d.size || 80;
      const color = d.color || '#ffd54a';
      ctx.font = 'bold ' + size + 'px Impact, "Arial Black", sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      // Slitet utseende: 3 lager med fade + chips
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.fillText(text, x + 2, y + 2);
      ctx.fillStyle = color;
      ctx.globalAlpha = 0.72;
      ctx.fillText(text, x, y);
      // Slitage-chips (random svarta fläckar inom texten)
      ctx.globalAlpha = 1;
      ctx.fillStyle = 'rgba(20, 20, 24, 0.55)';
      const wearSeed = ((d.x * 13) ^ (d.y * 17)) | 0;
      for (let i = 0; i < 8; i++) {
        const wx = x + ((wearSeed * (i + 1) * 23) % size) - size * 0.5;
        const wy = y + ((wearSeed * (i + 3) * 31) % size) - size * 0.5;
        const wsz = 2 + ((wearSeed >> i) & 0x3);
        ctx.fillRect(wx, wy, wsz, wsz * 0.6);
      }
      // Subtle dark outline
      ctx.strokeStyle = 'rgba(0,0,0,0.5)';
      ctx.lineWidth = 1.5;
      ctx.strokeText(text, x, y);

    } else if (d.kind === 'ceiling_pipe') {
      // Horisontellt tak-rör — bred mörk balk med highlight + shadow
      // Halvtransparent för "tak ovanpå"-känsla
      const w = d.w || 1000;
      const dia = d.dia || 14;
      const color = d.color || '#5a4030';
      // Skugga på golvet (halvtransparent, lite offset)
      ctx.fillStyle = 'rgba(0,0,0,0.18)';
      ctx.fillRect(x, y + dia * 0.8, w, dia * 0.4);
      // Pipe-body (med skuggning)
      const grad = ctx.createLinearGradient(0, y, 0, y + dia);
      grad.addColorStop(0, '#1a1a1e');
      grad.addColorStop(0.3, color);
      grad.addColorStop(0.7, color);
      grad.addColorStop(1, '#0a0a0e');
      ctx.fillStyle = grad;
      ctx.globalAlpha = 0.82;
      ctx.fillRect(x, y, w, dia);
      // Highlight-streak ovanpå
      ctx.fillStyle = '#ffffff';
      ctx.globalAlpha = 0.15;
      ctx.fillRect(x, y + dia * 0.15, w, 1);
      // Pipe-joints/brackets (var ~250px)
      ctx.globalAlpha = 1;
      ctx.fillStyle = '#1a1a1a';
      const jointSpacing = 250;
      const startX = Math.floor((cx - x) / jointSpacing) * jointSpacing + x;
      for (let jx = Math.max(x, startX); jx < x + w && jx < cx + viewW + 20; jx += jointSpacing) {
        ctx.fillRect(jx - cx - 2, y, 4, dia);
        ctx.fillStyle = '#3a3a3a';
        ctx.fillRect(jx - cx - 2, y, 4, 1);
        ctx.fillStyle = '#1a1a1a';
      }
      // Rust-streaks (random vertical drips ned från piper)
      ctx.fillStyle = 'rgba(140, 70, 30, 0.35)';
      const rustSeed = ((d.x * 7) ^ (d.y * 11)) | 0;
      for (let i = 0; i < Math.min(8, w / 200); i++) {
        const rx = x + ((rustSeed * (i + 1) * 19) % w);
        ctx.fillRect(rx - cx, y + dia, 1, 8);
      }
      ctx.globalAlpha = 1;

    } else if (d.kind === 'ceiling_pipe_v') {
      // Vertikalt tak-rör (samma logik som ceiling_pipe men rotated 90°)
      const h = d.h || 1000;
      const dia = d.dia || 10;
      const color = d.color || '#4a4a55';
      ctx.fillStyle = 'rgba(0,0,0,0.18)';
      ctx.fillRect(x + dia * 0.8, y, dia * 0.4, h);
      const grad = ctx.createLinearGradient(x, 0, x + dia, 0);
      grad.addColorStop(0, '#1a1a1e');
      grad.addColorStop(0.3, color);
      grad.addColorStop(0.7, color);
      grad.addColorStop(1, '#0a0a0e');
      ctx.fillStyle = grad;
      ctx.globalAlpha = 0.78;
      ctx.fillRect(x, y, dia, h);
      // Highlight
      ctx.fillStyle = '#ffffff';
      ctx.globalAlpha = 0.13;
      ctx.fillRect(x + dia * 0.15, y, 1, h);
      ctx.globalAlpha = 1;
      // Joints var 250px
      ctx.fillStyle = '#1a1a1a';
      const jointSpacing = 250;
      const startY = Math.floor((cy - y) / jointSpacing) * jointSpacing + y;
      for (let jy = Math.max(y, startY); jy < y + h && jy < cy + viewH + 20; jy += jointSpacing) {
        ctx.fillRect(x, jy - cy - 2, dia, 4);
        ctx.fillStyle = '#3a3a3a';
        ctx.fillRect(x, jy - cy - 2, 1, 4);
        ctx.fillStyle = '#1a1a1a';
      }

    } else if (d.kind === 'cable_bundle') {
      // Hängande kabel-knippe — flera kurviga linjer mellan 2 punkter
      const x2 = (d.x2 || d.x + 200) - cx;
      const y2 = (d.y2 || d.y) - cy;
      // Skugga
      ctx.strokeStyle = 'rgba(0,0,0,0.22)';
      ctx.lineWidth = 6;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(x, y + 6);
      const sagY = (y + y2) / 2 + 18;
      ctx.quadraticCurveTo((x + x2) / 2, sagY + 4, x2, y2 + 6);
      ctx.stroke();
      // 3 kabelfärger som hänger ihop i ett knippe
      const cableColors = ['#1a1a1a', '#2a2018', '#181820'];
      for (let i = 0; i < 3; i++) {
        ctx.strokeStyle = cableColors[i];
        ctx.lineWidth = 2.5 - i * 0.5;
        ctx.beginPath();
        ctx.moveTo(x, y + i * 1.5);
        ctx.quadraticCurveTo((x + x2) / 2, sagY + i * 1.2, x2, y2 + i * 1.5);
        ctx.stroke();
      }
      // Cable-clamps (mörka punkter där kablarna sitter fast i taket)
      ctx.fillStyle = '#0a0a0a';
      ctx.fillRect(x - 3, y - 2, 6, 5);
      ctx.fillRect(x2 - 3, y2 - 2, 6, 5);
      ctx.fillStyle = '#3a3a3a';
      ctx.fillRect(x - 3, y - 2, 6, 1);
      ctx.fillRect(x2 - 3, y2 - 2, 6, 1);

    } else if (d.kind === 'ceiling_drip') {
      // Tak-läcka: liten dropp som forms + faller med periodisk anim
      const dripPhase = (t / 1500 + (d.x * 0.001) + (d.y * 0.001)) % 1;
      // Tak-håll-punkt
      ctx.fillStyle = '#1a1a1a';
      ctx.beginPath(); ctx.arc(x, y - 60, 1.5, 0, Math.PI*2); ctx.fill();
      // Vått fuktig fläck runt håll-punkten
      ctx.fillStyle = 'rgba(40, 60, 90, 0.45)';
      ctx.beginPath();
      ctx.ellipse(x, y - 60, 6, 2, 0, 0, Math.PI*2); ctx.fill();
      // Droppe i fallning
      const dropY = y - 60 + dripPhase * 60;
      const dropAlpha = dripPhase < 0.9 ? 1 : (1 - dripPhase) * 10;
      ctx.fillStyle = `rgba(140, 180, 220, ${dropAlpha})`;
      ctx.beginPath();
      ctx.ellipse(x, dropY, 1.3, 2.5, 0, 0, Math.PI*2); ctx.fill();
      // Subtle trail-streak ovanför droppen
      if (dripPhase > 0.2) {
        ctx.strokeStyle = `rgba(140, 180, 220, ${0.3 * dropAlpha})`;
        ctx.lineWidth = 0.8;
        ctx.beginPath();
        ctx.moveTo(x, dropY - 8);
        ctx.lineTo(x, dropY);
        ctx.stroke();
      }
      // Splash vid impact (synlig kort)
      if (dripPhase > 0.92) {
        const splashAlpha = (dripPhase - 0.92) / 0.08;
        ctx.strokeStyle = `rgba(140, 180, 220, ${splashAlpha * 0.6})`;
        ctx.lineWidth = 0.8;
        ctx.beginPath();
        ctx.arc(x, y, 4 + splashAlpha * 3, 0, Math.PI*2);
        ctx.stroke();
      }

    } else if (d.kind === 'warning_triangle') {
      // Röd-vit varningstriangel (vanlig vägmarkering)
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath();
      ctx.moveTo(x + 1, y + 9); ctx.lineTo(x - 9, y + 9); ctx.lineTo(x + 1, y + 8);
      ctx.closePath(); ctx.fill();
      // Triangel-bas (svart kant)
      ctx.fillStyle = '#1a1a1a';
      ctx.beginPath();
      ctx.moveTo(x, y - 10); ctx.lineTo(x - 11, y + 8); ctx.lineTo(x + 11, y + 8);
      ctx.closePath(); ctx.fill();
      // Triangel inner (röd)
      ctx.fillStyle = '#ff3030';
      ctx.beginPath();
      ctx.moveTo(x, y - 8); ctx.lineTo(x - 9, y + 6); ctx.lineTo(x + 9, y + 6);
      ctx.closePath(); ctx.fill();
      // Vit inner
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.moveTo(x, y - 5); ctx.lineTo(x - 7, y + 5); ctx.lineTo(x + 7, y + 5);
      ctx.closePath(); ctx.fill();
      // Utropstecken
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(x - 0.8, y - 3, 1.6, 5);
      ctx.beginPath(); ctx.arc(x, y + 4, 0.9, 0, Math.PI*2); ctx.fill();
      // Bas-block (rektangulär fot)
      ctx.fillStyle = '#3a3a3a';
      ctx.fillRect(x - 5, y + 8, 10, 2);
    }

    ctx.restore();
  }
  // Sign + graffiti → drawCtfDecorations
  const fallback = decos.filter(d => ctfFallbackKinds.indexOf(d.kind) >= 0);
  if (fallback.length) {
    const saved = state.ctfDecorations;
    state.ctfDecorations = fallback;
    try { drawCtfDecorations(); } finally { state.ctfDecorations = saved; }
  }
}

// SIEGE: capture-bases — pulsande cirklar med owner-färg + capture-progress-ring
function drawKothZone() {
  if (!state.kothZones || state.kothActiveZoneIdx == null) return;
  const z = state.kothZones[state.kothActiveZoneIdx];
  if (!z) return;
  // KRITISKT: rendera i skärm-koords genom att subtrahera kameran. Render-loopen
  // använder INTE ctx.translate(-camera) globalt — varje draw-funktion subtraherar
  // själv. Glömd subtraktion = zonen ritas långt utanför skärmen.
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const sx = z.x - cx, sy = z.y - cy;
  // Viewport-cull: om hela cirkeln är utanför skärmen, skippa
  if (sx + z.r < -20 || sx - z.r > viewW + 20 || sy + z.r < -20 || sy - z.r > viewH + 20) return;
  const t = performance.now() / 1000;
  // Snabbare puls + röd-tint under warning-fas (5s före byte)
  const warningActive = state._kothWarningUntil && performance.now() < state._kothWarningUntil;
  const pulse = warningActive ? (0.4 + Math.sin(t * 12) * 0.6) : (0.85 + Math.sin(t * 2.4) * 0.15);
  ctx.save();
  // Gold ring + glow
  ctx.strokeStyle = '#ffd54a';
  ctx.lineWidth = 4;
  ctx.shadowColor = '#ffd54a';
  ctx.shadowBlur = 18 * pulse;
  ctx.globalAlpha = 0.75;
  ctx.beginPath();
  ctx.arc(sx, sy, z.r, 0, Math.PI * 2);
  ctx.stroke();
  // Inner fill
  ctx.shadowBlur = 0;
  ctx.fillStyle = 'rgba(255, 213, 74, 0.10)';
  ctx.fill();
  // Crown emblem i mitten
  ctx.fillStyle = '#ffd54a';
  ctx.font = 'bold 32px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.globalAlpha = 0.55 + pulse * 0.4;
  ctx.fillText('👑', sx, sy);
  // Zone-namn under
  ctx.font = 'bold 13px sans-serif';
  ctx.fillStyle = '#ffd54a';
  ctx.globalAlpha = 0.85;
  ctx.shadowColor = '#000'; ctx.shadowBlur = 4;
  ctx.fillText(z.name || 'HILL', sx, sy + 28);
  // Countdown till nästa zone-byte (om vi har info)
  if (state.kothNextRotateAt) {
    const sec = Math.max(0, Math.ceil((state.kothNextRotateAt - Date.now()) / 1000));
    ctx.font = 'bold 11px sans-serif';
    ctx.fillStyle = '#fff';
    ctx.shadowBlur = 3;
    ctx.fillText('byter om ' + sec + 's', sx, sy + 46);
  }
  // Contested-banner (>1 spelare i zonen) ovanför zone
  if (state._kothContestedUntil && performance.now() < state._kothContestedUntil) {
    ctx.font = 'bold 14px sans-serif';
    ctx.fillStyle = '#ff5a3a';
    ctx.globalAlpha = 0.95;
    ctx.shadowColor = '#000'; ctx.shadowBlur = 5;
    ctx.fillText('⏸ CONTESTED (' + (state._kothContestedCount || 2) + ')', sx, sy - 50);
  }
  ctx.restore();
}

function drawSiegeBases() {
  if (!state.siegeBases) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now();
  for (const id of Object.keys(state.siegeBases)) {
    const b = state.siegeBases[id];
    const x = b.x - cx, y = b.y - cy;
    if (x < -200 || x > viewW + 200 || y < -200 || y > viewH + 200) continue;
    let baseColor, baseRgb;
    if (b.owner === 'red') { baseColor = 'rgba(255,60,60,'; baseRgb = '255,60,60'; }
    else if (b.owner === 'blue') { baseColor = 'rgba(60,140,255,'; baseRgb = '60,140,255'; }
    else { baseColor = 'rgba(200,200,200,'; baseRgb = '200,200,200'; }  // ljus-grå för neutral
    const pulse = 0.7 + Math.sin(t / 500) * 0.3;
    ctx.save();
    // STARK inner-fyllning (mycket synligare än tidigare 0.15 alpha)
    const grad = ctx.createRadialGradient(x, y, 4, x, y, b.r);
    grad.addColorStop(0, baseColor + (0.55 * pulse) + ')');
    grad.addColorStop(0.7, baseColor + (0.25 * pulse) + ')');
    grad.addColorStop(1, baseColor + '0)');
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.arc(x, y, b.r, 0, Math.PI * 2); ctx.fill();
    // Tjock yttre dashed ring + GLOW
    ctx.strokeStyle = baseColor + (0.95 * pulse) + ')';
    ctx.lineWidth = 5;
    ctx.shadowColor = 'rgb(' + baseRgb + ')';
    ctx.shadowBlur = 14 * pulse;
    ctx.setLineDash([14, 8]);
    ctx.beginPath(); ctx.arc(x, y, b.r, 0, Math.PI * 2); ctx.stroke();
    ctx.setLineDash([]);
    ctx.shadowBlur = 0;
    // Capture-progress-ring med fas-färg
    if (b.captureProgress > 0 && b.captureSide) {
      // 'neutralize'-fas = gul-orange (rensar enemy-bas), 'capture'-fas = lag-färg
      let ringColor;
      if (b.phase === 'neutralize') ringColor = '#ffaa30';
      else ringColor = b.captureSide === 'red' ? '#ff5a5a' : '#5aaaff';
      ctx.strokeStyle = ringColor;
      ctx.lineWidth = 5;
      ctx.shadowColor = ringColor; ctx.shadowBlur = 12;
      ctx.beginPath();
      ctx.arc(x, y, b.r + 8, -Math.PI / 2, -Math.PI / 2 + b.captureProgress * Math.PI * 2);
      ctx.stroke();
      ctx.shadowBlur = 0;
      // Procent + fas-label
      ctx.fillStyle = ringColor;
      ctx.font = 'bold 11px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = '#000'; ctx.shadowBlur = 3;
      const label = b.phase === 'neutralize'
        ? 'NEUTRAL ' + Math.round(b.captureProgress * 100) + '%'
        : 'CAPTURE ' + Math.round(b.captureProgress * 100) + '%';
      ctx.fillText(label, x, y - b.r - 20);
      ctx.shadowBlur = 0;
    }
    // Contested-badge: visa "R vs B"-count om båda lagen står på basen
    const redOn = b.redOn || 0;
    const blueOn = b.blueOn || 0;
    if (redOn > 0 && blueOn > 0) {
      ctx.fillStyle = '#ffd54a';
      ctx.font = 'bold 12px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = '#000'; ctx.shadowBlur = 4;
      ctx.fillText('⏸ ' + redOn + ' vs ' + blueOn + ' — CONTESTED', x, y - b.r - 6);
      ctx.shadowBlur = 0;
    } else if (redOn > 0 || blueOn > 0) {
      // Visa antal capturers när en sida har basen
      const c = redOn || blueOn;
      const color = redOn ? '#ff8080' : '#80aaff';
      ctx.fillStyle = color;
      ctx.font = 'bold 11px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = '#000'; ctx.shadowBlur = 3;
      ctx.fillText('×' + c, x, y - b.r - 6);
      ctx.shadowBlur = 0;
    }
    // Centrum-emblem (⬢)
    ctx.fillStyle = b.owner === 'red' ? '#ff8080' : (b.owner === 'blue' ? '#80aaff' : '#999');
    ctx.font = 'bold 22px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = '#000'; ctx.shadowBlur = 4;
    ctx.fillText('⬢', x, y);
    ctx.shadowBlur = 0;
    ctx.restore();
  }
}

// SIEGE: cores — stor blinkande HP-bar + symbol över core-byggnaden
function drawSiegeCores() {
  if (!state.siegeCores) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now();
  for (const id of Object.keys(state.siegeCores)) {
    const c = state.siegeCores[id];
    const x = c.x - cx, y = c.y - cy;
    if (x + c.w < -100 || x > viewW + 100 || y + c.h < -100 || y > viewH + 100) continue;
    ctx.save();
    if (c.destroyed) {
      // Förstörd: röd skugga + flickering eld
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(x + 30, y + 30, c.w - 60, c.h - 60);
      const flicker = 0.5 + Math.random() * 0.5;
      ctx.fillStyle = `rgba(255,120,30,${flicker * 0.7})`;
      ctx.fillRect(x + c.w * 0.3, y + c.h * 0.3, c.w * 0.4, c.h * 0.4);
      if (state.particles && state.particles.length < 200 && Math.random() < 0.4) {
        state.particles.push({
          x: c.x + c.w / 2 + (Math.random() - 0.5) * c.w,
          y: c.y + c.h / 2 + (Math.random() - 0.5) * c.h,
          vx: (Math.random() - 0.5) * 30,
          vy: -50 - Math.random() * 40,
          life: 1.5 + Math.random(),
          color: 'rgba(80,80,80,0.5)',
          r: 10 + Math.random() * 5,
          isExplosion: true,
        });
      }
    } else {
      // Aktiv core: pulsande inner-light + emblem
      const pulse = 0.6 + Math.sin(t / 400) * 0.3;
      const teamColor = c.team === 'red' ? 'rgba(255,90,90,' : 'rgba(90,170,255,';
      ctx.fillStyle = teamColor + (0.25 * pulse) + ')';
      ctx.fillRect(x + 30, y + 30, c.w - 60, c.h - 60);
      // Stor team-emblem
      ctx.fillStyle = c.team === 'red' ? '#ff8080' : '#88aaff';
      ctx.font = 'bold 60px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = '#000'; ctx.shadowBlur = 8;
      ctx.fillText('🛡', x + c.w / 2, y + c.h / 2);
      ctx.shadowBlur = 0;
      // HP-bar ovanför core
      const bw = c.w - 40;
      const hpFrac = Math.max(0, c.hp / c.maxHp);
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(x + 20 - 2, y - 22, bw + 4, 12);
      ctx.fillStyle = hpFrac > 0.5 ? '#5aff5a' : (hpFrac > 0.25 ? '#ffd54a' : '#ff5a5a');
      ctx.fillRect(x + 20, y - 20, bw * hpFrac, 8);
      // HP-text
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 9px sans-serif';
      ctx.shadowColor = '#000'; ctx.shadowBlur = 2;
      ctx.fillText(Math.round(c.hp) + ' / ' + c.maxHp, x + c.w / 2, y - 16);
      ctx.shadowBlur = 0;
    }
    ctx.restore();
  }
}

// SIEGE: turrets — reuse CTF turret-rendering pattern men för siege state
function drawSiegeTurrets() {
  if (!state.siegeTurrets) return;
  const cx = Math.round(state.camera.x), cy = Math.round(state.camera.y);
  const t = performance.now();
  for (const id of Object.keys(state.siegeTurrets)) {
    const tur = state.siegeTurrets[id];
    const x = tur.x - cx, y = tur.y - cy;
    if (x < -80 || x > viewW + 80 || y < -80 || y > viewH + 80) continue;
    ctx.save();
    const teamColor = tur.team === 'red' ? '#ff5a5a' : '#5aaaff';
    if (tur.destroyed) {
      ctx.fillStyle = '#222';
      ctx.beginPath(); ctx.arc(x, y, 24, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#444'; ctx.lineWidth = 2; ctx.stroke();
      const flicker = 0.5 + Math.random() * 0.5;
      ctx.fillStyle = `rgba(255,120,30,${flicker * 0.6})`;
      ctx.beginPath(); ctx.arc(x, y, 8 + Math.random() * 4, 0, Math.PI * 2); ctx.fill();
      // Rebuild-progress-ring
      const p = tur.rebuildProgress || 0;
      if (p > 0) {
        ctx.lineWidth = 4;
        ctx.strokeStyle = 'rgba(255,255,255,0.15)';
        ctx.beginPath(); ctx.arc(x, y, 32, 0, Math.PI * 2); ctx.stroke();
        ctx.strokeStyle = '#5aff5a';
        ctx.shadowColor = '#5aff5a'; ctx.shadowBlur = 10;
        ctx.beginPath();
        ctx.arc(x, y, 32, -Math.PI / 2, -Math.PI / 2 + p * Math.PI * 2);
        ctx.stroke();
        ctx.shadowBlur = 0;
        const sLeft = Math.ceil((1 - p) * 20);
        ctx.fillStyle = '#5aff5a';
        ctx.font = 'bold 13px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(sLeft + 's', x, y - 40);
      }
    } else {
      ctx.fillStyle = '#333';
      ctx.beginPath(); ctx.arc(x, y, tur.r, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = teamColor; ctx.lineWidth = 3; ctx.stroke();
      ctx.fillStyle = '#555';
      ctx.beginPath(); ctx.arc(x, y, tur.r * 0.65, 0, Math.PI * 2); ctx.fill();
      // Pipa
      ctx.strokeStyle = '#222'; ctx.lineWidth = 8; ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + (tur.team === 'red' ? 1 : -1) * (tur.r + 10), y);
      ctx.stroke();
      ctx.lineCap = 'butt';
      if (tur.occupantId) {
        const pulse = 0.6 + Math.sin(t / 200) * 0.4;
        ctx.fillStyle = `rgba(255,213,74,${pulse})`;
        ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI * 2); ctx.fill();
      }
      if (tur.hp < tur.maxHp) {
        const bw = 50;
        const hpFrac = Math.max(0, tur.hp / tur.maxHp);
        ctx.fillStyle = 'rgba(0,0,0,0.6)';
        ctx.fillRect(x - bw / 2 - 1, y - tur.r - 16, bw + 2, 7);
        ctx.fillStyle = hpFrac > 0.5 ? '#5aff5a' : (hpFrac > 0.25 ? '#ffd54a' : '#ff5a5a');
        ctx.fillRect(x - bw / 2, y - tur.r - 15, bw * hpFrac, 5);
      }
    }
    ctx.restore();
  }
}

function drawCoopPartner() {
  if (!Coop.active || Coop.inLobby) return;
  const now = performance.now();
  for (const [pid, p] of Coop.players) {
    if (p.x === undefined) continue;
    const x = p.x - state.camera.x;
    const y = p.y - state.camera.y;
    // Detect movement för walk-animation
    if (p._prevX === undefined) { p._prevX = p.x; p._prevY = p.y; p._walkPhase = 0; }
    const moved = Math.hypot(p.x - p._prevX, p.y - p._prevY);
    p._walkPhase = (p._walkPhase || 0) + (moved > 0.5 ? 0.22 : 0.04);
    p._prevX = p.x; p._prevY = p.y;

    // Off-screen check (rita pil mot dem istället)
    if (x < -40 || x > viewW + 40 || y < -40 || y > viewH + 40) {
      drawOffscreenPartner(p, x, y);
      continue;
    }
    const color = PLAYER_COLORS[p.colorIdx % PLAYER_COLORS.length];
    const isDead = p.hp !== undefined && p.hp <= 0;

    // Om död — rita liggande kropp + revive-indikator
    if (isDead) {
      ctx.save();
      // Skugga
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.beginPath(); ctx.ellipse(x + 4, y + 8, 22, 8, 0, 0, Math.PI*2); ctx.fill();
      // Liggande kropp (oval)
      ctx.fillStyle = color;
      ctx.beginPath(); ctx.ellipse(x, y, 18, 11, 0.3, 0, Math.PI*2); ctx.fill();
      // Blod
      ctx.fillStyle = 'rgba(120,0,0,0.5)';
      ctx.beginPath(); ctx.ellipse(x - 2, y + 3, 14, 6, 0.3, 0, Math.PI*2); ctx.fill();
      // Revive-indikator (synkat med dead player's reviveTimer)
      if (p.reviveTimer && p.reviveTimer > 0) {
        const frac = Math.min(1, p.reviveTimer / 5);
        ctx.strokeStyle = '#5aff5a';
        ctx.lineWidth = 3;
        ctx.shadowColor = '#5aff5a'; ctx.shadowBlur = 8;
        ctx.beginPath();
        ctx.arc(x, y, 28, -Math.PI/2, -Math.PI/2 + frac * Math.PI*2);
        ctx.stroke();
        ctx.shadowBlur = 0;
        ctx.fillStyle = '#5aff5a';
        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(Math.ceil(5 - p.reviveTimer) + 's', x, y - 36);
      } else {
        ctx.fillStyle = '#ff5a5a';
        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center';
        ctx.shadowColor = '#000'; ctx.shadowBlur = 3;
        ctx.fillText('💀 ' + p.name, x, y - 16);
        ctx.shadowBlur = 0;
      }
      ctx.restore();
      continue;
    }

    // Levande — rita karaktär likt drawPlayer (förenklad)
    const r = 14;
    const phase = p._walkPhase;
    const moving = moved > 0.5;
    const bob = moving ? Math.abs(Math.sin(phase)) * 1.6 : Math.sin(phase) * 0.4;

    // Skugga (mjuk oval)
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.beginPath(); ctx.ellipse(x + 2, y + r * 1.1, r * 1.3, r * 0.45, 0, 0, Math.PI*2); ctx.fill();

    // Färg-aura under
    ctx.fillStyle = color + '22';
    ctx.beginPath(); ctx.arc(x, y, r * 1.6, 0, Math.PI*2); ctx.fill();

    ctx.save();
    ctx.translate(x, y + bob);
    ctx.rotate(p.aimAngle || 0);
    // JUG-scale + JUG-kostym i juggernaut-mode
    const _partnerIsJug = p.isJug && state.juggernautActive;
    const _partnerJugScale = (_partnerIsJug && p.scaleMul) ? p.scaleMul : 1;
    if (_partnerJugScale !== 1) ctx.scale(_partnerJugScale, _partnerJugScale);

    const skin = _partnerIsJug ? '#4a7a3a' : '#d4a574';
    const skinDark = _partnerIsJug ? '#2e5a26' : '#a07a52';
    const vest = _partnerIsJug ? '#1a1a14' : color;
    const vestDark = _partnerIsJug ? '#0a0a08' : darken(color, 0.7);
    const pants = _partnerIsJug ? '#2a1a0a' : '#3a3528';
    const boot = '#1a1208';

    // BEN (alternerar)
    const legSwing = Math.sin(phase);
    const lLegX = -r * 0.85 - legSwing * r * 0.2;
    const rLegX = -r * 0.85 + legSwing * r * 0.2;
    ctx.fillStyle = pants;
    ctx.fillRect(lLegX, -r * 0.55, r * 0.35, r * 0.4);
    ctx.fillStyle = boot;
    ctx.fillRect(lLegX, -r * 0.5, r * 0.35, r * 0.18);
    ctx.fillStyle = pants;
    ctx.fillRect(rLegX, r * 0.15, r * 0.35, r * 0.4);
    ctx.fillStyle = boot;
    ctx.fillRect(rLegX, r * 0.32, r * 0.35, r * 0.18);

    // VÄST (kropp)
    ctx.fillStyle = vest;
    ctx.beginPath(); ctx.ellipse(0, 0, r * 0.95, r * 1.3, 0, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = vestDark;
    ctx.beginPath(); ctx.ellipse(-r * 0.3, 0, r * 0.4, r * 1.15, 0, 0, Math.PI*2); ctx.fill();
    // Stitching
    ctx.strokeStyle = '#0a0a08';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, -r * 1.0); ctx.lineTo(0, r * 1.0);
    ctx.stroke();

    // AXLAR
    ctx.fillStyle = skin;
    ctx.beginPath(); ctx.ellipse(r * 0.05, -r * 1.0, r * 0.42, r * 0.36, 0, 0, Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(r * 0.05, r * 1.0, r * 0.42, r * 0.36, 0, 0, Math.PI*2); ctx.fill();

    // ARMAR
    ctx.beginPath(); ctx.ellipse(r * 0.55, -r * 0.85, r * 0.30, r * 0.28, 0, 0, Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(r * 0.55, r * 0.85, r * 0.30, r * 0.28, 0, 0, Math.PI*2); ctx.fill();

    // HUVUD
    ctx.fillStyle = skin;
    ctx.beginPath(); ctx.arc(r * 0.2, 0, r * 0.55, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = skinDark;
    ctx.beginPath(); ctx.arc(r * 0.05, 0, r * 0.32, 0, Math.PI*2); ctx.fill();

    // BANDANA i partnerns färg
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.ellipse(r * 0.18, 0, r * 0.60, r * 0.32, 0, 0, Math.PI*2); ctx.fill();

    // ÖGON
    ctx.fillStyle = '#0a0a0a';
    ctx.beginPath(); ctx.arc(r * 0.50, -r * 0.18, 1.8, 0, Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(r * 0.50, r * 0.18, 1.8, 0, Math.PI*2); ctx.fill();

    // VAPEN — enkelt, baserat på weaponId
    const w = p.weaponId ? W_BY_ID[p.weaponId] : null;
    const wColor = w && w.color ? w.color : '#1a1a1a';
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(r * 0.6, -r * 0.18, r * 1.4, r * 0.22);
    ctx.fillStyle = wColor;
    ctx.fillRect(r * 0.6, -r * 0.10, r * 0.6, r * 0.10);

    ctx.restore();

    // JUG-glow ring + crown om denna partner är JUG
    if (p.isJug && state.juggernautActive) {
      const now2 = performance.now();
      const pulse = 0.5 + Math.sin(now2 / 300) * 0.5;
      const ringR = r * (p.scaleMul || 1.8) + 6;
      ctx.save();
      ctx.strokeStyle = `rgba(255, 213, 74, ${0.6 + 0.4 * pulse})`;
      ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(x, y, ringR, 0, Math.PI * 2); ctx.stroke();
      const grad = ctx.createRadialGradient(x, y, ringR * 0.7, x, y, ringR * 1.5);
      grad.addColorStop(0, `rgba(255, 213, 74, ${0.25 * pulse})`);
      grad.addColorStop(1, 'rgba(255, 213, 74, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath(); ctx.arc(x, y, ringR * 1.5, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
    }

    // Namn-tag (🤖-prefix för bots så spelaren ser AI vs människor)
    ctx.fillStyle = (p.isJug && state.juggernautActive) ? '#ffd54a' : color;
    ctx.font = 'bold 11px sans-serif';
    ctx.textAlign = 'center';
    ctx.shadowColor = '#000'; ctx.shadowBlur = 4;
    const _crown = (p.isJug && state.juggernautActive) ? '👑 ' : '';
    const nameLabel = _crown + (p.isBot ? ('🤖 ' + p.name) : p.name);
    ctx.fillText(nameLabel, x, y - 28);
    ctx.shadowBlur = 0;
    // HP+shield som EN sammanhängande bar i PvP (shield blå ovanpå, HP grön
    // under — utan gap så det ser ut som en bar). Shield krymper först,
    // sedan HP. I story-coop: bara HP-bar.
    if (p.hp !== undefined) {
      const inPvP = state.tdmActive || state.ctfActive || state.siegeActive || state.gungameActive || state.kothActive || state.juggernautActive;
      const maxShield = inPvP ? (p.maxShield || state.pvpShieldMax || 100) : 0;
      const hasShield = inPvP && maxShield > 0;
      const barW = (p.isJug && state.juggernautActive) ? 50 : 36;
      const hpY = y - 24;
      // HP-bar (grön/team-färg) — JUG har högre maxHp så bar-fraktionen
      // måste relatera till p.maxHp om det är satt.
      const _maxHp = (p.maxHp && p.maxHp > 100) ? p.maxHp : 100;
      const hpFrac = Math.max(0, p.hp / _maxHp);
      ctx.fillStyle = '#5a0a0a';
      ctx.fillRect(x - barW/2, hpY, barW, 4);
      ctx.fillStyle = color;
      ctx.fillRect(x - barW/2, hpY, barW * hpFrac, 4);
      // Shield-bar DIREKT ovanpå (no gap) — bildar visuellt EN bar
      if (hasShield) {
        const shVal = (p.shield != null) ? p.shield : maxShield;
        const sFrac = Math.max(0, Math.min(1, shVal / maxShield));
        const shY = hpY - 3; // direkt ovanpå HP-bar (3px shield-höjd, no gap)
        ctx.fillStyle = 'rgba(15,30,55,0.85)';
        ctx.fillRect(x - barW/2, shY, barW, 3);
        if (sFrac > 0) {
          ctx.fillStyle = '#3acaff';
          ctx.shadowColor = '#3acaff';
          ctx.shadowBlur = 4;
          ctx.fillRect(x - barW/2, shY, barW * sFrac, 3);
          ctx.shadowBlur = 0;
        }
      }
    }
  }
}

function drawOffscreenPartner(p, sx, sy) {
  // Pil mot off-screen partner
  const cx = viewW/2, cy = viewH/2;
  const dx = sx - cx, dy = sy - cy;
  const ang = Math.atan2(dy, dx);
  const margin = 40;
  const halfW = viewW/2 - margin, halfH = viewH/2 - margin;
  let px, py;
  if (Math.abs(Math.tan(ang)) * halfW < halfH) {
    px = Math.cos(ang) > 0 ? cx + halfW : cx - halfW;
    py = cy + (px - cx) * Math.tan(ang);
  } else {
    py = Math.sin(ang) > 0 ? cy + halfH : cy - halfH;
    px = cx + (py - cy) / Math.tan(ang);
  }
  const color = PLAYER_COLORS[p.colorIdx % PLAYER_COLORS.length];
  ctx.save();
  ctx.translate(px, py);
  ctx.rotate(ang);
  ctx.fillStyle = color;
  ctx.shadowColor = color; ctx.shadowBlur = 6;
  ctx.beginPath();
  ctx.moveTo(0, 0); ctx.lineTo(-12, -8); ctx.lineTo(-12, 8);
  ctx.closePath(); ctx.fill();
  ctx.shadowBlur = 0;
  ctx.fillStyle = '#000';
  ctx.font = 'bold 9px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText(p.name, -6, 3);
  ctx.restore();
}

function drawDrone() {
  if (!state.drone || !state.drone.alive) return;
  const d = state.drone;
  const x = d.x - state.camera.x, y = d.y - state.camera.y;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(d.angle * 2);
  // Drone body
  ctx.fillStyle = '#1a1a22';
  ctx.fillRect(-8, -8, 16, 16);
  ctx.fillStyle = '#3acaff';
  ctx.shadowColor = '#3acaff'; ctx.shadowBlur = 6;
  ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();
  ctx.shadowBlur = 0;
  // Propellers
  ctx.fillStyle = '#3a3a44';
  for (let i = 0; i < 4; i++) {
    const a = i * Math.PI/2 + d.angle * 8;
    ctx.fillRect(Math.cos(a)*8 - 1, Math.sin(a)*8 - 1, 6, 2);
  }
  ctx.restore();
}

function updatePickups(dt) {
  if (!state.pickups || !state.player) return;
  const p = state.player;
  // Lista över alla spelare som kan grabba pickups
  const players = [{ ref: p, isLocal: true, pid: null }];
  if (Coop.active && Coop.isHost) {
    for (const [pid, partner] of Coop.players) {
      if (partner.hp > 0) players.push({ ref: partner, isLocal: false, pid });
    }
  }
  for (const pk of state.pickups) {
    pk.life -= dt;
    if (pk.life <= 0) { pk.dead = true; continue; }
    // Hitta närmsta spelare till denna pickup
    let nearest = null, nearestD = Infinity;
    for (const pl of players) {
      const dd = Math.hypot(pl.ref.x - pk.x, pl.ref.y - pk.y);
      if (dd < nearestD) { nearestD = dd; nearest = pl; }
    }
    if (!nearest) continue;
    const dx = nearest.ref.x - pk.x, dy = nearest.ref.y - pk.y;
    const d = nearestD;
    // Magnet mot närmsta spelare. MagnetJamlo-cheat = oändlig räckvidd
    const magnetRange = isCheatActive('magnet') ? 99999 : 110;
    if (d < magnetRange) pk.magnetized = true;
    if (pk.magnetized && d > 0) {
      const speed = Math.min(600, 200 + (1 - d/magnetRange) * 300);
      pk.x += (dx/d) * speed * dt;
      pk.y += (dy/d) * speed * dt;
      // Magnet-trail: liten färgad prick bakom pickup som drar mot spelaren.
      // Throttle via _magnetTrailAccum så vi inte spammar pool vid flera pickups.
      state._magnetTrailAccum = (state._magnetTrailAccum || 0) + dt;
      if (state._magnetTrailAccum > 0.045 && state.particles.length < 220) {
        state._magnetTrailAccum = 0;
        const trailColors = { hp: '#5aff5a', ammo: '#ffae3a', gold: '#ffd54a', temp_dmg: '#ff5a3a' };
        state.particles.push({
          x: pk.x, y: pk.y, vx: 0, vy: 0,
          isTrail: true, color: trailColors[pk.type] || '#fff',
          r: 2.5, life: 0.22, fadeMul: 5,
        });
      }
    }
    if (d < (nearest.ref.r || 14) + 10) {
      pk.dead = true;
      Audio.goldPickup();
      // Pickup-collect burst — färgad shockwave + 4 sparks i samma färg
      const burstColor = pk.type === 'hp' ? '#5aff5a' : pk.type === 'ammo' ? '#ffae3a' : pk.type === 'gold' ? '#ffd54a' : '#ff5a3a';
      spawnShockwave(pk.x, pk.y, 6, 36, burstColor, 0.28, 2);
      spawnSparks(pk.x, pk.y, burstColor, 5, 220);
      // Om partner picked it up, skicka event
      if (!nearest.isLocal && nearest.pid) {
        Coop.sendPickupToPartner(nearest.pid, pk.type);
        continue;
      }
      if (pk.type === 'hp') {
        p.hp = Math.min(p.maxHp, p.hp + 30);
        showFloatingText(pk.x, pk.y, '+30 HP', '#5aff5a');
      } else if (pk.type === 'ammo') {
        const w = getWeapon(p.weaponId);
        if (w.mag) {
          p.ammo = effectiveMag(p.weaponId);
          p.reloading = false;
          showFloatingText(pk.x, pk.y, 'AMMO!', '#ffae3a');
        }
      } else if (pk.type === 'gold') {
        const bonus = 25 + Math.floor(Math.random() * 25);
        save.gold += bonus;
        state.goldThisRun += bonus;
        showFloatingText(pk.x, pk.y, '+' + bonus, '#ffd54a');
      } else if (pk.type === 'temp_dmg') {
        p.tempDmgUntil = performance.now() + 8000;
        showFloatingText(pk.x, pk.y, '×2 DMG 8s', '#ff5a3a');
      }
    }
  }
  state.pickups = state.pickups.filter(p => !p.dead);
}
function showFloatingText(x, y, text, color) {
  state.particles.push({
    x, y, vx: 0, vy: -80, life: 1.0, r: 0,
    color, isDamageNumber: true, text, size: 13,
  });
}
function drawPickups() {
  if (!state.pickups) return;
  const cx = state.camera.x, cy = state.camera.y;
  const t = performance.now();
  for (const pk of state.pickups) {
    const bob = Math.sin(t/200 + pk.x) * 2.5;
    const x = pk.x - cx, y = pk.y - cy + bob;
    const colors = { hp: '#5aff5a', ammo: '#ffae3a', gold: '#ffd54a', temp_dmg: '#ff5a3a' };
    const col = colors[pk.type] || '#fff';
    // Pulserande halo (yttre ring + glow)
    const pulse = 0.55 + Math.sin(t / 280 + pk.x * 0.1) * 0.45;
    ctx.save();
    ctx.shadowColor = col; ctx.shadowBlur = 14 * pulse;
    ctx.fillStyle = col + '44';
    ctx.beginPath(); ctx.arc(x, y, 16 + pulse * 3, 0, Math.PI * 2); ctx.fill();
    ctx.shadowBlur = 0;
    // Inner glow disk
    ctx.fillStyle = col + '22';
    ctx.beginPath(); ctx.arc(x, y, 11, 0, Math.PI * 2); ctx.fill();
    // Rotating sparkle ring (4 prickar)
    const rot = t / 600;
    for (let i = 0; i < 4; i++) {
      const a = rot + i * Math.PI / 2;
      const sx = x + Math.cos(a) * 13, sy = y + Math.sin(a) * 13;
      ctx.fillStyle = '#fff';
      ctx.globalAlpha = 0.5 + Math.sin(t / 200 + i) * 0.4;
      ctx.beginPath(); ctx.arc(sx, sy, 1.5, 0, Math.PI * 2); ctx.fill();
    }
    ctx.globalAlpha = 1;
    ctx.restore();
    // Skugga under (gör att pickup känns flytande)
    ctx.fillStyle = 'rgba(0,0,0,0.35)';
    ctx.beginPath(); ctx.ellipse(x, y + 10 - bob * 0.5, 8, 3, 0, 0, Math.PI * 2); ctx.fill();
    // Ikon
    if (pk.type === 'hp') {
      ctx.fillStyle = '#5aff5a';
      ctx.shadowColor = '#5aff5a'; ctx.shadowBlur = 6;
      ctx.fillRect(x - 5, y - 2, 10, 4);
      ctx.fillRect(x - 2, y - 5, 4, 10);
      ctx.shadowBlur = 0;
    } else if (pk.type === 'ammo') {
      ctx.fillStyle = '#ffae3a';
      ctx.shadowColor = '#ffae3a'; ctx.shadowBlur = 6;
      ctx.fillRect(x - 4, y - 6, 8, 12);
      ctx.shadowBlur = 0;
      ctx.fillStyle = '#3a2a08';
      ctx.fillRect(x - 3, y - 5, 6, 3);
    } else if (pk.type === 'gold') {
      ctx.fillStyle = '#ffd54a';
      ctx.shadowColor = '#ffd54a'; ctx.shadowBlur = 8;
      ctx.beginPath(); ctx.arc(x, y, 6, 0, Math.PI*2); ctx.fill();
      ctx.shadowBlur = 0;
      ctx.fillStyle = '#a07a18';
      ctx.font = 'bold 8px sans-serif'; ctx.textAlign = 'center';
      ctx.fillText('$', x, y + 3);
    } else if (pk.type === 'temp_dmg') {
      ctx.fillStyle = '#ff5a3a';
      ctx.shadowColor = '#ff5a3a'; ctx.shadowBlur = 8;
      ctx.font = 'bold 14px sans-serif'; ctx.textAlign = 'center';
      ctx.fillText('⚡', x, y + 5);
      ctx.shadowBlur = 0;
    }
    // Life-blink när < 5s kvar — nu mer aggressiv så spelaren ser brådskan
    if (pk.life < 5) {
      const blink = 0.5 + Math.sin(t / 80) * 0.5;
      ctx.strokeStyle = col; ctx.lineWidth = 2;
      ctx.globalAlpha = blink;
      ctx.beginPath(); ctx.arc(x, y, 16, 0, Math.PI*2); ctx.stroke();
      ctx.globalAlpha = 1;
    }
  }
}

const stageState = {
  buildings: [],   // kollisions-objekt: { x, y, w, h, kind, ...detaljer }
  decorations: [], // icke-kollisions visuella element: { x, y, kind, ...details }
  hazards: [],     // ex. explosiva fat (kan triggas)
};
const SAVE_KEY = 'penetrator_save_v1';
// Migrera gammal save-nyckel om den finns
(function migrateOldSave() {
  try {
    const old = localStorage.getItem('jimmy_mourad_save_v1');
    if (old && !localStorage.getItem(SAVE_KEY)) {
      localStorage.setItem(SAVE_KEY, old);
    }
  } catch (e) {}
})();

// ============================================================
// VAPEN
// Varje vapen: id, name, type ('melee'|'gun'), price, dmg, rate (ms),
// range/speed, mag, reload, spread, pellets, explosive, color
// ============================================================
// COOP_WEAPONS — i alla coop-modes (med eller mot varandra) har spelare ETT
// gemensamt arsenal: dessa 6 vapen + 'fists'. Ingen shop/perks/upgrades-system
// aktivt i coop. Switcha via vapen-menyn som vanligt.
const COOP_WEAPONS = ['pistol', 'shuriken', 'burstpistol', 'shotgun', 'sniper', 'rifle'];

// Story-coop: progressiv vapen-unlock per wave så det inte blir för lätt direkt.
// PvP-modes (TDM/CTF) får alla 6 från start (rättvis match), endless/bossrush/
// survive coop likaså — det är bara story coop som progressar.
// Stage 1 har två vapen så Shadow Stalker (cloak-miniboss, hp×14) faktiskt går
// att döda inom rimlig tid med pistol-only.
const COOP_STORY_WEAPON_UNLOCKS = {
  1: ['pistol', 'shuriken'],  // Stage 1: pistol + kaststjärnor (för Shadow Stalker)
  2: 'shotgun',               // Stage 2: + hagelgevär (close-range power)
  3: 'burstpistol',           // Stage 3: + burst (mid-range)
  4: 'rifle',                 // Stage 4: + automatkarbin (Ossarius behöver DPS)
  5: 'sniper',                // Stage 5: + prickskytte (Valv XIII öppna ytor)
  // Stage 6+: alla 6 låsta, ingen ytterligare unlock
};
function isCoopStoryMode() {
  return Coop.active && !Coop.config.tdm && !Coop.config.ctf && !Coop.config.siege && !Coop.config.gungame && !Coop.config.koth && (Coop.config.mode === 'story' || !Coop.config.mode);
}
function coopStoryUnlockedThroughWave(wave) {
  const unlocked = ['fists'];
  for (let w = 1; w <= wave; w++) {
    const v = COOP_STORY_WEAPON_UNLOCKS[w];
    if (!v) continue;
    if (Array.isArray(v)) unlocked.push(...v);
    else unlocked.push(v);
  }
  return unlocked;
}

