const MAX_COMPANION_LEVEL = 100;
function companionUpgradePrice(level) {
  // 100 + level * 30 — ~165k för att maxa allt
  return Math.round(100 + level * 30);
}
function companionStats(comp, level) {
  const lvlMul = 1 + level * 0.012; // +1.2% per level → +120% vid max
  const cdMul = Math.max(0.4, 1 - level * 0.005); // -50% cooldown vid max
  return {
    hp: Math.round(comp.baseHp * lvlMul),
    dmg: Math.round(comp.baseDmg * lvlMul),
    speed: Math.round(comp.baseSpeed * (1 + level * 0.005)),
    range: Math.round(comp.baseRange * (1 + level * 0.003)),
    cooldown: comp.cooldown * cdMul,
  };
}
// Återväckningskostnad: skalar med wave så stage 1 är överkomligt + stage 9 stings.
// Formula: basePrice × 0.5 × (0.3 + wave×0.08) → stage 1 = 19% av basePrice, stage 9 = 51%.
function companionRevivePrice(comp) {
  const wave = (state && state.wave) ? state.wave : 1;
  const stageMul = 0.3 + Math.min(wave, 9) * 0.08; // 0.38 - 1.02
  return Math.max(50, Math.round((comp.basePrice * 0.5 * stageMul) / 10) * 10);
}
// Är aktiv companion död (in-game ELLER persisted från tidigare run)?
// Används för att visa ÅTERVÄCK-UI även i menu pre-game (state.companion null).
function isActiveCompanionDead() {
  if (!save.companions || !save.companions.active) return false;
  if (state.companion && state.companion.id === save.companions.active && !state.companion.alive) return true;
  if (save.companions.dead && save.companions.dead[save.companions.active]) return true;
  return false;
}
// Specifik companion-id död?
function isCompanionDead(id) {
  if (state.companion && state.companion.id === id && !state.companion.alive) return true;
  return !!(save.companions && save.companions.dead && save.companions.dead[id]);
}
function ensureCompanions() {
  if (!save.companions) save.companions = {};
  if (!save.companions.owned) save.companions.owned = [];
  if (!save.companions.level) save.companions.level = {};
  for (const c of COMPANIONS) {
    if (typeof save.companions.level[c.id] !== 'number') save.companions.level[c.id] = 0;
  }
  if (save.companions.active === undefined) save.companions.active = null;
}
function getCompanionById(id) { return COMPANIONS.find(c => c.id === id); }

