const Achievements = {
  unlock(id) {
    if (!save.achievements) save.achievements = [];
    if (save.achievements.includes(id)) return;
    save.achievements.push(id);
    persist();
    const ach = ACHIEVEMENTS.find(a => a.id === id);
    if (ach) showAchievementPopup(ach);
  },
  has(id) { return save.achievements && save.achievements.includes(id); },
  check() {
    const stats = save.stats || {};
    if ((stats.totalKills || 0) >= 1) this.unlock('firstblood');
    if ((stats.totalKills || 0) >= 10) this.unlock('kill10');
    if ((stats.totalKills || 0) >= 100) this.unlock('kill100');
    if ((stats.totalKills || 0) >= 1000) this.unlock('kill1000');
    if ((stats.bossKills || 0) >= 1) this.unlock('firstboss');
    if ((stats.totalGold || 0) >= 5000) this.unlock('rich');
    if (save.owned && save.owned.length >= WEAPONS.length) this.unlock('allweapons');
    if (save.upgrades && Object.values(save.upgrades).some(v => v >= MAX_UPGRADE_LEVEL)) this.unlock('maxedup');
    if (save.perks && save.perks.length >= PERKS.length) this.unlock('allperks');
    if ((stats.totalCrits || 0) >= 100) this.unlock('crit100');
    if ((stats.explKills || 0) >= 50) this.unlock('explosion50');
  },
};
function ensureStats() {
  if (!save.stats) save.stats = {};
  for (const k of ['totalKills','bossKills','totalGold','totalCrits','explKills','runs','playtime','wins']) {
    if (typeof save.stats[k] !== 'number') save.stats[k] = 0;
  }
}

// Skapa achievement-popup dynamiskt
let achPopupEl = null;
let achPopupTimer = null;
function createAchPopup() {
  if (achPopupEl) return achPopupEl;
  const el = document.createElement('div');
  el.id = 'ach-popup-dyn';
  // Top-left under HP-bar (var top-right förut, täckte minimap).
  // Slide-in från VÄNSTER istället för höger.
  // Push ach-popup nedanför hud-toast-stack-zonen (toast-stack tar top:58-110px).
  el.style.cssText = 'position:fixed;top:max(120px, calc(env(safe-area-inset-top, 0px) + 112px));left:-380px;max-width:300px;background:#1a0a08;color:#fff;border:2px solid #ffd54a;border-left:6px solid #ffd54a;border-radius:8px;padding:10px 14px;z-index:10000;transition:left 0.4s cubic-bezier(0.34,1.56,0.64,1);display:flex;align-items:center;gap:12px;box-shadow:0 8px 24px rgba(0,0,0,0.7),0 0 12px rgba(255,213,74,0.4);cursor:pointer;font-family:-apple-system,sans-serif;';
  el.innerHTML = `
    <div class="ach-icon" style="font-size:30px;flex:0 0 auto;line-height:1;">🏆</div>
    <div style="flex:1;min-width:0;text-align:left;">
      <div class="ach-title" style="font-weight:800;font-size:10px;letter-spacing:2px;color:#ffd54a;text-transform:uppercase;margin-bottom:2px;">PRESTATION</div>
      <div class="ach-name" style="font-size:14px;font-weight:700;color:#fff;line-height:1.2;word-wrap:break-word;">—</div>
    </div>
  `;
  el.addEventListener('click', () => {
    el.style.left = '-380px';
    if (achPopupTimer) clearTimeout(achPopupTimer);
  });
  document.body.appendChild(el);
  achPopupEl = el;
  return el;
}
// Achievements som triggar full-screen cinematic istället för slide-in toast
const ACH_CINEMATIC_IDS = new Set(['allbosses', 'firstboss', 'kill1000', 'streak20', 'rich', 'allweapons', 'allperks']);
function showAchievementPopup(ach) {
  // Stora milestones → cinematic instead of toast
  if (ach && ach.id && ACH_CINEMATIC_IDS.has(ach.id) && !state._achCinematicRunning) {
    showAchievementCinematic(ach);
    return;
  }
  const el = createAchPopup();
  if (!el) return;
  const iconEl = el.querySelector('.ach-icon');
  const nameEl = el.querySelector('.ach-name');
  if (iconEl) iconEl.textContent = ach.icon || '🏆';
  if (nameEl) nameEl.textContent = ach.name || '';
  // Slide in från vänster (top-left under HP-bar — täcker inte minimap som ligger top-right)
  el.style.left = 'max(8px, env(safe-area-inset-left, 8px))';
  try { Audio.achievement(); } catch(e) {}
  if (achPopupTimer) clearTimeout(achPopupTimer);
  achPopupTimer = setTimeout(() => {
    el.style.left = '-380px';
  }, 2200);
}

// Full-screen cinematic för major achievements — backdrop blur, scale-in icon,
// shockwave + sparks på spelaren, fader ut efter 2.5s.
let _achCinematicEl = null;
function showAchievementCinematic(ach) {
  state._achCinematicRunning = true;
  if (!_achCinematicEl) {
    _achCinematicEl = document.createElement('div');
    _achCinematicEl.id = 'ach-cinematic';
    document.body.appendChild(_achCinematicEl);
  }
  _achCinematicEl.innerHTML = `
    <div class="ach-cin-bg"></div>
    <div class="ach-cin-panel">
      <div class="ach-cin-banner">ACHIEVEMENT UNLOCKED</div>
      <div class="ach-cin-icon">${ach.icon || '🏆'}</div>
      <div class="ach-cin-name">${ach.name || ''}</div>
      <div class="ach-cin-desc">${ach.desc || ''}</div>
    </div>
  `;
  _achCinematicEl.classList.add('show');
  try { Audio.achievement(); } catch (e) {}
  // VFX på spelaren
  if (state.player) {
    const p = state.player;
    spawnShockwave(p.x, p.y, 16, 140, '#ffd54a', 0.7, 5);
    setTimeout(() => spawnShockwave(p.x, p.y, 16, 220, '#fff', 0.6, 4), 150);
    spawnSparks(p.x, p.y, '#ffd54a', 24, 380);
    triggerShake(8, 0.4);
  }
  setTimeout(() => {
    if (_achCinematicEl) _achCinematicEl.classList.remove('show');
    state._achCinematicRunning = false;
  }, 2500);
}

