// GAME MODES + DIFFICULTY
// ============================================================
const GAME_MODES = ['story', 'endless', 'bossrush', 'daily', 'sandbox', 'speedrun', 'survive', 'truck'];
const DIFFICULTIES = ['casual', 'veteran', 'hardcore', 'insane'];
const MODE_LABELS = { story: 'STORY', endless: 'ENDLESS', bossrush: 'BOSS RUSH', daily: 'DAILY', sandbox: 'SANDBOX', speedrun: 'SPEEDRUN', survive: 'SURVIVE 5M', truck: '🚚 KONVOJ', newgameplus: 'NG+' };
const DIFF_LABELS = { casual: 'CASUAL', veteran: 'VETERAN', hardcore: 'HARDCORE', insane: '💀 INSANE' };
const DIFF_MULTIPLIERS = {
  casual:   { enemyHp: 0.7, enemyDmg: 0.7, gold: 1.2, shopPrice: 0.85 },
  veteran:  { enemyHp: 1.0, enemyDmg: 1.0, gold: 1.0, shopPrice: 1.0 },
  hardcore: { enemyHp: 1.3, enemyDmg: 1.3, gold: 1.0, shopPrice: 1.15 },
  insane:   { enemyHp: 2.5, enemyDmg: 2.0, gold: 1.5, shopPrice: 1.3 },
};
function getMode() { return save.mode || 'story'; }
function getDifficulty() { return save.difficulty || 'veteran'; }
function getDiffMul() { return DIFF_MULTIPLIERS[getDifficulty()] || DIFF_MULTIPLIERS.veteran; }
function getNGPLevel() { return save.ngpLevel || 0; }
function isNewGamePlus() { return getNGPLevel() > 0; }
function getNGPMul() {
  const lvl = getNGPLevel();
  return 1 + lvl * 0.5; // NG+: 1.5×, NG++: 2×, NG+++: 2.5×
}
function persist() {
  // Sanitera save.gold mot NaN/Infinity/negativt — annars kan korrupta värden persistera
  sanitizeGold();
  // Coop-run pågår: spara INTE ändringar (fresh-start varje gång)
  if (typeof state !== 'undefined' && state && state._coopSnapshot) return;
  localStorage.setItem(SAVE_KEY, JSON.stringify(save));
}

// Defensiv guard mot NaN/Infinity som corruption-källor (visar 9999... i shop)
function sanitizeGold() {
  if (!Number.isFinite(save.gold)) save.gold = 0;
  if (save.gold < 0) save.gold = 0;
  if (save.gold > 1e9) save.gold = 1e9;  // hard cap så inga 9999...-värden
  save.gold = Math.floor(save.gold);     // alltid integer
  if (typeof state !== 'undefined' && state) {
    if (!Number.isFinite(state.goldThisRun)) state.goldThisRun = 0;
    if (state.goldThisRun < 0) state.goldThisRun = 0;
  }
}
// Säker gold-addition: ignorerar NaN/Infinity-input. Använd istället för direkt save.gold += x
function addGold(amount) {
  const n = Number(amount);
  if (!Number.isFinite(n)) return;
  if (!Number.isFinite(save.gold)) save.gold = 0;
  save.gold = Math.floor(Math.max(0, Math.min(1e9, save.gold + n)));
  if (typeof state !== 'undefined' && state) {
    if (!Number.isFinite(state.goldThisRun)) state.goldThisRun = 0;
    if (n > 0) state.goldThisRun = Math.floor(state.goldThisRun + n);
  }
}

