// CTF turret-ENTER/EXIT-knapp. Visas dynamiskt när spelaren är nära ett ledigt
// torn av sitt eget lag, eller när hen sitter i ett torn.
const _btnTurretAction = document.getElementById('btn-turret-action');
let _turretNearbyId = null; // id på närmaste ledigt torn (för enter), eller null
function updateTurretButton() {
  if (!_btnTurretAction) return;
  if (!state.player) {
    if (!_btnTurretAction.classList.contains('hidden')) _btnTurretAction.classList.add('hidden');
    _turretNearbyId = null;
    return;
  }
  // CTF eller SIEGE? Pick right state/team-source.
  let turrets, team, mountedId, radius;
  if (state.ctfActive) {
    turrets = state.ctfTurrets;
    team = Coop.ctfTeams && Coop.ctfTeams[Coop.myId];
    mountedId = state.player._mountedCtfTurretId;
    radius = state.ctfTurretEnterRadius || 50;
  } else if (state.siegeActive) {
    turrets = state.siegeTurrets;
    team = Coop.siegeTeams && Coop.siegeTeams[Coop.myId];
    mountedId = state.player._mountedSiegeTurretId;
    radius = state.siegeTurretEnterRadius || 50;
  } else {
    if (!_btnTurretAction.classList.contains('hidden')) _btnTurretAction.classList.add('hidden');
    _turretNearbyId = null;
    return;
  }
  // Sitter spelaren i ett torn? Visa EXIT
  if (mountedId) {
    _btnTurretAction.textContent = '🚪 EXIT TORN';
    _btnTurretAction.classList.remove('hidden');
    _turretNearbyId = null;
    return;
  }
  if (!team || !turrets) {
    if (!_btnTurretAction.classList.contains('hidden')) _btnTurretAction.classList.add('hidden');
    _turretNearbyId = null;
    return;
  }
  const r = radius + 15;
  let found = null, foundType = null;
  for (const id of Object.keys(turrets)) {
    const t = turrets[id];
    if (t.destroyed || t.occupantId || t.team !== team) continue;
    const dx = state.player.x - t.x, dy = state.player.y - t.y;
    if (dx * dx + dy * dy < r * r) {
      found = id;
      foundType = t.turretType || 'mg';
      break;
    }
  }
  if (found) {
    if (_turretNearbyId !== found) console.log('[TURRET-CLIENT] in range of', found);
    _turretNearbyId = found;
    const label = foundType === 'rocket' ? '🚀 ENTER ROCKET' : '🔫 ENTER MG';
    _btnTurretAction.textContent = label;
    _btnTurretAction.classList.remove('hidden');
  } else {
    _turretNearbyId = null;
    if (!_btnTurretAction.classList.contains('hidden')) _btnTurretAction.classList.add('hidden');
  }
}
function triggerTurretAction(source) {
  if (!state.player) { console.log('[TURRET-CLIENT] no player'); return; }
  if (!Coop.ws || Coop.ws.readyState !== 1) { console.log('[TURRET-CLIENT] ws not open'); return; }
  // CTF turret
  if (state.player._mountedCtfTurretId) {
    const tid = state.player._mountedCtfTurretId;
    try { Coop.ws.send(JSON.stringify({ type: 'ctf_turret_exit', turretId: tid })); } catch (_) {}
    return;
  }
  // SIEGE turret
  if (state.player._mountedSiegeTurretId) {
    const tid = state.player._mountedSiegeTurretId;
    try { Coop.ws.send(JSON.stringify({ type: 'siege_turret_exit', turretId: tid })); } catch (_) {}
    return;
  }
  // Inte mounted — försök ENTER
  if (_turretNearbyId) {
    const enterType = state.siegeActive ? 'siege_turret_enter' : 'ctf_turret_enter';
    try { Coop.ws.send(JSON.stringify({ type: enterType, turretId: _turretNearbyId })); } catch (_) {}
  }
}
if (_btnTurretAction) {
  // Dedupe pointerdown + touchstart (båda fyrar på mobil)
  let _lastTurretClick = 0;
  const onTurretClick = (e) => {
    e.preventDefault();
    const now = performance.now();
    if (now - _lastTurretClick < 200) return; // ignore double-fire
    _lastTurretClick = now;
    triggerTurretAction('btn');
  };
  _btnTurretAction.addEventListener('pointerdown', onTurretClick);
  _btnTurretAction.addEventListener('touchstart', onTurretClick, { passive: false });
}
// Keyboard fallback: E-key för desktop-spelare (CTF + SIEGE)
window.addEventListener('keydown', (e) => {
  if (e.key === 'e' || e.key === 'E') {
    if (state.mode === 'playing' && (state.ctfActive || state.siegeActive)) triggerTurretAction('keyE');
  }
});

// PvP-shield-knapp: 3s total immunitet, 45s cooldown. Bara aktiv i TDM/CTF.
// Server-auth: skickar pvp_ability_shield till server som sätter invulnUntil.
const PVP_SHIELD_DURATION_MS = 3000;
const PVP_SHIELD_COOLDOWN_MS = 45000;
const PVP_SHIELD_COOLDOWN_HUNTER_MS = 20000; // juggernaut-hunters har snabbare CD
const _btnPvpShield = document.getElementById('btn-pvp-shield');
function tryPvpShield() {
  const p = state.player;
  if (!p) return;
  if (!state.tdmActive && !state.ctfActive && !state.siegeActive && !state.gungameActive && !state.kothActive && !state.juggernautActive) return;
  const now = performance.now();
  if (p.pvpShieldUntil && now < p.pvpShieldUntil) return; // redan aktiv
  // Bugfix: ingen cooldown vid match-start. pvpShieldCdAt = null = aldrig använd.
  // Tidigare gjorde (null || 0) + 45000 = 45000 vilket var > performance.now()
  // när sidan precis laddats → spelaren kunde inte använda shielden första
  // ~45s av matchen.
  // Juggernaut: hunter får 20s CD, JUG behåller 45s (bot/server enforcerar också)
  const cdLength = (state.juggernautActive && !p.isJug) ? PVP_SHIELD_COOLDOWN_HUNTER_MS : PVP_SHIELD_COOLDOWN_MS;
  const cdEnd = p.pvpShieldCdAt == null ? 0 : (p.pvpShieldCdAt + cdLength);
  if (cdEnd > now) {
    if (typeof showToast === 'function') {
      const remaining = Math.ceil((cdEnd - now) / 1000);
      showToast('🛡 Cooldown ' + remaining + 's');
    }
    return;
  }
  // Optimistic-aktivera lokalt + skicka till server
  p.pvpShieldUntil = now + PVP_SHIELD_DURATION_MS;
  p.pvpShieldCdAt = now;
  if (typeof Coop !== 'undefined' && Coop.ws && Coop.ws.readyState === 1) {
    try { Coop.ws.send(JSON.stringify({ type: 'pvp_ability_shield' })); } catch (_) {}
  }
  if (typeof Audio !== 'undefined' && Audio._tone) Audio._tone(600, 0.3, 'sine', 0.3, 0.005, 0.25, 1000);
  if (typeof showToast === 'function') showToast('🛡 SHIELD AKTIV (3s)');
  if (typeof triggerVibrate === 'function') triggerVibrate(40);
}
if (_btnPvpShield) {
  const onShieldDown = (e) => {
    e.preventDefault();
    if (state.mode === 'playing') tryPvpShield();
  };
  _btnPvpShield.addEventListener('pointerdown', onShieldDown);
  _btnPvpShield.addEventListener('touchstart', onShieldDown, { passive: false });
}

// EMOTE-knapp + picker (lazy-build första gången knappen trycks så EMOTES finns då)
const emotePickerEl = document.getElementById('emote-picker');
let _emotePickerBuilt = false;
function buildEmotePicker() {
  if (!emotePickerEl || _emotePickerBuilt) return;
  if (typeof EMOTES === 'undefined') return;
  _emotePickerBuilt = true;
  emotePickerEl.innerHTML = '';
  for (const em of EMOTES) {
    const btn = document.createElement('button');
    btn.className = 'emote-picker-btn';
    btn.title = em.text;
    btn.style.touchAction = 'manipulation';
    btn.innerHTML = '<span style="font-size:17px;line-height:1;">' + em.emoji + '</span>';
    // ENDAST pointerdown — annars fyrar både pointerdown + touchstart på touch.
    btn.addEventListener('pointerdown', (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      if (state.player) applyEmote(state.player, em.id);
      Coop.broadcastEmote(em.id);
      emotePickerEl.classList.add('hidden');
      Audio.uiClick();
    }, { passive: false });
    emotePickerEl.appendChild(btn);
  }
}
const _btnEmote = document.getElementById('btn-emote');
if (_btnEmote) {
  _btnEmote.style.touchAction = 'manipulation';
  // ENDAST pointerdown (inte touchstart också) — annars fyrar båda på touch
  // och toggle visar+gömmer picker direkt = "tryck men inget händer".
  _btnEmote.addEventListener('pointerdown', (e) => {
    e.preventDefault();
    e.stopPropagation();
    buildEmotePicker();
    emotePickerEl.classList.toggle('hidden');
    Audio.uiClick();
  }, { passive: false });
  // Stäng picker om man tappar någon annanstans
  document.addEventListener('pointerdown', (e) => {
    if (emotePickerEl && !emotePickerEl.classList.contains('hidden') &&
        !emotePickerEl.contains(e.target) &&
        e.target !== _btnEmote && !_btnEmote.contains(e.target)) {
      emotePickerEl.classList.add('hidden');
    }
  });
}

const weaponMenuScreen = document.getElementById('weapon-menu-screen');
const weaponMenuGrid = document.getElementById('weapon-menu-grid');
let prevModeBeforeWeaponMenu = 'playing';

function openWeaponMenu() {
  if (state.mode !== 'playing') return;
  // GUNGAME: vapen styrs av server via tier-promotion — spelaren får inte
  // välja vapen själv. Visa en kort toast istället.
  if (state.gungameActive) {
    if (typeof showToast === 'function') showToast('🔫 GUNGAME — vapnet växlar via kills');
    return;
  }
  // JUGGERNAUT: hunters har bara pistol, JUG väljer mellan 3 vapen
  if (state.juggernautActive) {
    if (!state.player || !state.player.isJug) {
      if (typeof showToast === 'function') showToast('🔫 HUNTER — pistol bara, döda JUG för att ta över');
      return;
    }
    // JUG-spelare: använd dedikerad picker med bara 3 vapen
    showJuggernautWeaponPicker();
    return;
  }
  prevModeBeforeWeaponMenu = state.mode;
  state.mode = 'weaponmenu';
  weaponMenuScreen.classList.remove('hidden');
  // I coop: dölj shop-knappen så användaren inte ens ser den (ingen shop tillåten)
  const wsBtn = document.getElementById('btn-weapon-shop');
  if (wsBtn) wsBtn.classList.toggle('hidden', !!Coop.active);
  // släpp pågående input
  input.firing = false;
  if (typeof joyEnd === 'function') joyEnd({ changedTouches: null });
  renderWeaponMenu();
}

function closeWeaponMenu() {
  weaponMenuScreen.classList.add('hidden');
  state.mode = prevModeBeforeWeaponMenu === 'weaponmenu' ? 'playing' : prevModeBeforeWeaponMenu;
}

document.getElementById('btn-weapon-close').addEventListener('click', closeWeaponMenu);

