// ============ PHOTO BOOTH ============
function takeWardrobePhoto() {
  if (!wardrobePreview) return;
  // Skapa hög-upplöst version av karaktären på en cleaner bakgrund (300×400 base)
  const photoCanvas = document.createElement('canvas');
  photoCanvas.width = 600; photoCanvas.height = 760;
  const pc = photoCanvas.getContext('2d');
  // Cinematic-bakgrund med radial spotlight
  const bgGrad = pc.createRadialGradient(300, 380, 50, 300, 380, 500);
  bgGrad.addColorStop(0, '#3a1a5a');
  bgGrad.addColorStop(0.5, '#1a0a2a');
  bgGrad.addColorStop(1, '#000');
  pc.fillStyle = bgGrad;
  pc.fillRect(0, 0, photoCanvas.width, photoCanvas.height);
  // Scan-lines för cool retro look
  pc.fillStyle = 'rgba(255,255,255,0.03)';
  for (let yy = 0; yy < photoCanvas.height; yy += 3) {
    pc.fillRect(0, yy, photoCanvas.width, 1);
  }
  // Spelnamn-watermark uppe
  pc.fillStyle = 'rgba(255,213,74,0.7)';
  pc.font = 'bold 18px sans-serif';
  pc.textAlign = 'center';
  pc.fillText('THE PENETRATOR', 300, 36);
  pc.fillStyle = 'rgba(170,58,255,0.6)';
  pc.font = '12px sans-serif';
  pc.fillText('— Min outfit —', 300, 56);
  // Skala upp wardrobePreview till photo-canvas (2x)
  pc.imageSmoothingEnabled = false;
  pc.drawImage(wardrobePreview, 0, 80, 600, 760);
  // Underskrift
  pc.fillStyle = 'rgba(255,255,255,0.5)';
  pc.font = '11px sans-serif';
  pc.fillText(new Date().toLocaleDateString('sv-SE'), 300, photoCanvas.height - 12);
  // Trigger download — iOS Safari ignorerar `download`-attribute så vi öppnar
  // i ny tab så user kan long-press → "Spara i bilder".
  try {
    const url = photoCanvas.toDataURL('image/png');
    const isIOS = /iP(hone|ad|od)/.test(navigator.userAgent);
    if (isIOS) {
      window.open(url, '_blank');
      Audio.purchase();
      showWardrobeEquipFeedback(null, '📸 LÅNGTRYCK FÖR ATT SPARA');
    } else {
      const a = document.createElement('a');
      a.href = url;
      a.download = 'penetrator-outfit-' + Date.now() + '.png';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      Audio.purchase();
      showWardrobeEquipFeedback(null, '📸 SPARAD!');
    }
  } catch (e) {
    if (window._debug) console.warn('[PHOTO] Export failed:', e.message);
    showWardrobeEquipFeedback(null, '⚠ EXPORT FAILED');
  }
}

// ============ THEME PREVIEW ============
// Vissa outfits sätter en CSS-variabel som tintar HUD-accent. Subtilt.
function applyWardrobeTheme() {
  if (!save.wardrobe) return;
  const w = save.wardrobe;
  // Theme baserat på bandana-färg (mest framträdande accent)
  const bandanaOpt = w.bandana ? WARDROBE.bandana.find(o => o.id === w.bandana) : null;
  let themeColor = null;
  if (bandanaOpt && bandanaOpt.color && bandanaOpt.tier && bandanaOpt.tier !== 'common') {
    themeColor = bandanaOpt.color;
  }
  if (themeColor) {
    document.documentElement.style.setProperty('--player-theme', themeColor);
  } else {
    document.documentElement.style.removeProperty('--player-theme');
  }
}

// COMPANIONS-skärm
const companionsScreen = document.getElementById('companions-screen');
const companionsGridEl = document.getElementById('companions-grid');
function renderCompanions() {
  ensureCompanions();
  if (!companionsGridEl) return;
  companionsGridEl.innerHTML = '';
  for (const c of COMPANIONS) {
    const owned = save.companions.owned.includes(c.id);
    const lvl = save.companions.level[c.id] || 0;
    const isActive = save.companions.active === c.id;
    const stats = companionStats(c, lvl);
    const upgPrice = lvl < MAX_COMPANION_LEVEL ? companionUpgradePrice(lvl) : null;
    const isDead = isActive && isCompanionDead(c.id);
    const revivePrice = companionRevivePrice(c);
    const card = document.createElement('div');
    card.style.cssText = 'background:rgba(20,20,30,0.7);border:2px solid ' + (isDead ? '#ff5a5a' : (isActive ? '#aa3aff' : 'rgba(170,58,255,0.2)')) + ';border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:8px;';
    card.innerHTML = `
      <div style="display:flex;align-items:center;gap:12px;">
        <div style="font-size:36px;${isDead ? 'filter:grayscale(1) brightness(0.5);' : ''}">${c.icon}</div>
        <div style="flex:1;">
          <div style="font-weight:bold;color:${isDead ? '#ff5a5a' : '#ffd54a'};font-size:15px;">${c.name}${isDead ? ' 💀' : ''}</div>
          <div style="font-size:11px;color:#bbb;">${c.desc}</div>
          <div style="font-size:11px;color:#aa3aff;margin-top:3px;">⚡ ${c.special}</div>
        </div>
      </div>
      ${owned ? `
        <div style="display:flex;justify-content:space-between;font-size:11px;color:#ddd;">
          <span>LVL ${lvl}/${MAX_COMPANION_LEVEL}</span>
          <span>HP ${stats.hp} · DMG ${stats.dmg}</span>
        </div>
        <div style="background:rgba(0,0,0,0.4);border-radius:4px;height:6px;overflow:hidden;">
          <div style="background:linear-gradient(90deg,#aa3aff,#ff5aca);width:${(lvl/MAX_COMPANION_LEVEL)*100}%;height:100%;"></div>
        </div>
        <div style="display:flex;gap:6px;">
          ${isDead
            ? `<button class="small-btn" data-act="revive" style="flex:1;background:${save.gold >= revivePrice ? 'linear-gradient(135deg,#ff5a5a,#aa3030)' : '#444'};">⚡ ÅTERVÄCK 💰${revivePrice}</button>`
            : `<button class="small-btn" data-act="toggle" style="flex:1;background:${isActive ? '#aa3aff' : '#444'};">${isActive ? '✓ AKTIV' : 'AKTIVERA'}</button>`
          }
          ${upgPrice ? `<button class="small-btn" data-act="upgrade" style="flex:1;background:${save.gold >= upgPrice ? '#3a8a3a' : '#444'};">UPGRADE 💰${upgPrice}</button>` : `<div style="flex:1;text-align:center;color:#ffd54a;font-weight:bold;">⭐ MAXAD</div>`}
        </div>
      ` : `
        <button class="big-btn" data-act="buy" style="width:100%;background:${save.gold >= c.basePrice ? '#3a8a3a' : '#444'};">KÖP — 💰 ${c.basePrice}</button>
      `}
    `;
    // Event handlers
    const buyBtn = card.querySelector('[data-act="buy"]');
    if (buyBtn) buyBtn.addEventListener('click', () => {
      if (save.gold < c.basePrice) { showToast('Inte nog gold!'); return; }
      save.gold -= c.basePrice;
      save.companions.owned.push(c.id);
      if (!save.companions.active) save.companions.active = c.id;
      persist(); Audio.purchase(); renderCompanions();
      // Spawna companion direkt så användaren ser den även mid-run
      // Spawna companion direkt vid köp/toggle. spawnCompanion hanterar null-fallet
      // så det är säkert att kalla även när shoppen är öppen (state.mode='shop').
      if (typeof spawnCompanion === 'function') spawnCompanion();
    });
    const upgBtn = card.querySelector('[data-act="upgrade"]');
    if (upgBtn) upgBtn.addEventListener('click', () => {
      if (save.gold < upgPrice) { showToast('Inte nog gold!'); return; }
      save.gold -= upgPrice;
      save.companions.level[c.id] = lvl + 1;
      persist(); Audio.purchase(); renderCompanions();
    });
    const togBtn = card.querySelector('[data-act="toggle"]');
    if (togBtn) togBtn.addEventListener('click', () => {
      save.companions.active = isActive ? null : c.id;
      persist(); Audio.uiClick(); renderCompanions();
      // Spawna companion direkt vid köp/toggle. spawnCompanion hanterar null-fallet
      // så det är säkert att kalla även när shoppen är öppen (state.mode='shop').
      if (typeof spawnCompanion === 'function') spawnCompanion();
    });
    // ÅTERVÄCK från menu-companions också
    const revBtn = card.querySelector('[data-act="revive"]');
    if (revBtn) revBtn.addEventListener('click', () => {
      const cost = companionRevivePrice(c);
      if (save.gold < cost) { showToast('Inte nog gold!'); return; }
      save.gold -= cost;
      persist(); Audio.purchase(); renderCompanions();
      if (typeof spawnCompanion === 'function') spawnCompanion();
    });
    companionsGridEl.appendChild(card);
  }
}
