const menuScreen = document.getElementById('menu-screen');
const gameoverScreen = document.getElementById('gameover-screen');
const endTitle = document.getElementById('end-title');
const endStats = document.getElementById('end-stats');

document.getElementById('btn-start').addEventListener('click', startGame);
function resetSavePrompt() {
  const choice = prompt('SKRIV: "RESET" för att radera all progression\n         "EXPORT" för att kopiera spar-data\n         "IMPORT" för att klistra in spar-data');
  if (!choice) return;
  if (choice.toUpperCase() === 'RESET') {
    save = defaultSave();
    rebuildPerkSet();
    persist();
    alert('Progression återställd.');
  } else if (choice.toUpperCase() === 'EXPORT') {
    const code = btoa(JSON.stringify(save));
    if (navigator.clipboard) navigator.clipboard.writeText(code);
    prompt('Spara denna kod (kopiera):', code);
  } else if (choice.toUpperCase() === 'IMPORT') {
    const code = prompt('Klistra in spar-kod:');
    if (!code) return;
    try {
      const parsed = JSON.parse(atob(code.trim()));
      if (parsed && typeof parsed === 'object') {
        save = parsed;
        ensureUpgrades(); ensurePerks(); ensureStats();
        rebuildPerkSet();
        persist();
        alert('Spar-data importerad!');
      }
    } catch (e) { alert('Ogiltig kod.'); }
  }
}
const _setReset = document.getElementById('set-reset');
if (_setReset) _setReset.addEventListener('click', resetSavePrompt);
document.getElementById('btn-retry').addEventListener('click', () => {
  gameoverScreen.classList.add('hidden');
  // Coop: om vi var i coop-rum, måste server få sim_start på nytt — annars
  // tror server att matchen är slut och klient blir stuck. Skicka om host.
  if (Coop.active && Coop.isHost && Coop.config && Coop.config.serverSim &&
      Coop.ws && Coop.ws.readyState === 1) {
    // Reset serverSim-flag innan retry så att actuallyStartGame triggar ny sim_start
    Coop.serverSimActive = false;
    state.serverSimActive = false;
    Coop._simStartedConfirmed = false;
  }
  startGame();
  // Efter actuallyStartGame: om host i coop-serverSim, skicka ny sim_start
  if (Coop.active && Coop.isHost && Coop.config && Coop.config.serverSim &&
      Coop.ws && Coop.ws.readyState === 1) {
    const payload = {
      type: 'sim_start',
      wave: state.wave || 1,
      difficulty: Coop.config.difficulty || 'veteran',
      ngpLevel: save.ngpLevel || 0,
      mode: Coop.config.mode || 'story',
    };
    if (Coop.config.tdm) {
      payload.tdm = true;
      payload.tdmTargetKills = Coop.config.tdmTargetKills || 10;
    }
    if (Coop.config.ctf) {
      payload.ctf = true;
      payload.ctfTargetCaptures = Coop.config.ctfTargetCaptures || 3;
    }
    if (Coop.config.siege) {
      payload.siege = true;
      payload.siegeTargetPoints = Coop.config.siegeTargetPoints || 500;
    }
    if (Coop.config.gungame) {
      payload.gungame = true;
    }
    if (Coop.config.koth) {
      payload.koth = true;
      payload.kothTargetPoints = Coop.config.kothTargetPoints || 100;
    }
    if (Coop.config.juggernaut) {
      payload.juggernaut = true;
      payload.juggernautMatchDurationSec = Coop.config.juggernautMatchDurationSec || 360;
    }
    if (Coop.config.addBot) {
      payload.addBot = true;
      payload.botTeam = Coop.config.botTeam || 'red';
      payload.botCount = Coop.config.botCount || 1;
      payload.botSkill = Coop.config.botSkill || 'normal';
      if (Coop.config.botNames && Array.isArray(Coop.config.botNames)) {
        payload.botNames = Coop.config.botNames.slice(0, payload.botCount);
      }
      if (Coop.config.botTeams && Array.isArray(Coop.config.botTeams)) {
        payload.botTeams = Coop.config.botTeams.slice(0, payload.botCount);
      }
    }
    try { Coop.ws.send(JSON.stringify(payload)); } catch (_) {}
    Coop.serverSimActive = true;
    state.serverSimActive = true;
  }
});
document.getElementById('btn-menu').addEventListener('click', () => {
  gameoverScreen.classList.add('hidden');
  menuScreen.classList.remove('hidden');
  document.body.classList.add('menu-mode');
  state.mode = 'menu';
  if (typeof restoreSandboxIfNeeded === 'function') restoreSandboxIfNeeded();
  refreshModeButtons();
});

function startGame() {
  menuScreen.classList.add('hidden');
  gameoverScreen.classList.add('hidden');
  document.body.classList.remove('menu-mode');
  // Visa intro-cutscene första gången (eller om man trycker R-flagga)
  if (!save.introWatched && getMode() === 'story' && !Coop.active) {
    save.introWatched = true; persist();
    runIntroCutscene(() => actuallyStartGame());
    return;
  }
  actuallyStartGame();
}

// INTRO CUTSCENE
const INTRO_FRAMES = [
  { t: 0,    text: 'STOCKHOLM, 2026' },
  { t: 1500, text: 'En man i skuggan tittar på nyheterna...' },
  { t: 3000, text: 'En militär ledare har förrått sitt folk.' },
  { t: 4500, text: 'Han heter Jimmy Mourad.' },
  { t: 6500, text: 'The Penetrator har fått nog.' },
  { t: 8500, text: 'Han tar fram bandanan.' },
  { t: 10000, text: 'Han laddar pistolen.' },
  { t: 11500, text: 'Det här slutar idag.' },
  { t: 13500, text: '' },
];
function runIntroCutscene(onDone) {
  state.mode = 'intro';
  const startTime = performance.now();
  const totalDur = 14000;
  function intoFrame() {
    const elapsed = performance.now() - startTime;
    if (elapsed > totalDur) {
      state.mode = 'menu'; // wird actuallyStartGame som ändrar
      onDone();
      return;
    }
    // Find current frame + nästa för cross-fade
    let cur = INTRO_FRAMES[0], curIdx = 0;
    for (let i = 0; i < INTRO_FRAMES.length; i++) {
      if (INTRO_FRAMES[i].t <= elapsed) { cur = INTRO_FRAMES[i]; curIdx = i; }
    }
    const next = INTRO_FRAMES[curIdx + 1] || INTRO_FRAMES[curIdx];
    // Bakgrund: djup mörk röd radial + scanlines
    const bgGrad = ctx.createRadialGradient(viewW/2, viewH/2, 50, viewW/2, viewH/2, viewW * 0.8);
    bgGrad.addColorStop(0, '#1a0a14');
    bgGrad.addColorStop(0.5, '#0a0508');
    bgGrad.addColorStop(1, '#000');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, viewW, viewH);
    // Scan-lines för cinematic film-look
    ctx.fillStyle = 'rgba(255,255,255,0.025)';
    for (let yy = 0; yy < viewH; yy += 3) ctx.fillRect(0, yy, viewW, 1);
    // Subtilt drift-noise (TV-grain)
    if (elapsed % 50 < 25) {
      ctx.fillStyle = 'rgba(255,255,255,0.015)';
      ctx.fillRect(0, (elapsed * 0.7) % viewH, viewW, 2);
    }
    // The Penetrator silhuett (bli större + sway)
    const t = elapsed / totalDur;
    const sway = Math.sin(elapsed / 800) * 3;
    const cx = viewW/2 + sway, cy = viewH/2 - 50;
    const size = 40 + t * 90;
    // Glödande aura bakom
    const auraGrad = ctx.createRadialGradient(cx, cy + size * 0.3, 10, cx, cy + size * 0.3, size * 2);
    auraGrad.addColorStop(0, 'rgba(180, 30, 30, 0.25)');
    auraGrad.addColorStop(1, 'rgba(180, 30, 30, 0)');
    ctx.fillStyle = auraGrad;
    ctx.fillRect(cx - size * 2, cy - size, size * 4, size * 3);
    // Silhuett-kropp
    ctx.fillStyle = '#0a0a0a';
    ctx.fillRect(cx - size*0.3, cy, size*0.6, size*1.2);
    // Huvud
    ctx.beginPath(); ctx.arc(cx, cy - size*0.3, size*0.3, 0, Math.PI*2); ctx.fill();
    // Rim-light kant runt silhuett
    ctx.strokeStyle = 'rgba(255, 80, 80, 0.4)';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(cx - size*0.3, cy, size*0.6, size*1.2);
    ctx.beginPath(); ctx.arc(cx, cy - size*0.3, size*0.3, 0, Math.PI*2); ctx.stroke();
    // Bandana (röd när nära slutet)
    if (elapsed > 8000) {
      const bandaTime = (elapsed - 8000) / 500;
      const bandaA = Math.min(1, bandaTime);
      ctx.fillStyle = `rgba(170, 24, 24, ${bandaA})`;
      ctx.fillRect(cx - size*0.3, cy - size*0.3, size*0.6, size*0.1);
      ctx.fillStyle = `rgba(220, 60, 60, ${bandaA})`;
      ctx.fillRect(cx - size*0.3, cy - size*0.3, size*0.6, 2);
    }
    // Pistol (sista 3 sek) — med subtil glow
    if (elapsed > 10000) {
      const pistolA = Math.min(1, (elapsed - 10000) / 500);
      ctx.fillStyle = `rgba(20, 20, 20, ${pistolA})`;
      ctx.fillRect(cx + size*0.3, cy + size*0.2, size*0.4, size*0.1);
      // Mynning-glow
      ctx.fillStyle = `rgba(255, 200, 80, ${pistolA * 0.4})`;
      ctx.beginPath();
      ctx.arc(cx + size*0.7, cy + size*0.25, size*0.06, 0, Math.PI * 2);
      ctx.fill();
    }
    // Text med fade-in mellan frames
    const frameProgress = (elapsed - cur.t) / Math.max(50, (next.t - cur.t));
    let textAlpha = 1;
    if (frameProgress < 0.15) textAlpha = frameProgress / 0.15;
    else if (frameProgress > 0.85) textAlpha = (1 - frameProgress) / 0.15;
    textAlpha = Math.max(0, Math.min(1, textAlpha));
    // Text-panel
    if (cur.text) {
      const textY = viewH * 0.85;
      const textW = Math.min(600, viewW - 40);
      ctx.save();
      ctx.globalAlpha = textAlpha;
      // Text-bakgrund (subtilt)
      ctx.fillStyle = 'rgba(0,0,0,0.55)';
      ctx.fillRect((viewW - textW) / 2, textY - 22, textW, 36);
      // Gula linjer ovan/under text
      ctx.fillStyle = 'rgba(255, 213, 74, 0.4)';
      ctx.fillRect((viewW - textW) / 2, textY - 22, textW, 1);
      ctx.fillRect((viewW - textW) / 2, textY + 13, textW, 1);
      // Text
      ctx.fillStyle = '#ffd54a';
      ctx.font = 'italic 22px serif';
      ctx.textAlign = 'center';
      ctx.shadowColor = '#000'; ctx.shadowBlur = 8;
      ctx.fillText(cur.text, viewW/2, textY);
      ctx.shadowBlur = 0;
      ctx.restore();
    }
    // Skip-tip (pulserande)
    const skipPulse = 0.6 + Math.sin(elapsed / 400) * 0.3;
    ctx.fillStyle = `rgba(170, 170, 170, ${skipPulse})`;
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Tryck för att skippa', viewW/2, viewH - 14);
    // Vinjettering kant
    const vGrad = ctx.createRadialGradient(viewW/2, viewH/2, viewW * 0.3, viewW/2, viewH/2, viewW * 0.8);
    vGrad.addColorStop(0, 'rgba(0,0,0,0)');
    vGrad.addColorStop(1, 'rgba(0,0,0,0.7)');
    ctx.fillStyle = vGrad;
    ctx.fillRect(0, 0, viewW, viewH);
    requestAnimationFrame(intoFrame);
  }
  intoFrame();
  // Skip via klick/tap
  const skip = () => {
    state.mode = 'menu';
    canvas.removeEventListener('click', skip);
    canvas.removeEventListener('touchstart', skip);
    onDone();
  };
  canvas.addEventListener('click', skip, { once: true });
  canvas.addEventListener('touchstart', skip, { once: true });
  setTimeout(() => {
    canvas.removeEventListener('click', skip);
    canvas.removeEventListener('touchstart', skip);
  }, totalDur + 100);
}

// Coop-snapshot restore: anropas när user lämnar coop via menyn (utan att vinna/dö),
// så att gold/perks/upgrades återställs (annars persistar coop-state i save).
function restoreCoopIfNeeded() {
  let snap = state && state._coopSnapshot;
  if (!snap) {
    try {
      const raw = localStorage.getItem('penetrator_coop_snapshot');
      if (raw) snap = JSON.parse(raw);
    } catch (_) {}
  }
  if (!snap) return false;
  if (typeof snap.gold === 'number') save.gold = snap.gold;
  if (snap.owned) save.owned = snap.owned;
  if (snap.weaponId) save.weaponId = snap.weaponId;
  if (snap.equipped) save.equipped = snap.equipped;
  if (snap.upgrades) save.upgrades = snap.upgrades;
  if (snap.perks) save.perks = snap.perks;
  if (save.companions && snap.activeCompanion !== undefined) save.companions.active = snap.activeCompanion;
  if (state) state._coopSnapshot = null;
  try { localStorage.removeItem('penetrator_coop_snapshot'); } catch (_) {}
  persist();
  return true;
}

// Sandbox-restore: anropas vid mode-byte / page-init / pre-start för att se till
// att obegränsat-gold + alla-vapen-buff från sandbox INTE läcker till andra modes.
// Persistar snapshot till localStorage så tab-crash inte stjäl save.gold.
function restoreSandboxIfNeeded() {
  let snap = state && state._sandboxSnapshot;
  if (!snap) {
    try {
      const raw = localStorage.getItem('penetrator_sandbox_snapshot');
      if (raw) snap = JSON.parse(raw);
    } catch (_) {}
  }
  if (!snap) return false;
  save.owned = snap.owned || save.owned;
  if (snap.equipped) save.equipped = snap.equipped;
  if (snap.weaponId) save.weaponId = snap.weaponId;
  if (typeof snap.gold === 'number') save.gold = snap.gold;
  if (state) state._sandboxSnapshot = null;
  try { localStorage.removeItem('penetrator_sandbox_snapshot'); } catch (_) {}
  persist();
  return true;
}

function actuallyStartGame() {
  // Göm ALLA overlays så vi faktiskt ser spelet
  menuScreen.classList.add('hidden');
  gameoverScreen.classList.add('hidden');
  if (coopScreen) coopScreen.classList.add('hidden');
  if (coopInitEl) coopInitEl.classList.remove('hidden');
  if (coopLobbyEl) coopLobbyEl.classList.add('hidden');
  document.body.classList.remove('menu-mode');
  // Anti-läck: ALLTID restore sandbox-snapshot innan ny game-start. Garanterar
  // att sandbox-state aldrig leakas in i nästa mode oavsett exit-path.
  restoreSandboxIfNeeded();
  // Coop: fresh-start varje run (ingen pengar/vapen/perks/upgrades carry-over)
  if (Coop.active) {
    // Snapshot bara FÖRSTA gången (om vi inte redan har en sparad).
    // Persist till localStorage så tab-crash mid-coop inte wipear progression.
    if (!state._coopSnapshot) {
      // Försök restore tidigare snapshot från localStorage (tab-crash recovery)
      try {
        const stored = localStorage.getItem('penetrator_coop_snapshot');
        if (stored) state._coopSnapshot = JSON.parse(stored);
      } catch (e) {}
    }
    // SANITY: om coop_snapshot är polluterad av sandbox-state (>10 vapen ELLER
    // gold > 100000) → ignorera den. Annars "restore"ar vi tillbaka till 999999
    // gold + alla-vapen efter coop-spel.
    if (state._coopSnapshot && (
        (state._coopSnapshot.owned && state._coopSnapshot.owned.length > 10) ||
        (state._coopSnapshot.gold > 100000)
    )) {
      state._coopSnapshot = null;
      try { localStorage.removeItem('penetrator_coop_snapshot'); } catch (_) {}
    }
    if (!state._coopSnapshot) {
      state._coopSnapshot = {
        gold: save.gold,
        owned: [...(save.owned || ['fists'])],
        weaponId: save.weaponId,
        equipped: save.equipped,
        upgrades: { ...(save.upgrades || {}) },
        perks: [...(save.perks || [])],
        activeCompanion: save.companions ? save.companions.active : null,
      };
      // Persist immediately så tab-crash inte wipear
      try { localStorage.setItem('penetrator_coop_snapshot', JSON.stringify(state._coopSnapshot)); } catch (e) {}
    }
    // Reset varje coop-run (både första gången och återupprepade gånger).
    // Companions BEHÅLLS — användaren ska se sin köpta pet även i coop.
    // Coop-inventory:
    //  - Story coop: progressiv unlock (start: bara pistol+fists, +1 vapen per wave)
    //  - PvP/endless/bossrush: alla 6 vapen från start
    save.gold = 0;
    if (isCoopStoryMode()) {
      save.owned = coopStoryUnlockedThroughWave(1);
    } else {
      save.owned = ['fists', ...COOP_WEAPONS];
    }
    save.weaponId = 'pistol';
    save.equipped = 'pistol';
    if (save.upgrades) {
      for (const k of Object.keys(save.upgrades)) save.upgrades[k] = 0;
    }
    save.perks = [];
    // KRITISK: _perkSet är cached → hasPerk() returnerar stale true om vi inte
    // rebuildar. Annars läcker glasscannon/revive/headshot/etc in i coop trots
    // att save.perks=[]. Bugg som fick perks/upgrades att "fortfarande gälla" i PvP.
    if (typeof rebuildPerkSet === 'function') rebuildPerkSet();
    // save.companions.active behålls — pets ska följa med in i coop
  }
  state.mode = 'playing';
  state.player = makePlayer();
  // Initial revive: sätt EN gång vid run-start. applyUpgradesToPlayer respekterar
  // sedan p.reviveAvailable (sätter inte tillbaka när redan false från användning).
  state.player.reviveAvailable = hasPerk('revive');
  if (typeof updateFireButtonIcon === 'function') updateFireButtonIcon();
  // Setup custom stages for game mode
  state.customStages = null;
  const mode = getMode();
  if (mode === 'bossrush') {
    state.customStages = buildBossRushStages();
  } else if (mode === 'endless') {
    state.customStages = buildEndlessStages();
  } else if (mode === 'daily') {
    state.customStages = buildDailyStages();
  } else if (mode === 'sandbox') {
    state.customStages = buildSandboxStages();
    // Sandbox: ge alla vapen + obegränsat med pengar TEMPORÄRT.
    // Snapshot persistas till localStorage så tab-crash/page-reload inte
    // läcker 999999 gold + alla-vapen permanent till save (bug fix).
    state._sandboxSnapshot = {
      owned: [...(save.owned || ['fists'])],
      equipped: save.equipped,
      weaponId: save.weaponId,
      gold: save.gold,
    };
    try { localStorage.setItem('penetrator_sandbox_snapshot', JSON.stringify(state._sandboxSnapshot)); } catch (_) {}
    save.owned = [...new Set([...save.owned, ...WEAPONS.map(w => w.id)])];
    save.gold = 999999;  // Sandbox = obegränsat — köp allt
    if (typeof showToast === 'function') showToast('🏖 SANDBOX — alla vapen + obegränsat gold');
  } else if (mode === 'speedrun') {
    state.customStages = STAGES; // samma som story men trackar tid
    state.speedrunStart = performance.now();
  } else if (mode === 'survive') {
    state.customStages = buildSurviveStages();
    state.surviveStart = performance.now();
  } else if (mode === 'truck') {
    state.customStages = buildTruckStages();
  }
  // Rensa speedrun/survive-state om vi startar en ANNAN mode — annars läckte
  // drawModeTimer in stale timer i story/PvP. (Klockan med "00:00.00"-emoji)
  if (mode !== 'speedrun') state.speedrunStart = null;
  if (mode !== 'survive') state.surviveStart = null;
  // Coop story + convoy-tillägg = story-stages + truck-stages (11 totalt)
  if (Coop.active && Coop.config && Coop.config.includeConvoy && mode === 'story') {
    state.customStages = [...STAGES, ...buildTruckStages()];
  }
  // Tutorial första gången
  // Per-mode tutorial: visa tutorial-panel första gången varje mode startas
  // (samma generic content men ger användaren chans att läsa kontroller igen).
  if (!save.tutorialModesSeen) save.tutorialModesSeen = {};
  const _curMode = (typeof getMode === 'function') ? getMode() : 'story';
  const _shouldShowTut = !save.tutorialDone || !save.tutorialModesSeen[_curMode];
  if (_shouldShowTut) {
    save.tutorialModesSeen[_curMode] = true;
    persist();
    document.getElementById('tutorial-overlay').classList.remove('hidden');
  }
  state.enemies = [];
  state.bullets = [];
  state.pickups = [];
  state.particles = [];
  // Rensa ALLA death-state som annars triggar instant-death-loop vid retry
  state.deadBody = null;
  state.deathCamUntil = 0;
  state._lastDamageSource = null;
  state._stageClearShown = false;
  state._stageClearShownForWave = null;
  if (state.player) state.player.spectating = false;
  state.goldThisRun = 0;
  state.killsThisRun = 0;
  state.critsThisRun = 0;
  state.headshotsThisRun = 0;
  state.weaponUsage = {};
  state.killstreak = 0;
  state._coopGameOverFired = false;
  state.hostKills = 0;
  state.hostBossKills = 0;
  state.hostDeaths = 0;
  state.hostRevives = 0;
  state.runStartTime = performance.now();
  spawnCompanion();
  // Reset coop partner stats
  if (Coop.active) {
    for (const [, partner] of Coop.players) {
      partner.kills = 0; partner.bossKills = 0; partner.dmgDealt = 0; partner.deaths = 0; partner.revives = 0; partner.gold = 0;
    }
  }
  startWave(1);
  updateHUD();
}

