function getEndingType() {
  // Multiple endings baserat på run-stats
  const time = (performance.now() - state.runStartTime) / 1000;
  const noShop = (state.shopBoughtThisStage || 0) === 0 && save.gold > 1000;
  const allCheats = save.cheatsActive && Object.values(save.cheatsActive).filter(v => v).length >= 3;
  const fastTime = time < 600;
  const lowKills = (state.killsThisRun || 0) < 50;
  if (allCheats) return { title: 'ULTIMAT GUDOMLIG SLUT', color: '#aa3aff', desc: 'Du har överskridit allt mänskligt. Mourad är bara ett minne.' };
  if (lowKills) return { title: 'PACIFIST-SLUT', color: '#3acaff', desc: 'Få fiender, fast Mourad föll. Du visade nåd där det inte fanns.' };
  if (fastTime) return { title: 'SPEEDRUN-SLUT', color: '#ffd54a', desc: 'Mindre än 10 minuter. Mourads regim föll snabbare än hans gradband.' };
  if (noShop) return { title: 'SVÄRMENS HJÄLTE-SLUT', color: '#5aff5a', desc: 'Inga köp. Bara dig och dina nävar. Mourad såg ditt riktiga jag.' };
  return { title: 'STANDARD-SLUT', color: '#4caf50', desc: 'Mourad är död. Gatorna är dina igen.' };
}

function renderCoopBoardHTML(rows) {
  const trophies = ['🥇','🥈','🥉','🎖','🎖','🎖','🎖','🎖'];
  return `<div id="coop-board-placeholder" style="margin-top:14px;padding:10px;background:rgba(170,58,255,0.1);border:1px solid rgba(170,58,255,0.3);border-radius:8px;">
    <div style="font-weight:bold;color:#aa3aff;margin-bottom:6px;">🏆 CO-OP LEADERBOARD</div>
    ${rows.map((r, i) => {
      const isMe = r.peerId === Coop.myId;
      const isWorst = i === rows.length - 1 && rows.length > 1;
      const tease = isWorst ? ' <span style="color:#ff5a5a;font-size:11px;">(💀 SÄMST)</span>' : '';
      return `<div style="display:flex;justify-content:space-between;font-size:13px;padding:3px 0;${isMe ? 'color:#ffd54a;' : ''}">
        <span>${trophies[i] || '·'} ${r.name}${tease}</span>
        <span><b>${r.kills}</b> kills · 💀 ${r.deaths}${r.bossKills > 0 ? ' · 👑' + r.bossKills : ''}</span>
      </div>`;
    }).join('')}
  </div>`;
}

function endGame(victory) {
  state.mode = victory ? 'victory' : 'gameover';
  // Rensa companion mellan runs så state inte läcker till next-run
  // (spawnCompanion vid actuallyStartGame återskapar om save.companions.active)
  state.companion = null;
  let ending = null;
  if (victory && getMode() === 'story') {
    ending = getEndingType();
    endTitle.textContent = ending.title;
    endTitle.style.color = ending.color;
  } else {
    endTitle.textContent = victory ? 'SEGER!' : 'GAME OVER';
    endTitle.style.color = victory ? '#4caf50' : '#ff5a5a';
  }
  Music.stop();
  if (victory) {
    Audio.victory();
    save.stats.wins = (save.stats.wins || 0) + 1;
    Achievements.unlock('allbosses');
    // Lås upp nästa cheat (max 4)
    const newUnlocks = save.cheatsUnlocked || 0;
    if (newUnlocks < CHEATS.length && getMode() === 'story') {
      save.cheatsUnlocked = newUnlocks + 1;
      const cheat = CHEATS[newUnlocks];
      setTimeout(() => {
        Audio.achievement();
        showAchievementPopup({
          icon: cheat.icon,
          name: 'CHEAT UPPLÅST: ' + cheat.name,
        });
      }, 1500);
    }
  } else {
    Audio.gameOver();
  }
  save.stats.runs = (save.stats.runs || 0) + 1;
  // Detaljerad stats
  const playTime = Math.round((performance.now() - state.runStartTime) / 1000);
  const minutes = Math.floor(playTime / 60);
  const seconds = playTime % 60;
  // Coop leaderboard om tillämpligt. Host bygger FULLSTÄNDIG board och broadcastar.
  // Partners visar placeholder tills host's broadcast anländer (ersätter sen).
  let coopBoard = '';
  if (Coop.active) {
    if (Coop.isHost) {
      const rows = [{
        name: (Coop.myName || 'Host') + ' 👑',
        peerId: Coop.myId,
        kills: state.hostKills || 0,
        bossKills: state.hostBossKills || 0,
        deaths: state.hostDeaths || 0,
      }];
      for (const [pid, p] of Coop.players) {
        rows.push({
          name: p.name || 'Player',
          peerId: pid,
          kills: p.kills || 0,
          bossKills: p.bossKills || 0,
          deaths: p.deaths || 0,
        });
      }
      rows.sort((a, b) => b.kills - a.kills);
      coopBoard = renderCoopBoardHTML(rows);
      // Broadcasta så alla peers får exakt samma board (annars visar partners bara sin egen rad)
      Coop.broadcast({ type: 'event', event: 'coop_board', rows });
    } else {
      // Partner: visa placeholder tills host's coop_board-event anländer
      coopBoard = '<div id="coop-board-placeholder" style="margin-top:14px;padding:10px;background:rgba(170,58,255,0.1);border:1px solid rgba(170,58,255,0.3);border-radius:8px;">' +
        '<div style="font-weight:bold;color:#aa3aff;margin-bottom:6px;">🏆 CO-OP LEADERBOARD</div>' +
        '<div style="font-size:12px;color:#888;text-align:center;padding:8px;">Hämtar leaderboard från host...</div>' +
        '</div>';
    }
  }
  endStats.innerHTML = `
    <div style="text-align:left;display:inline-block;line-height:1.7;">
      Stage: <b>${state.wave}/${getStageCount()}</b> · ${getLevel(state.wave).name}<br>
      Tid: <b>${minutes}:${seconds.toString().padStart(2,'0')}</b><br>
      Kills denna runda: <b>${state.killsThisRun || 0}</b><br>
      Mynt insamlade: <b>💰 ${state.goldThisRun}</b><br>
      Headshots: <b>${state.headshotsThisRun || 0}</b> · Krits: <b>${state.critsThisRun || 0}</b><br>
      Mest använt vapen: <b>${getMostUsedWeapon()}</b><br>
      Total mynt: <b>💰 ${save.gold}</b>
      ${coopBoard}
    </div>
  `;
  // Coop: återställ original save (ingen carry-over från coop)
  if (state._coopSnapshot) {
    const snap = state._coopSnapshot;
    save.gold = snap.gold;
    save.owned = snap.owned;
    save.weaponId = snap.weaponId;
    if (snap.equipped) save.equipped = snap.equipped;
    save.upgrades = snap.upgrades;
    save.perks = snap.perks;
    if (save.companions && snap.activeCompanion !== undefined) save.companions.active = snap.activeCompanion;
    // Återbygg perk-cachen så hasPerk() reflekterar restored save.perks
    if (typeof rebuildPerkSet === 'function') rebuildPerkSet();
    state._coopSnapshot = null;
    // Rensa localStorage-snapshot — coop-run är slutförd, no recovery needed
    try { localStorage.removeItem('penetrator_coop_snapshot'); } catch (e) {}
  }
  // Sandbox: återställ owned/equipped/gold (vi gav alla vapen + obegränsat temporärt)
  if (state._sandboxSnapshot) {
    save.owned = state._sandboxSnapshot.owned;
    save.equipped = state._sandboxSnapshot.equipped;
    save.weaponId = state._sandboxSnapshot.weaponId;
    if (typeof state._sandboxSnapshot.gold === 'number') save.gold = state._sandboxSnapshot.gold;
    state._sandboxSnapshot = null;
    try { localStorage.removeItem('penetrator_sandbox_snapshot'); } catch (_) {}
  }
  gameoverScreen.classList.remove('hidden');
  persist();
}

function getMostUsedWeapon() {
  if (!state.weaponUsage) return '—';
  let best = null, bestC = 0;
  for (const [id, c] of Object.entries(state.weaponUsage)) {
    if (c > bestC) { best = id; bestC = c; }
  }
  return best ? (W_BY_ID[best]?.name || '—') : '—';
}

// Toast
let toastTimer = 0;
let toastText = '';
function showToast(text, sec) {
  toastText = text;
  toastTimer = (typeof sec === 'number' && sec > 0) ? sec : 2.0;
  // Visa även som DOM-toast under HP-baren (smidigare än canvas-text)
  showHudToast(text, (typeof sec === 'number' && sec > 0) ? sec * 1000 : 2000);
}
// HUD-toast: DOM-element under HP-baren. Stackar 3 senaste, fadar ut.
let _hudToastEl = null;
function ensureHudToast() {
  if (_hudToastEl) return _hudToastEl;
  const el = document.createElement('div');
  el.id = 'hud-toast-stack';
  document.body.appendChild(el);
  _hudToastEl = el;
  return el;
}
function showHudToast(text, ms) {
  const stack = ensureHudToast();
  const row = document.createElement('div');
  row.className = 'hud-toast-row';
  row.textContent = text;
  stack.appendChild(row);
  // Max 3 rader — släng äldsta
  while (stack.children.length > 3) stack.removeChild(stack.firstChild);
  setTimeout(() => {
    if (row.parentNode) {
      row.classList.add('fading');
      setTimeout(() => { if (row.parentNode) row.parentNode.removeChild(row); }, 350);
    }
  }, Math.max(800, ms || 2000));
}

// ============================================================
// TDM HUD — team-score banner + kill-feed + match-end screen
// ============================================================
const _tdmHud = document.getElementById('tdm-hud');
const _tdmRedEl = document.getElementById('tdm-red');
const _tdmBlueEl = document.getElementById('tdm-blue');
const _tdmTargetEl = document.getElementById('tdm-target');
const _tdmKillFeedEl = document.getElementById('tdm-killfeed');
const _tdmEndOverlay = document.getElementById('tdm-end-overlay');
const _tdmEndTitle = document.getElementById('tdm-end-title');
const _tdmEndScore = document.getElementById('tdm-end-score');
const _tdmEndStats = document.getElementById('tdm-end-stats');
const _btnTdmBack = document.getElementById('btn-tdm-back');
const _btnTdmRematch = document.getElementById('btn-tdm-rematch');
const _tdmRespawnOverlay = document.getElementById('tdm-respawn-overlay');
const _tdmRespawnNum = document.getElementById('tdm-respawn-num');

// Visar countdown-overlay tills `respawnAt` (server-millis). Stänger sig själv automatiskt.
let _tdmRespawnInterval = null;
function showTdmRespawnCountdown(respawnAt) {
  if (!_tdmRespawnOverlay || !_tdmRespawnNum) return;
  _tdmRespawnOverlay.classList.remove('hidden');
  if (_tdmRespawnInterval) clearInterval(_tdmRespawnInterval);
  const tick = () => {
    const remaining = Math.max(0, respawnAt - Date.now());
    if (remaining <= 0) {
      _tdmRespawnOverlay.classList.add('hidden');
      clearInterval(_tdmRespawnInterval);
      _tdmRespawnInterval = null;
      return;
    }
    _tdmRespawnNum.textContent = String(Math.ceil(remaining / 1000));
  };
  tick();
  _tdmRespawnInterval = setInterval(tick, 100);
}

function showTdmHud(myTeam) {
  if (!_tdmHud) return;
  _tdmHud.classList.remove('hidden');
  if (_tdmRedEl) _tdmRedEl.textContent = 'RED 0';
  if (_tdmBlueEl) _tdmBlueEl.textContent = 'BLUE 0';
  if (_tdmTargetEl) _tdmTargetEl.textContent = String(Coop.tdmTargetKills || 10);
  if (_tdmKillFeedEl) _tdmKillFeedEl.innerHTML = '';
}
function hideTdmHud() {
  if (_tdmHud) _tdmHud.classList.add('hidden');
}
function updateTdmScore(red, blue, target) {
  if (_tdmRedEl) _tdmRedEl.textContent = 'RED ' + red;
  if (_tdmBlueEl) _tdmBlueEl.textContent = 'BLUE ' + blue;
  if (_tdmTargetEl) _tdmTargetEl.textContent = String(target || 10);
}
function addTdmKillFeed(killerName, killerTeam, victimName, victimTeam, weaponName) {
  if (!_tdmKillFeedEl) return;
  const row = document.createElement('div');
  const kColor = killerTeam === 'red' ? '#ff5a5a' : '#5aaaff';
  const vColor = victimTeam === 'red' ? '#ff5a5a' : '#5aaaff';
  row.className = 'tdm-kf-row tdm-kf-' + killerTeam;
  // Neon-kort med team-färgad vänster-border och glow
  const weaponHtml = weaponName ? `<span class="tdm-kf-weapon">· ${escapeHtml(weaponName)}</span>` : '';
  row.innerHTML = `<span class="tdm-kf-killer" style="color:${kColor};">${escapeHtml(killerName)}</span><span class="tdm-kf-arrow">⚡</span><span class="tdm-kf-victim" style="color:${vColor};">${escapeHtml(victimName)}</span>${weaponHtml}`;
  _tdmKillFeedEl.appendChild(row);
  while (_tdmKillFeedEl.children.length > 5) _tdmKillFeedEl.removeChild(_tdmKillFeedEl.firstChild);
  setTimeout(() => {
    if (row.parentNode) {
      row.classList.add('fading');
      setTimeout(() => { if (row.parentNode) row.parentNode.removeChild(row); }, 400);
    }
  }, 4100);
}
function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
}

// Bot-payload-helper: lägger till addBot+botCount+botSkill+botTeam i sim_start-
// payload om host valt bots. DRY för 7 callsites (2 sim_start + 5 rematch).
function applyBotPayload(payload) {
  if (Coop.config && Coop.config.addBot) {
    payload.addBot = true;
    payload.botCount = Coop.config.botCount || 1;
    payload.botSkill = Coop.config.botSkill || 'normal';
    payload.botTeam = Coop.config.botTeam || 'red';
    // Skicka pre-genererade bot-namn så server och lobby visar samma namn
    if (Coop.config.botNames && Array.isArray(Coop.config.botNames)) {
      payload.botNames = Coop.config.botNames.slice(0, payload.botCount);
    }
    // Per-bot-team-override från free-pick (R/B-knappar per bot-rad)
    if (Coop.config.botTeams && Array.isArray(Coop.config.botTeams)) {
      payload.botTeams = Coop.config.botTeams.slice(0, payload.botCount);
    }
  }
  // Skicka team-assignments (shuffle/pick) så server respekterar dem vid sim_start
  if (Coop.teamAssignments && Object.keys(Coop.teamAssignments).length > 0) {
    payload.teams = { ...Coop.teamAssignments };
  }
  return payload;
}
function showTdmEndScreen(winner, redKills, blueKills, stats, teams) {
  if (!_tdmEndOverlay) return;
  hideTdmHud();
  // Vinnar-färg-flash innan overlay slides in (game-feel polish)
  const winColor = winner === 'red' ? 'rgba(255,90,90,0.4)' : 'rgba(90,170,255,0.4)';
  const flash = document.createElement('div');
  flash.style.cssText = `position:fixed;inset:0;background:${winColor};z-index:199;pointer-events:none;animation:tdmEndFlash 1s forwards;`;
  document.body.appendChild(flash);
  setTimeout(() => { if (flash.parentNode) flash.parentNode.removeChild(flash); }, 1100);
  _tdmEndOverlay.classList.remove('hidden');
  // Rematch-knapp: bara host får trycka (de andra ser host väljer-text)
  if (_btnTdmRematch) {
    _btnTdmRematch.classList.toggle('hidden', !Coop.isHost);
  }
  if (_tdmEndTitle) {
    _tdmEndTitle.textContent = winner === 'red' ? 'RED WINS' : 'BLUE WINS';
    _tdmEndTitle.style.color = winner === 'red' ? '#ff5a5a' : '#5aaaff';
  }
  if (_tdmEndScore) _tdmEndScore.textContent = redKills + ' — ' + blueKills;
  // Hero-stat: MVP = mest kills
  const tdmHeroEl = document.getElementById('tdm-end-hero');
  if (tdmHeroEl && stats && stats.length) {
    const mvp = stats.slice().sort((a, b) => (b.kills || 0) - (a.kills || 0))[0];
    if (mvp) {
      const mvpName = mvp.peerId === Coop.myId ? (Coop.myName || 'Du') : ((Coop.players.get(mvp.peerId) && Coop.players.get(mvp.peerId).name) || 'Spelare');
      const mvpKd = mvp.deaths > 0 ? (mvp.kills / mvp.deaths).toFixed(2) : (mvp.kills || 0) + '.00';
      tdmHeroEl.innerHTML = '🏆 MVP: <span style="color:#fff;">' + escapeHtml(mvpName) + '</span> · ' + (mvp.kills || 0) + ' kills · K/D ' + mvpKd;
    }
  }
  if (_tdmEndStats) {
    const sortedStats = (stats || []).slice().sort((a, b) => b.kills - a.kills);
    _tdmEndStats.innerHTML = sortedStats.map(s => {
      const name = (s.peerId === Coop.myId)
        ? (Coop.myName || 'Du')
        : (Coop.players.get(s.peerId) && Coop.players.get(s.peerId).name) || 'Spelare';
      const tColor = s.team === 'red' ? '#ff5a5a' : '#5aaaff';
      const isMe = s.peerId === Coop.myId ? ' (du)' : '';
      return `<div style="display:flex;justify-content:space-between;padding:4px 0;border-bottom:1px solid rgba(255,255,255,0.05);">
        <span style="color:${tColor};font-weight:700;">${escapeHtml(name)}${isMe}</span>
        <span style="color:#ddd;"><b>${s.kills}</b> kills · 💀 ${s.deaths}</span>
      </div>`;
    }).join('') || '<div style="color:#888;">Inga stats</div>';
  }
}
if (_btnTdmBack) {
  _btnTdmBack.addEventListener('click', () => {
    if (_tdmEndOverlay) _tdmEndOverlay.classList.add('hidden');
    // Host stoppar simmen för alla; non-hosts disconnectar bara sig själva
    if (Coop.isHost && Coop.ws && Coop.ws.readyState === 1) {
      try { Coop.ws.send(JSON.stringify({ type: 'sim_stop' })); } catch (e) {}
    }
    state.tdmActive = false;
    Coop.tdmActive = false;
    Coop.serverSimActive = false;
    state.serverSimActive = false;
    state.mode = 'menu';
    if (typeof restoreSandboxIfNeeded === 'function') restoreSandboxIfNeeded();
    if (typeof Music !== 'undefined' && Music.stop) Music.stop();
    document.body.classList.add('menu-mode');
    if (typeof menuScreen !== 'undefined') menuScreen.classList.remove('hidden');
    Coop.disconnect();
  });
}
if (_btnTdmRematch) {
  _btnTdmRematch.addEventListener('click', () => {
    if (!Coop.isHost) return;
    if (_tdmEndOverlay) _tdmEndOverlay.classList.add('hidden');
    // Stoppa nuvarande sim + starta ny TDM med samma config (members.size oförändrat)
    if (Coop.ws && Coop.ws.readyState === 1) {
      try {
        Coop.ws.send(JSON.stringify({ type: 'sim_stop' }));
        // Liten paus så server hinner stoppa innan nytt start (annars race)
        setTimeout(() => {
          if (!Coop.ws || Coop.ws.readyState !== 1) return;
          Coop.ws.send(JSON.stringify(applyBotPayload({
            type: 'sim_start',
            wave: 1,
            difficulty: Coop.config.difficulty || 'veteran',
            ngpLevel: 0,
            mode: Coop.config.mode || 'story',
            tdm: true,
            tdmTargetKills: Coop.config.tdmTargetKills || 10,
          })));
        }, 400);
      } catch (e) {}
    }
  });
}

