  stageState.decorations.push({ x: W * 0.82, y: H/2, kind: 'big_warning_sign', text: 'KEEP CLEAR' });
  stageState.decorations.push({ x: W/2, y: H * 0.85, kind: 'metal_sign', text: 'AMMO DEPOT — DEPÅ 7', red: true });
  // Gula säkerhetsstreck
