      ctx.beginPath(); ctx.moveTo(p.r * 0.7, 0); ctx.lineTo(p.r * 1.7, 0); ctx.stroke();
      ctx.lineWidth = 8;
      ctx.beginPath(); ctx.moveTo(p.r * 1.7, 0); ctx.lineTo(p.r * 2.3, 0); ctx.stroke();
      // Tape-grepp (svart spiral)
      ctx.strokeStyle = flash ? '#fff' : '#1a1a1a';
      ctx.lineWidth = 1;
